function Select-WimImageIndex {
 param(
 [Parameter(Mandatory = $true)]
 [string]$ImagePath
 )

 $images = @(Get-WindowsImage -ImagePath $ImagePath -ErrorAction Stop)

 if ($images.Count -eq 0) {
 throw "No image indexes were found in: $ImagePath"
 }

 if ($images.Count -eq 1) {
 $selectedIndex = [int]$images[0].ImageIndex
 Write-Host "Only one image index was found. Automatically selecting Index: $selectedIndex"
 return $selectedIndex
 }

 Write-Host "Multiple image indexes were found. Please select the index you want to use."

 foreach ($image in $images) {
 Write-Host ("Index: {0} - {1}" -f $image.ImageIndex, $image.ImageName)
 }

 do {
 $selectedIndex = Read-Host "Please enter the image index"

 $parsedIndex = 0
 $validNumber = [int]::TryParse([string]$selectedIndex, [ref]$parsedIndex)
 $validIndex = if ($validNumber) { $images | Where-Object { $_.ImageIndex -eq $parsedIndex } } else { $null }

 if ($null -eq $validIndex) {
 Write-Warning "Invalid index. Please enter one of the indexes listed above."
 }
 }
 until ($null -ne $validIndex)

 return [int]$selectedIndex
}


