# ============================================================================
# ROBUST OFFLINE-IMAGE HELPERS
# ============================================================================
# These helpers prevent stale DISM mount registrations and registry hive locks
# from allowing the script to continue after a failed operation.
# ============================================================================

function Invoke-RegUnloadWithRetry {
 param(
 [Parameter(Mandatory = $true)]
 [string]$HiveName,
 [int]$Attempts = 30,
 [int]$DelayMilliseconds = 500
 )

 $hivePath = "HKLM\$HiveName"

 for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
 & reg.exe unload $hivePath > $null 2>&1
 $exitCode = $LASTEXITCODE

 if ($exitCode -eq 0) {
 return $true
 }

 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 Start-Sleep -Milliseconds $DelayMilliseconds
 }

 return $false
}


# ============================================================================
# NATIVE REGISTRY HIVE SAVE / PHYSICAL COMPACTION
# ============================================================================
function Get-Micro11NativeRegistryApi {
 if ($script:Micro11NativeRegistryApi) {
 return $script:Micro11NativeRegistryApi
 }

 $assemblyName = New-Object System.Reflection.AssemblyName('Micro11.NativeRegistry.Dynamic')
 $assembly = [AppDomain]::CurrentDomain.DefineDynamicAssembly(
 $assemblyName,
 [System.Reflection.Emit.AssemblyBuilderAccess]::Run
 )
 $module = $assembly.DefineDynamicModule('Micro11.NativeRegistry.Dynamic.Module')

 $typeAttributes = [System.Reflection.TypeAttributes]::Public -bor
 [System.Reflection.TypeAttributes]::Sealed -bor
 [System.Reflection.TypeAttributes]::Abstract
 $typeBuilder = $module.DefineType('Micro11.NativeRegistry.Win32', $typeAttributes)

 function Add-Micro11PInvokeMethod {
 param(
 [Parameter(Mandatory = $true)] [string]$Name,
 [Parameter(Mandatory = $true)] [string]$Dll,
 [Parameter(Mandatory = $true)] [Type]$ReturnType,
 [AllowEmptyCollection()] [Type[]]$ParameterTypes = [Type[]]@(),
 [System.Runtime.InteropServices.CharSet]$CharSet = [System.Runtime.InteropServices.CharSet]::Unicode
 )

 # PowerShell can treat a positional @() as an omitted argument during
 # parameter binding. Reflection.Emit, however, must receive an actual
 # Type[] (including a zero-length Type[]) for a zero-argument Win32 API.
 # Normalize it here so DefinePInvokeMethod always receives a real array.
 if ($null -eq $ParameterTypes) {
 $ParameterTypes = [Type[]]@()
 } else {
 $ParameterTypes = [Type[]]$ParameterTypes
 }

 $attrs = [System.Reflection.MethodAttributes]::Public -bor
 [System.Reflection.MethodAttributes]::Static -bor
 [System.Reflection.MethodAttributes]::PinvokeImpl

 $method = $typeBuilder.DefinePInvokeMethod(
 $Name,
 $Dll,
 $attrs,
 [System.Reflection.CallingConventions]::Standard,
 $ReturnType,
 $ParameterTypes,
 [System.Runtime.InteropServices.CallingConvention]::Winapi,
 $CharSet
 )
 $method.SetImplementationFlags(
 $method.GetMethodImplementationFlags() -bor
 [System.Reflection.MethodImplAttributes]::PreserveSig
 )
 }

 $intPtrByRef = [IntPtr].MakeByRefType()

 Add-Micro11PInvokeMethod -Name 'GetCurrentProcess' -Dll 'kernel32.dll' -ReturnType ([IntPtr]) -ParameterTypes ([Type[]]@()) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'CloseHandle' -Dll 'kernel32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([IntPtr])) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'OpenProcessToken' -Dll 'advapi32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([IntPtr],[uint32],$intPtrByRef)) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'LookupPrivilegeValueW' -Dll 'advapi32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([string],[string],[IntPtr]))
 Add-Micro11PInvokeMethod -Name 'AdjustTokenPrivileges' -Dll 'advapi32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([IntPtr],[bool],[IntPtr],[uint32],[IntPtr],[IntPtr])) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'RegOpenKeyExW' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr],[string],[uint32],[uint32],$intPtrByRef))
 Add-Micro11PInvokeMethod -Name 'RegDeleteTreeW' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr],[string])) -CharSet ([System.Runtime.InteropServices.CharSet]::Unicode)
 Add-Micro11PInvokeMethod -Name 'RegSaveKeyExW' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr],[string],[IntPtr],[uint32]))
 Add-Micro11PInvokeMethod -Name 'RegCloseKey' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr])) -CharSet ([System.Runtime.InteropServices.CharSet]::None)

 $script:Micro11NativeRegistryApi = $typeBuilder.CreateType()
 return $script:Micro11NativeRegistryApi
}

function Invoke-Micro11EnableBackupPrivilege {
 param([Parameter(Mandatory = $true)] [Type]$Api)

 # The nuclear offline-hive deletion needs more than SeBackupPrivilege.
 # SeTakeOwnershipPrivilege and SeRestorePrivilege are enabled so protected
 # Registry keys can have their owner/DACL changed before recursive deletion.
 $privileges = @('SeBackupPrivilege','SeTakeOwnershipPrivilege','SeRestorePrivilege')
 $token = [IntPtr]::Zero

 try {
 $process = $Api.GetMethod('GetCurrentProcess').Invoke($null, @())
 $openArgs = [object[]]@([IntPtr]$process, [uint32]0x28, [IntPtr]::Zero)
 $opened = [bool]$Api.GetMethod('OpenProcessToken').Invoke($null, $openArgs)
 $token = [IntPtr]$openArgs[2]
 if (-not $opened -or $token -eq [IntPtr]::Zero) {
 throw 'OpenProcessToken failed. Run the script from an elevated PowerShell session.'
 }

 foreach ($privilege in $privileges) {
 $luid = [Runtime.InteropServices.Marshal]::AllocHGlobal(8)
 $tp = [Runtime.InteropServices.Marshal]::AllocHGlobal(16)
 try {
 [Runtime.InteropServices.Marshal]::WriteInt64($luid, 0, 0)
 $lookupArgs = [object[]]@($null, $privilege, $luid)
 $lookedUp = [bool]$Api.GetMethod('LookupPrivilegeValueW').Invoke($null, $lookupArgs)
 if (-not $lookedUp) { throw "LookupPrivilegeValueW failed for $privilege." }

 for ($i = 0; $i -lt 16; $i += 4) {
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, $i, 0)
 }
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 0, 1)
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 4, [Runtime.InteropServices.Marshal]::ReadInt32($luid, 0))
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 8, [Runtime.InteropServices.Marshal]::ReadInt32($luid, 4))
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 12, 0x2)

 $adjustArgs = [object[]]@($token, $false, $tp, [uint32]0, [IntPtr]::Zero, [IntPtr]::Zero)
 $adjusted = [bool]$Api.GetMethod('AdjustTokenPrivileges').Invoke($null, $adjustArgs)
 if (-not $adjusted) { throw "AdjustTokenPrivileges failed for $privilege." }
 }
 finally {
 if ($tp -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($tp) }
 if ($luid -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($luid) }
 }
 }
 }
 finally {
 if ($token -ne [IntPtr]::Zero) {
 [void]$Api.GetMethod('CloseHandle').Invoke($null, [object[]]@($token))
 }
 }
}

function Invoke-NativeRegistryHiveSaveLatest {
 param(
 [Parameter(Mandatory = $true)] [string]$HiveName,
 [Parameter(Mandatory = $true)] [string]$DestinationPath
 )

 Remove-Item -LiteralPath $DestinationPath -Force -ErrorAction SilentlyContinue

 $api = $null
 $key = [IntPtr]::Zero

 try {
 $api = Get-Micro11NativeRegistryApi
 Invoke-Micro11EnableBackupPrivilege -Api $api

 $hklm = [IntPtr]([int64]-2147483646) # HKEY_LOCAL_MACHINE / 0xFFFFFFFF80000002
 $samDesired = [uint32](0x20019 -bor 0x0100) # KEY_READ | KEY_WOW64_64KEY
 $openArgs = [object[]]@($hklm, [string]$HiveName, [uint32]0, $samDesired, [IntPtr]::Zero)
 $openResult = [int]$api.GetMethod('RegOpenKeyExW').Invoke($null, $openArgs)
 $key = [IntPtr]$openArgs[4]
 if ($openResult -ne 0 -or $key -eq [IntPtr]::Zero) {
 throw "RegOpenKeyExW failed for HKLM\$HiveName (Win32 code $openResult)."
 }

 # REG_LATEST_FORMAT = 2. The destination must not already exist.
 $saveArgs = [object[]]@($key, $DestinationPath, [IntPtr]::Zero, [uint32]2)
 $saveResult = [int]$api.GetMethod('RegSaveKeyExW').Invoke($null, $saveArgs)
 if ($saveResult -ne 0) {
 throw "RegSaveKeyExW(REG_LATEST_FORMAT) failed for HKLM\$HiveName (Win32 code $saveResult)."
 }

 if (-not (Test-Path -LiteralPath $DestinationPath -PathType Leaf)) {
 throw "RegSaveKeyExW reported success but did not create $DestinationPath."
 }

 Write-Host " Native in-process RegSaveKeyEx(REG_LATEST_FORMAT) succeeded for HKLM\$HiveName." -ForegroundColor Green
 return 0
 }
 catch {
 Write-Warning ("Native RegSaveKeyExW compaction failed for HKLM\{0}: {1}" -f $HiveName, $_.Exception.Message)
 }
 finally {
 if ($null -ne $api -and $key -ne [IntPtr]::Zero) {
 try { [void]$api.GetMethod('RegCloseKey').Invoke($null, [object[]]@($key)) } catch {}
 }
 }

 # Safe fallback only. This keeps the script functional on unusual hosts,
 # but the log explicitly reports that maximum physical compaction was not
 # available instead of pretending REG.EXE SAVE is equivalent.
 Remove-Item -LiteralPath $DestinationPath -Force -ErrorAction SilentlyContinue
 Write-Warning "Falling back to reg.exe SAVE for HKLM\$HiveName. Maximum physical hive compaction was not available."
 & reg.exe save "HKLM\$HiveName" $DestinationPath /y 2>&1 | ForEach-Object {
 if ($_ -and $_.ToString().Trim()) { Write-Warning $_.ToString() }
 }
 return $LASTEXITCODE
}

function Invoke-DismUnmountDiscardIfMounted {
 param(
 [Parameter(Mandatory = $true)]
 [string]$MountDir
 )

 $normalizedMountDir = [System.IO.Path]::GetFullPath($MountDir).TrimEnd('\')
 $mountedInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
 $mountedCode = $LASTEXITCODE
 $mountedText = ($mountedInfo -join [Environment]::NewLine)

 if ($mountedCode -ne 0) {
  Write-Warning "DISM /Get-MountedWimInfo returned exit code $mountedCode. Running DISM mount-point cleanup..."
  & dism.exe /English /Cleanup-Mountpoints 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $cleanupMountpointsCode = $LASTEXITCODE
  & dism.exe /English /Cleanup-Wim 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $cleanupWimCode = $LASTEXITCODE
  Start-Sleep -Seconds 2
  $mountedInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
  $mountedCode = $LASTEXITCODE
  $mountedText = ($mountedInfo -join [Environment]::NewLine)
 }

 if ($mountedText -match [regex]::Escape($MountDir)) {
  Write-Warning "DISM reports an image mounted at $MountDir. Attempting recovery before discard..."

  # First try the normal DISM recovery path.
  & dism.exe /English /Remount-Image "/MountDir:$MountDir" 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $remountCode = $LASTEXITCODE
  if ($remountCode -eq 0) {
   Write-Host "DISM mount point remounted successfully; proceeding with discard..." -ForegroundColor Yellow
   Start-Sleep -Seconds 1
  }
  else {
   Write-Warning "DISM /Remount-Image returned exit code $remountCode. Continuing with cleanup/discard recovery."
  }

  & dism.exe /English /Unmount-Image "/MountDir:$MountDir" /Discard 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $unmountCode = $LASTEXITCODE

  if ($unmountCode -ne 0) {
   Write-Warning "DISM discard unmount failed for $MountDir (exit code $unmountCode). Running /Cleanup-Mountpoints and /Cleanup-Wim, then retrying..."

   & dism.exe /English /Cleanup-Mountpoints 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
   $cleanupMountpointsCode = $LASTEXITCODE
   & dism.exe /English /Cleanup-Wim 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
   $cleanupWimCode = $LASTEXITCODE
   Start-Sleep -Seconds 2

   & dism.exe /English /Unmount-Image "/MountDir:$MountDir" /Discard 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
   $retryCode = $LASTEXITCODE

   $verifyInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
   $verifyText = ($verifyInfo -join [Environment]::NewLine)

   if (($retryCode -ne 0) -and ($verifyText -match [regex]::Escape($MountDir))) {
    # 0xC1420117 means DISM could not completely unmount the directory. At
    # startup this can be an orphaned WIMMount registration left by a crashed
    # previous run. Do NOT delete the whole WIMMount registry tree: locate only
    # the registry entry whose Mount Path exactly matches our mount directory.
    Write-Warning "DISM still reports $MountDir after discard/cleanup. Checking the WIMMount registry for an orphaned entry matching this mount only..."

    $wimMountRoot = 'Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\WIMMount\Mounted Images'
    $removedOrphan = $false

    if (Test-Path -LiteralPath $wimMountRoot) {
     foreach ($entry in @(Get-ChildItem -LiteralPath $wimMountRoot -ErrorAction SilentlyContinue)) {
      try {
       $props = Get-ItemProperty -LiteralPath $entry.PSPath -ErrorAction Stop
       $entryMountPath = [string]$props.'Mount Path'
       if ([string]::IsNullOrWhiteSpace($entryMountPath)) { continue }

       try {
        $normalizedEntryPath = [System.IO.Path]::GetFullPath($entryMountPath).TrimEnd('\')
       }
       catch {
        $normalizedEntryPath = $entryMountPath.TrimEnd('\')
       }

       if ([string]::Equals($normalizedEntryPath, $normalizedMountDir, [System.StringComparison]::OrdinalIgnoreCase)) {
        Write-Warning "Removing orphaned WIMMount registration for ${MountDir}: $($entry.PSChildName)"
        Remove-Item -LiteralPath $entry.PSPath -Recurse -Force -ErrorAction Stop
        $removedOrphan = $true
       }
      }
      catch {
       Write-Warning "Could not inspect/remove WIMMount entry '$($entry.PSPath)': $($_.Exception.Message)"
      }
     }
    }

    if ($removedOrphan) {
     Start-Sleep -Seconds 1
     & dism.exe /English /Cleanup-Mountpoints 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
     $cleanupMountpointsCode = $LASTEXITCODE
     & dism.exe /English /Cleanup-Wim 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
     $cleanupWimCode = $LASTEXITCODE
     Start-Sleep -Seconds 2

     $postRegistryInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
     $postRegistryText = ($postRegistryInfo -join [Environment]::NewLine)

     if ($postRegistryText -match [regex]::Escape($MountDir)) {
      throw "A stale DISM mount exists at $MountDir after targeted WIMMount registry recovery. Initial exit code: $unmountCode; Remount exit code: $remountCode; Cleanup-Mountpoints exit code: $cleanupMountpointsCode; Cleanup-Wim exit code: $cleanupWimCode; retry exit code: $retryCode"
     }
    }
    else {
     throw "A stale DISM mount exists at $MountDir and could not be discarded. No orphaned WIMMount registry entry matched this mount. Initial exit code: $unmountCode; Remount exit code: $remountCode; Cleanup-Mountpoints exit code: $cleanupMountpointsCode; Cleanup-Wim exit code: $cleanupWimCode; retry exit code: $retryCode"
    }
   }
  }
 }

 Start-Sleep -Seconds 1
 $finalInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
 $finalText = ($finalInfo -join [Environment]::NewLine)
 if ($finalText -match [regex]::Escape($MountDir)) {
  throw "DISM still reports $MountDir as mounted after all automatic recovery attempts."
 }
}

function Clear-EmptyMountDirectory {
 param(
 [Parameter(Mandatory = $true)]
 [string]$MountDir
 )

 Invoke-DismUnmountDiscardIfMounted -MountDir $MountDir

 if (Test-Path -LiteralPath $MountDir) {
 $items = @(Get-ChildItem -LiteralPath $MountDir -Force -ErrorAction SilentlyContinue)
 if ($items.Count -gt 0) {
 Write-Host "Clearing residual files from mount directory: $MountDir"
 foreach ($item in $items) {
 Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
 }
 }
 }
 else {
 New-Item -ItemType Directory -Path $MountDir -Force -ErrorAction Stop | Out-Null
 }
}

function Wait-ForFileUnlock {
 param(
 [Parameter(Mandatory = $true)]
 [string]$Path,
 [int]$Attempts = 30,
 [int]$DelayMilliseconds = 500
 )

 for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
 if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
 return $true
 }

 try {
 $stream = [System.IO.File]::Open(
 $Path,
 [System.IO.FileMode]::Open,
 [System.IO.FileAccess]::ReadWrite,
 [System.IO.FileShare]::None
 )
 $stream.Dispose()
 return $true
 }
 catch {
 Start-Sleep -Milliseconds $DelayMilliseconds
 }
 }

 return $false
}
$hostArchitecture = $Env:PROCESSOR_ARCHITECTURE
New-Item -ItemType Directory -Force -Path "$mainOSDrive\Micro 11 Barebones\sources" >$null

# Robust ISO/source-drive input. Accepts E, E:, E:\, or a mounted-media path
do {
 $DriveInput = (Read-Host "Please enter the drive letter for the Windows 11 image").Trim()
 if ([string]::IsNullOrWhiteSpace($DriveInput)) {
 Write-Warning "No drive was entered. Please enter a mounted ISO drive such as E or E:."
 $DriveLetter = $null
 continue
 }

 # Accept a drive-letter form (E, E:, E:\).
 if ($DriveInput -match '^[A-Za-z]:?\\?$') {
 $DriveLetter = $DriveInput.Substring(0,1).ToUpperInvariant() + ':'
 }
 elseif ($DriveInput -match '^[A-Za-z]$') {
 $DriveLetter = $DriveInput.ToUpperInvariant() + ':'
 }
 else {
 Write-Warning "Invalid drive input '$DriveInput'. Enter only a mounted drive such as E or E:."
 $DriveLetter = $null
 continue
 }

 if (-not (Test-Path -LiteralPath ($DriveLetter + '\\') -PathType Container)) {
 Write-Warning "Drive $DriveLetter is not available. Mount the Windows ISO and try again."
 $DriveLetter = $null
 }
} while ($null -eq $DriveLetter)

# Validate the Windows installation media.
$sourceInstallWim = Join-Path $DriveLetter 'sources\install.wim'
$sourceInstallEsd = Join-Path $DriveLetter 'sources\install.esd'

if (-not (Test-Path -LiteralPath (Join-Path $DriveLetter 'sources\boot.wim') -PathType Leaf)) {
 throw "boot.wim was not found in: $DriveLetter\sources. Check that the mounted ISO is Windows installation media."
}

if ((Test-Path -LiteralPath $sourceInstallWim -PathType Leaf) -and (Test-Path -LiteralPath $sourceInstallEsd -PathType Leaf)) {
 # Prefer install.wim when both files exist.
 $sourceImagePath = $sourceInstallWim
}
elseif (Test-Path -LiteralPath $sourceInstallWim -PathType Leaf) {
 $sourceImagePath = $sourceInstallWim
}
elseif (Test-Path -LiteralPath $sourceInstallEsd -PathType Leaf) {
 $sourceImagePath = $sourceInstallEsd
}
else {
 throw "Neither install.wim nor install.esd was found in: $DriveLetter\sources"
}

Write-Host "Using source image: $sourceImagePath"
$index = Select-WimImageIndex -ImagePath $sourceImagePath
 # Determine the architecture of the selected Windows image.
 # Query the selected image directly first. Different DISM versions expose
 # architecture as x64/amd64, arm64, or numeric architecture IDs.
 $architecture = $null
 $rawArchitecture = $null

 try {
     $selectedImageInfo = Get-WindowsImage -ImagePath $sourceImagePath -Index $index -ErrorAction Stop
     if ($selectedImageInfo) {
         $rawArchitecture = [string]$selectedImageInfo.Architecture
     }
 } catch {
     $selectedImageInfo = $null
 }

 switch -Regex ($rawArchitecture) {
     '(?i)^(x64|amd64|9)$' { $architecture = 'amd64'; break }
     '(?i)^(arm64|12)$' { $architecture = 'arm64'; break }
     '(?i)^(x86|i386|0)$' { $architecture = 'x86'; break }
 }

 if (-not $architecture) {
     $dismInfo = & dism.exe /English /Get-WimInfo /WimFile:$sourceImagePath /Index:$index 2>&1
     $dismText = $dismInfo -join [Environment]::NewLine
     $archMatch = [regex]::Match($dismText, '(?im)^\s*Architecture\s*:\s*(x64|amd64|arm64|x86|i386|9|12|0)\s*$')
     if ($archMatch.Success) {
         $rawArchitecture = $archMatch.Groups[1].Value
         switch -Regex ($rawArchitecture) {
             '(?i)^(x64|amd64|9)$' { $architecture = 'amd64'; break }
             '(?i)^(arm64|12)$' { $architecture = 'arm64'; break }
             '(?i)^(x86|i386|0)$' { $architecture = 'x86'; break }
         }
     }
 }

 if (-not $architecture) {
     $allImageInfo = @(Get-WindowsImage -ImagePath $sourceImagePath -ErrorAction SilentlyContinue |
         Where-Object { [int]$_.ImageIndex -eq [int]$index } | Select-Object -First 1)
     if ($allImageInfo.Count -gt 0) {
         foreach ($propertyName in 'Architecture','ArchitectureName','Platform') {
             $prop = $allImageInfo[0].PSObject.Properties[$propertyName]
             if ($prop) {
                 $candidate = [string]$prop.Value
                 if ($candidate -match '(?i)^(x64|amd64|9)$') { $architecture = 'amd64'; break }
                 if ($candidate -match '(?i)^(arm64|12)$') { $architecture = 'arm64'; break }
                 if ($candidate -match '(?i)^(x86|i386|0)$') { $architecture = 'x86'; break }
             }
         }
     }
 }

 if (-not $architecture) {
     throw "Could not determine the architecture of selected Windows image Index $index. DISM/Get-WindowsImage did not return a recognized architecture."
 }

 Write-Host "Architecture: $architecture"

# Architecture compatibility flags used by architecture-sensitive cleanup blocks.
$isAmd64 = ($architecture -eq 'amd64')
$isArm64 = ($architecture -eq 'arm64')
$isX86   = ($architecture -eq 'x86')

if (-not ($isAmd64 -or $isArm64 -or $isX86)) {
    throw "Unsupported Windows image architecture: $architecture"
}

# Architecture-aware cleanup guard.
# Keep the cleanup/compaction engines architecture-neutral while gating
# explicit architecture-specific payload paths.
function Test-Micro11CleanupPathForArchitecture {
    param([Parameter(Mandatory=$true)][string]$Path)

    if ($isArm64 -and $Path -match '(?i)(?:_amd64_|\\GAC_64\\|\\Framework64\\)') { return $false }
    if ($isAmd64 -and $Path -match '(?i)(?:_arm64_|\\GAC_Arm64\\|\\FrameworkArm64\\)') { return $false }
    return $true
}
# Silenced per-directory WinSxS copy message: "Copying Windows image..."
Copy-Item -Path "$DriveLetter\*" -Destination "$mainOSDrive\Micro 11 Barebones" -Recurse -Force | Out-Null

$wimFilePath = Join-Path $mainOSDrive 'Micro 11 Barebones\sources\install.wim'
$destinationEsdPath = Join-Path $mainOSDrive 'Micro 11 Barebones\sources\install.esd'

if ($sourceImagePath -eq $sourceInstallEsd) {
 Write-Host ''
 Write-Host "Converting the selected install.esd image to install.wim. This may take a while..."

 if (Test-Path $wimFilePath) {
 Remove-Item -LiteralPath $wimFilePath -Force -ErrorAction Stop
 }

 & DISM /Export-Image `
 "/SourceImageFile:$sourceInstallEsd" `
 "/SourceIndex:$index" `
 "/DestinationImageFile:$wimFilePath" `
 /Compress:max /CheckIntegrity

 if ($LASTEXITCODE -ne 0) {
 throw "DISM failed to export install.esd to install.wim. Exit code: $LASTEXITCODE"
 }

 # The exported WIM contains only the selected image, so its index is always 1.
 $index = 1

 if (Test-Path $destinationEsdPath) {
 try {
 Set-ItemProperty -LiteralPath $destinationEsdPath -Name IsReadOnly -Value $false -ErrorAction SilentlyContinue
 Remove-Item -LiteralPath $destinationEsdPath -Force -ErrorAction SilentlyContinue
 }
 catch {
 Write-Warning "Could not remove install.esd: $($_.Exception.Message)"
 }
 }
}
else {
 # The source was already install.wim. Keep the selected index.
 if (-not (Test-Path $wimFilePath)) {
 throw "install.wim was not copied to: $wimFilePath"
 }
}


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "INSTALL.WIM - PREPARATION AND MOUNTING" -ForegroundColor Yellow
Write-Host "  [Stage 1.1] Validate working files and image source" -ForegroundColor Cyan
Write-Host "  [Stage 1.2] Prepare temporary working directories" -ForegroundColor Green
Write-Host "  [Stage 1.3] Mount INSTALL.WIM" -ForegroundColor Green
Write-Host "  [Stage 1.4] Verify mounted image and servicing paths" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Copy complete!"
# Performance optimization: cosmetic fixed delay removed.
# Clear-Host suppressed so section headers remain visible.

if (-not (Test-Path $wimFilePath)) {
 throw "The working install.wim was not found: $wimFilePath"
}

Write-Host "Getting image information:"
& DISM /English "/Get-WimInfo" "/WimFile:$wimFilePath"

if ($LASTEXITCODE -ne 0) {
 throw "DISM could not read the working install.wim. Exit code: $LASTEXITCODE"
}

Write-Host "Using Image Index: $index"
Write-Host "Mounting Windows image. This may take a while."

& takeown /F $wimFilePath >$null 2>&1
$takeownWimExitCode = $LASTEXITCODE
if ($takeownWimExitCode -ne 0) {
    Write-Warning "Could not take ownership of install.wim (takeown.exe exit code $takeownWimExitCode). Continuing, since the file may already be writable."
}

& icacls $wimFilePath /grant "$($adminGroup.Value):(F)" >$null 2>&1
$icaclsWimExitCode = $LASTEXITCODE
if ($icaclsWimExitCode -ne 0) {
    Write-Warning "Could not grant Administrators full control on install.wim (icacls.exe exit code $icaclsWimExitCode). Continuing, since the file may already be writable."
}

try {
 Set-ItemProperty -LiteralPath $wimFilePath -Name IsReadOnly -Value $false -ErrorAction Stop
}
catch {
 Write-Warning "Could not change the read-only attribute of install.wim: $($_.Exception.Message)"
}

Clear-EmptyMountDirectory -MountDir $scratchDir

& DISM /English `
 /Mount-Image `
 "/ImageFile:$wimFilePath" `
 "/Index:$index" `
 "/MountDir:$scratchDir"
$mountExitCode = $LASTEXITCODE

if ($mountExitCode -ne 0) {
 throw "DISM failed to mount the Windows image. Exit code: $mountExitCode"
}

if (-not $architecture) {
 Write-Host "Architecture information not found."
}

Write-Host "Taking ownership of the Program Files folder. This might take a while..."
& takeown.exe /F "$mainOSDrive\scratchDir\Program Files" /A /R /D Y >$null 2>&1
& icacls.exe "$mainOSDrive\scratchDir\Program Files" /grant "$($adminGroup.Value):(F)" /T /C /Q /L >$null 2>&1

$programFilesX86Path = "$mainOSDrive\scratchDir\Program Files (x86)"
if (Test-Path -LiteralPath $programFilesX86Path -PathType Container) {
