Write-Host "  [Stage 1] 6.1 Load offline registry hives" -ForegroundColor Green
Write-Host "  [Stage 2] 6.2 Apply registry policy and configuration tweaks" -ForegroundColor Yellow
Write-Host "  [Stage 3] 6.3 Apply Default profile / Start configuration" -ForegroundColor Gray
Write-Host "  [Stage 4] 6.4 Unload and flush registry hives" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Loading registry hives for offline tweaking..."
$offlineHiveLoads = @(
    @{ Name = 'zCOMPONENTS'; Path = (Join-Path $scratchDir 'Windows\System32\config\COMPONENTS') },
    @{ Name = 'zDEFAULT';    Path = (Join-Path $scratchDir 'Windows\System32\config\default') },
    @{ Name = 'zNTUSER';     Path = (Join-Path $scratchDir 'Users\Default\ntuser.dat') },
    @{ Name = 'zSOFTWARE';   Path = (Join-Path $scratchDir 'Windows\System32\config\SOFTWARE') },
    @{ Name = 'zSYSTEM';     Path = (Join-Path $scratchDir 'Windows\System32\config\SYSTEM') }
)
foreach ($HiveLoad in $offlineHiveLoads) {
    & reg.exe load "HKLM\$($HiveLoad.Name)" "$($HiveLoad.Path)" >$null 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "Failed to load offline registry hive HKLM\$($HiveLoad.Name) from '$($HiveLoad.Path)'. REG.EXE exit code: $LASTEXITCODE"
    }
}


# ============================================================
# Remove Event Viewer and Task Scheduler ONLY as MMC namespace
# extensions (used by Computer Management), while keeping their
# standalone MMC snap-in registrations intact.
# # Do NOT delete the SnapIns\FX:{...} registrations here. Those
# registrations are also used when the snap-ins are opened directly.
# Instead, remove only matching extension values from MMC NodeTypes.
# ============================================================
$mmcNodeTypesRoot = 'HKLM\zSOFTWARE\Microsoft\MMC\NodeTypes'
$mmcExtensionClsids = @(
 'FX:{b05566ad-fe9c-4363-be05-7a4cbb7cb510}', # Event Viewer
 'FX:{b05566ae-fe9c-4363-be05-7a4cbb7cb510}', # Event Viewer alternate
 'FX:{c7b8fb06-bfe1-4c2e-9217-7a69a95bbac4}', # Task Scheduler
 'FX:{c7b8fb07-bfe1-4c2e-9217-7a69a95bbac4}' # Task Scheduler alternate
)

$mmcNodeTypeKeys = @(
 & reg.exe query $mmcNodeTypesRoot /s 2>$null |
 ForEach-Object {
 if ($_ -match '^HKEY_LOCAL_MACHINE\\zSOFTWARE\\Microsoft\\MMC\\NodeTypes\\(.+)$') {
 $matches[0]
 }
 }
)

foreach ($nodeTypeKey in $mmcNodeTypeKeys) {
 $nodeTypeOutput = & reg.exe query $nodeTypeKey 2>$null
 if ($LASTEXITCODE -ne 0) { continue }

 foreach ($line in $nodeTypeOutput) {
 if ($line -match '^\s+([^\s]+)\s+REG_SZ\s+(.*)$') {
 $valueName = $matches[1]
 $valueData = $matches[2].Trim()

 $nameCandidate = $valueName -replace '^FX:', ''
 $dataCandidate = $valueData -replace '^FX:', ''
 $matchedClsid = $null

 foreach ($candidate in @($nameCandidate, $dataCandidate)) {
 if ($candidate -match '^\{[0-9a-fA-F-]{36}\}$') {
 $fxCandidate = "FX:$candidate"
 if ($mmcExtensionClsids -contains $fxCandidate) {
 $matchedClsid = $fxCandidate
 break
 }
 }
 }

 if ($null -ne $matchedClsid) {
 & reg.exe delete $nodeTypeKey /v $valueName /f >$null 2>&1
 if ($LASTEXITCODE -eq 0) {
 # MMC extension removal completed silently.
 }
 }
 }
 }
}

Write-Host "Applying Micro 11 Barebones Registry Tweaks to the mounted image..."

# ==============================================================================
# MICRO 11 BAREBONES - OFFLINE REGISTRY TWEAKS
# Tweaks are numbered and named by function for easier maintenance.
# The registry commands and tweak logic are preserved.
# ==============================================================================


# 01 - Disable Windows Update and Update Services
Write-Host "`n--- 01 - Disable Windows Update and Update Services ---"
& reg.exe add "HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" '/v' 'StopWUPostOOBE1' '/t' 'REG_SZ' '/d' 'net stop wuauserv' '/f' | Out-Null
& reg.exe add "HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" '/v' 'StopWUPostOOBE2' '/t' 'REG_SZ' '/d' 'sc stop wuauserv' '/f' | Out-Null
& reg.exe add "HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" '/v' 'StopWUPostOOBE3' '/t' 'REG_SZ' '/d' 'sc config wuauserv start= disabled' '/f' | Out-Null
& reg.exe add "HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" '/v' 'DisableWUPostOOBE1' '/t' 'REG_SZ' '/d' 'reg add HKLM\SYSTEM\CurrentControlSet\Services\wuauserv /v Start /t REG_DWORD /d 4 /f' '/f' | Out-Null
& reg.exe add "HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" '/v' 'DisableWUPostOOBE2' '/t' 'REG_SZ' '/d' 'reg add HKLM\SYSTEM\ControlSet001\Services\wuauserv /v Start /t REG_DWORD /d 4 /f' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' '/v' 'DoNotConnectToWindowsUpdateInternetLocations' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' '/v' 'DisableWindowsUpdateAccess' '/t' 'REG_DWORD' '/d' '1' '/f'  | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' '/v' 'WUServer' '/t' 'REG_SZ' '/d' 'localhost' '/f'  | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' '/v' 'WUStatusServer' '/t' 'REG_SZ' '/d' 'localhost' '/f'  | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' '/v' 'UpdateServiceUrlAlternate' '/t' 'REG_SZ' '/d' 'localhost' '/f'  | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' '/v' 'UseWUServer' '/t' 'REG_DWORD' '/d' '1' '/f'  | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\OOBE' '/v' 'DisableOnline' '/t' 'REG_DWORD' '/d' '1' '/f'  | Out-Null
& reg.exe add 'HKLM\zSYSTEM\ControlSet001\Services\wuauserv' '/v' 'Start' '/t' 'REG_DWORD' '/d' '4' '/f'  | Out-Null
# WaaSMedicSVC and UsoSvc are not guaranteed to exist in every reduced Windows image.
# Only modify them when their offline service keys are present; do not generate a
# misleading REG.EXE error when a component/service has already been removed.
foreach ($wuService in @('WaaSMedicSVC','UsoSvc')) {
    $wuServiceKey = "HKLM\zSYSTEM\ControlSet001\Services\$wuService"
    & reg.exe query $wuServiceKey >$null 2>&1
    if ($LASTEXITCODE -eq 0) {
        & reg.exe add $wuServiceKey '/v' 'Start' '/t' 'REG_DWORD' '/d' '4' '/f' >$null 2>&1
        if ($LASTEXITCODE -ne 0) {
            Write-Warning "Could not disable offline Windows Update service $wuService (REG.EXE exit code $LASTEXITCODE)."
        }
    }
    else {
        Write-Host "Skipping ${wuService}: service key is not present in the offline image." -ForegroundColor Green
    }
}

# Disable automatic Windows Update through policy.  Ensure the AU policy key exists first.
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' '/v' 'NoAutoUpdate' '/t' 'REG_DWORD' '/d' '1' '/f' >$null 2>&1
if ($LASTEXITCODE -ne 0) {
    throw "Failed to set Windows Update NoAutoUpdate policy. REG.EXE exit code: $LASTEXITCODE"
}

# 02 - Bypass Windows 11 Hardware Requirements
Write-Host "`n--- 02 - Bypass Windows 11 Hardware Requirements ---" -ForegroundColor Cyan
& reg.exe add 'HKLM\zDEFAULT\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV1' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zDEFAULT\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV2' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zNTUSER\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV1' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zNTUSER\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV2' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassCPUCheck' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassRAMCheck' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassSecureBootCheck' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassStorageCheck' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassTPMCheck' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
& reg.exe add 'HKLM\zSYSTEM\Setup\MoSetup' '/v' 'AllowUpgradesWithUnsupportedTPMOrCPU' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null

# 03 - Enable Local Account Setup During OOBE
Write-Host "`n--- 03 - Enable Local Account Setup During OOBE ---" -ForegroundColor Cyan
& reg.exe add 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\OOBE' '/v' 'BypassNRO' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null
# Generate the supplied answer file exactly, including its original UTF-8 BOM.
