try {
    $answerFileBytes = [Convert]::FromBase64String($answerFileBase64)
    [System.IO.File]::WriteAllBytes($isoAnswerFile, $answerFileBytes)
    if ((Get-FileHash -LiteralPath $isoAnswerFile -Algorithm SHA256).Hash -ne '02E42FDB50FAD726D5111F2D4E108198298C31AB01E4FC5A1D3389B18E94FBE0') {
        throw 'The generated autounattend.xml did not match the supplied file.'
    }
    Write-Host 'Generated autounattend.xml in the ISO source root.' -ForegroundColor Green
}
catch {
    throw ("Unable to generate ISO root autounattend.xml: {0}" -f $_.Exception.Message)
}

# 04 - Disable Reserved Storage
Write-Host "`n--- 04 - Disable Reserved Storage ---" -ForegroundColor Green
& reg.exe add 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\ReserveManager' '/v' 'ShippedWithReserves' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null

# 05 - Disable Automatic BitLocker Device Encryption
Write-Host "`n--- 05 - Disable Automatic BitLocker Device Encryption ---" -ForegroundColor Yellow
& reg.exe add 'HKLM\zSYSTEM\ControlSet001\Control\BitLocker' '/v' 'PreventDeviceEncryption' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null

# 06 - Disable OneDrive Folder Backup
Write-Host "`n--- 06 - Disable OneDrive Folder Backup ---" -ForegroundColor Gray
& reg.exe add "HKLM\zSOFTWARE\Policies\Microsoft\Windows\OneDrive" '/v' 'DisableFileSyncNGSC' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null

# 07 - Disable Sponsored Apps and Consumer Content
Write-Host "`n--- 07 - Disable Sponsored Apps and Consumer Content ---" -ForegroundColor Green
& reg.exe add 'HKLM\zNTUSER\SOFTWARE\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' '/v' 'OemPreInstalledAppsEnabled' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zNTUSER\SOFTWARE\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' '/v' 'PreInstalledAppsEnabled' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zNTUSER\SOFTWARE\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' '/v' 'SilentInstalledAppsEnabled' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' '/v' 'ContentDeliveryAllowed' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Microsoft\PolicyManager\current\device\Start' '/v' 'ConfigureStartPins' '/t' 'REG_SZ' '/d' '{"pinnedList": [{"desktopAppId": "Microsoft.Windows.Settings"}, {"desktopAppId": "Microsoft.Windows.Explorer"}]}' '/f' | Out-Null
& reg.exe add 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' '/v' 'FeatureManagementEnabled' '/t' 'REG_DWORD' '/d' '0' '/f' | Out-Null
