# 46 - Enable Classic Windows Context Menu
Write-Host "`n--- 46 - Enable Classic Windows Context Menu ---" -ForegroundColor Cyan
# Use the registry API: Windows PowerShell native argument handling can drop
# an empty /d argument. Explorer requires an actual empty default REG_SZ.
$classicContextSubKey = 'Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32'

# Apply the override to the signed-in user's HKCU with CMD/reg.exe only.
# /d "" reaches reg.exe through CMD, preserving the actual empty REG_SZ.
# Do not restart Explorer. An existing Explorer session may require a later
# sign-out/sign-in or Windows restart before displaying the classic menu.
$classicContextRunCommand = 'cmd.exe /d /c "reg.exe add HKCU\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32 /ve /t REG_SZ /d "" /f >nul 2>&1"'
$classicContextHive = $null
$classicContextKey = $null
$classicContextRunOnce = $null
try {
    $classicContextHive = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
        [Microsoft.Win32.RegistryHive]::LocalMachine,
        [Microsoft.Win32.RegistryView]::Registry64
    )
    $classicContextKey = $classicContextHive.CreateSubKey('zNTUSER\' + $classicContextSubKey)
    $classicContextKey.SetValue('', '', [Microsoft.Win32.RegistryValueKind]::String)
    $classicContextKey.Flush()
    if ($classicContextKey.GetValueKind('') -ne [Microsoft.Win32.RegistryValueKind]::String -or
        $classicContextKey.GetValue('', $null) -cne '') {
        throw 'Classic context-menu default value is not an empty REG_SZ.'
    }
    # Default User HKCU RunOnce is inherited by each new account and executes
    # in that account, including standard users (unlike machine RunOnce).
    $classicContextRunOnce = $classicContextHive.CreateSubKey(
        'zNTUSER\Software\Microsoft\Windows\CurrentVersion\RunOnce'
    )
    $classicContextRunOnce.SetValue('Micro11ClassicContextMenu', $classicContextRunCommand, [Microsoft.Win32.RegistryValueKind]::String)
    $classicContextRunOnce.Flush()
} finally {
    if ($null -ne $classicContextRunOnce) { $classicContextRunOnce.Dispose() }
    if ($null -ne $classicContextKey) { $classicContextKey.Dispose() }
    if ($null -ne $classicContextHive) { $classicContextHive.Dispose() }
}

# 47 - Remove OneDrive and Windows Security Startup Entries
Write-Host "`n--- 47 - Remove OneDrive and Windows Security Startup Entries ---" -ForegroundColor Cyan
# SecurityHealthSystray can be registered in both Run and StartupApproved.
# Remove every known machine/default-user registration so it does not appear in
# Task Manager > Startup apps on first boot.

$startupEntries = @('OneDriveSetup', 'SecurityHealthSystray', 'SecurityHealth')

$startupRunKeys = @(
 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\Run',
 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
 'HKLM\zSOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run',
 'HKLM\zSOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce',
 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\Run',
 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\RunOnce'
)

$startupApprovedKeys = @(
 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run',
 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32',
 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run',
 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32'
)

foreach ($key in $startupRunKeys + $startupApprovedKeys) {
 foreach ($entry in $startupEntries) {
  & reg.exe query $key '/v' $entry >$null 2>&1
  if ($LASTEXITCODE -eq 0) {
   & reg.exe delete $key '/v' $entry '/f' >$null 2>&1
   if ($LASTEXITCODE -ne 0) {
    Write-Warning "Failed to remove startup value '$entry' from '$key'."
   }
  }
 }
}

# Hide the Windows Security notification icon as an additional safeguard.
& reg.exe add 'HKLM\zSOFTWARE\Policies\Microsoft\Windows Defender Security Center\Systray' `
 '/v' 'HideSystray' '/t' 'REG_DWORD' '/d' '1' '/f' | Out-Null

# Verify that the Run entries were actually removed while the offline hives are mounted.
foreach ($key in @(
 'HKLM\zSOFTWARE\Microsoft\Windows\CurrentVersion\Run',
 'HKLM\zNTUSER\Software\Microsoft\Windows\CurrentVersion\Run'
)) {
 foreach ($entry in $startupEntries) {
 # Capture native stderr as data. PowerShell 5.1 otherwise surfaces
 # expected ERRORLEVEL 1 "value not found" output as NativeCommandError.
 $queryResult = @(& reg.exe query $key '/v' $entry 2>&1)
 $queryExitCode = $LASTEXITCODE
 if ($queryExitCode -eq 0) {
 Write-Warning "Startup entry still exists: $key -> $entry"
 }
 }
}

