# 65 - Disable CPU Security Mitigations
Write-Host "`n--- 65 - Disable CPU Security Mitigations ---" -ForegroundColor Cyan
# Target the Memory Management key inside the mounted offline image
$MemoryManagementKey = 'HKLM\zSYSTEM\ControlSet001\Control\Session Manager\Memory Management'

# Array of values to set
$MitigationTweaks = @(
    @{ Name = 'FeatureSettings';             Type = 'REG_DWORD'; Value = '0' },
    @{ Name = 'FeatureSettingsOverrideMask'; Type = 'REG_DWORD'; Value = '3' },
    @{ Name = 'FeatureSettingsOverride';     Type = 'REG_DWORD'; Value = '3' }
)

# Apply settings with full pipeline error verification
foreach ($Tweak in $MitigationTweaks) {
    & reg.exe add $MemoryManagementKey /v $Tweak.Name /t $Tweak.Type /d $Tweak.Value /f >$null 2>&1
    if ($LASTEXITCODE -ne 0) { 
        throw "Failed to configure registry mitigation tweak: $($Tweak.Name)" 
    }
}


# 66 - Disable Windows Pagefile and Swapfile
Write-Host "`n--- 66 - Disable Windows Pagefile and Swapfile ---" -ForegroundColor Cyan

# IMPORTANT:
# Do not use reg.exe against the offline SYSTEM hive in this section.
# The previous implementation successfully discovered ControlSet001, but then
# stopped immediately afterwards.  The remaining reg.exe ADD/QUERY/DELETE
# operations can block against the mounted SYSTEM hive, so Stage 66 now uses
# Microsoft.Win32.RegistryKey directly.  This bypasses both the PowerShell
# Registry provider and reg.exe while still writing the same offline hive.
#
# The settings below are intentionally preserved:
#   - AutomaticManagedPagefile = 0
#   - PagefileOnOsVolume       = 0
#   - TemporaryPageFile        = 0
#   - TempPageFile             = 0
#   - PagingFiles              = empty REG_MULTI_SZ
#   - ExistingPageFiles        = removed
#   - SwapfileControl          = 0
#   - IoPageLockLimit          = 268435456
#   - HiberBootEnabled         = 0
#   - HibernateEnabled         = 0
#   - CrashDumpEnabled         = 0
#   - AutoReboot               = 1
#   - FilterPages              = 0
# The existing RunOnce cleanup is also retained below.

$MemoryManagementRelativePath = 'Control\Session Manager\Memory Management'

$OfflineControlSets = New-Object 'System.Collections.Generic.List[string]'
$OfflineSystemRoot = $null
$OfflineSystemSelect = $null

try {
    # SILENT: Write-Host "Opening offline SYSTEM hive directly through Windows Registry API..." -ForegroundColor DarkCyan

    $OfflineSystemRoot = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
        [Microsoft.Win32.RegistryHive]::LocalMachine,
        [Microsoft.Win32.RegistryView]::Default
    )

    # Read SYSTEM\Select directly.  This is a small key and avoids any root-hive
    # enumeration through reg.exe.
    $OfflineSystemSelect = $OfflineSystemRoot.OpenSubKey('zSYSTEM\Select', $false)

    if ($null -ne $OfflineSystemSelect) {
        foreach ($SelectName in @('Current','Default','LastKnownGood','Failed')) {
            $SelectValue = $OfflineSystemSelect.GetValue($SelectName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)

            if ($null -ne $SelectValue) {
                $ControlSetNumber = 0
                try {
                    if ($SelectValue -is [int] -or
                        $SelectValue -is [uint32] -or
                        $SelectValue -is [long] -or
                        $SelectValue -is [uint64]) {
                        $ControlSetNumber = [int]$SelectValue
                    }
                    else {
                        $SelectText = ([string]$SelectValue).Trim()
                        if ($SelectText -match '^0x([0-9a-fA-F]+)$') {
                            $ControlSetNumber = [Convert]::ToInt32($matches[1], 16)
                        }
                        elseif ($SelectText -match '^[0-9]+$') {
                            $ControlSetNumber = [int]$SelectText
                        }
                    }
                }
                catch {
                    $ControlSetNumber = 0
                }

                if ($ControlSetNumber -ge 1 -and $ControlSetNumber -le 999) {
                    $Candidate = 'ControlSet{0:D3}' -f $ControlSetNumber
                    if (-not $OfflineControlSets.Contains($Candidate)) {
                        [void]$OfflineControlSets.Add($Candidate)
                    }
                }
            }
        }
    }

    if ($null -ne $OfflineSystemSelect) {
        $OfflineSystemSelect.Close()
        $OfflineSystemSelect = $null
    }

    # Also probe the conventional ControlSet001..ControlSet009 names directly.
    # OpenSubKey is an exact key lookup; it does not enumerate the SYSTEM hive.
    for ($ControlSetNumber = 1; $ControlSetNumber -le 9; $ControlSetNumber++) {
        $Candidate = 'ControlSet{0:D3}' -f $ControlSetNumber
        $Probe = $null
        try {
            $Probe = $OfflineSystemRoot.OpenSubKey("zSYSTEM\$Candidate", $false)
            if ($null -ne $Probe -and -not $OfflineControlSets.Contains($Candidate)) {
                [void]$OfflineControlSets.Add($Candidate)
            }
        }
        finally {
            if ($null -ne $Probe) { $Probe.Close() }
        }
    }

    $OfflineControlSets = @($OfflineControlSets | Sort-Object -Unique)

    if ($OfflineControlSets.Count -eq 0) {
        throw 'No offline SYSTEM ControlSet00x hives were found; cannot safely disable the pagefile.'
    }

    # SILENT: Write-Host ("Offline SYSTEM control sets selected for pagefile/hibernation/crash-dump settings: {0}" -f ($OfflineControlSets -join ', ')) -ForegroundColor DarkCyan

    foreach ($ControlSetName in $OfflineControlSets) {
        # SILENT: Write-Host "Opening $ControlSetName\Control\Session Manager\Memory Management..." -ForegroundColor DarkCyan

        $MemoryManagementKey = $null
        try {
            $MemoryManagementKey = $OfflineSystemRoot.OpenSubKey(
                "zSYSTEM\$ControlSetName\$MemoryManagementRelativePath",
                $true
            )

            if ($null -eq $MemoryManagementKey) {
                throw "Unable to open $ControlSetName\$MemoryManagementRelativePath for writing."
            }

            # SILENT: Write-Host "  [66.1] Disable AutomaticManagedPagefile..." -ForegroundColor Gray
            $MemoryManagementKey.SetValue(
                'AutomaticManagedPagefile',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )

            # SILENT: Write-Host "  [66.2] Disable PagefileOnOsVolume..." -ForegroundColor Gray
            $MemoryManagementKey.SetValue(
                'PagefileOnOsVolume',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )

            # SILENT: Write-Host "  [66.3] Disable TemporaryPageFile..." -ForegroundColor Gray
            $MemoryManagementKey.SetValue(
                'TemporaryPageFile',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )

            # SILENT: Write-Host "  [66.4] Disable TempPageFile..." -ForegroundColor Gray
            $MemoryManagementKey.SetValue(
                'TempPageFile',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )

            # SILENT: Write-Host "  [66.5] Set PagingFiles to an explicitly empty REG_MULTI_SZ..." -ForegroundColor Gray
            $EmptyPagingFiles = [string[]]@()
            $MemoryManagementKey.SetValue(
                'PagingFiles',
                $EmptyPagingFiles,
                [Microsoft.Win32.RegistryValueKind]::MultiString
            )

            # SILENT: Write-Host "  [66.6] Remove ExistingPageFiles if present..." -ForegroundColor Gray
            $ExistingPageFiles = $MemoryManagementKey.GetValue(
                'ExistingPageFiles',
                $null,
                [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames
            )
            if ($null -ne $ExistingPageFiles) {
                $MemoryManagementKey.DeleteValue('ExistingPageFiles', $false)
            }

            # SILENT: Write-Host "  [66.7] Disable SwapfileControl..." -ForegroundColor Gray
            $MemoryManagementKey.SetValue(
                'SwapfileControl',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )

            # SILENT: Write-Host "  [66.8] Preserve IoPageLockLimit..." -ForegroundColor Gray
            $MemoryManagementKey.SetValue(
                'IoPageLockLimit',
                [int]268435456,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )

            $MemoryManagementKey.Flush()
        }
        finally {
            if ($null -ne $MemoryManagementKey) {
                $MemoryManagementKey.Close()
                $MemoryManagementKey = $null
            }
        }

        # SILENT: Write-Host "  Pagefile settings written successfully to $ControlSetName." -ForegroundColor Green
    }

    # Disable Fast Startup and Hibernation in every discovered ControlSet.
    foreach ($ControlSetName in $OfflineControlSets) {
        # SILENT: Write-Host "  [66.9] Disable Fast Startup/Hibernation in $ControlSetName..." -ForegroundColor Gray

        $PowerKey = $null
        try {
            $PowerKey = $OfflineSystemRoot.OpenSubKey(
                "zSYSTEM\$ControlSetName\Control\Session Manager\Power",
                $true
            )
            if ($null -eq $PowerKey) {
                $PowerKey = $OfflineSystemRoot.CreateSubKey(
                    "zSYSTEM\$ControlSetName\Control\Session Manager\Power"
                )
            }
            if ($null -eq $PowerKey) {
                throw "Unable to open/create the offline Power key in $ControlSetName."
            }

            $PowerKey.SetValue(
                'HiberBootEnabled',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )
            $PowerKey.Flush()
        }
        finally {
            if ($null -ne $PowerKey) { $PowerKey.Close() }
        }

        $ControlPowerKey = $null
        try {
            $ControlPowerKey = $OfflineSystemRoot.OpenSubKey(
                "zSYSTEM\$ControlSetName\Control\Power",
                $true
            )
            if ($null -eq $ControlPowerKey) {
                $ControlPowerKey = $OfflineSystemRoot.CreateSubKey(
                    "zSYSTEM\$ControlSetName\Control\Power"
                )
            }
            if ($null -eq $ControlPowerKey) {
                throw "Unable to open/create the offline Control\Power key in $ControlSetName."
            }

            $ControlPowerKey.SetValue(
                'HibernateEnabled',
                [int]0,
                [Microsoft.Win32.RegistryValueKind]::DWord
            )
            $ControlPowerKey.Flush()
        }
        finally {
            if ($null -ne $ControlPowerKey) { $ControlPowerKey.Close() }
        }
    }

    # Disable the crash-dump subsystem in every discovered ControlSet.
    foreach ($ControlSetName in $OfflineControlSets) {
        # SILENT: Write-Host "  [66.10] Disable crash-dump generation in $ControlSetName..." -ForegroundColor Gray

        $CrashControlKey = $null
        try {
            $CrashControlKey = $OfflineSystemRoot.OpenSubKey(
                "zSYSTEM\$ControlSetName\Control\CrashControl",
                $true
            )
            if ($null -eq $CrashControlKey) {
                $CrashControlKey = $OfflineSystemRoot.CreateSubKey(
                    "zSYSTEM\$ControlSetName\Control\CrashControl"
                )
            }
            if ($null -eq $CrashControlKey) {
                throw "Unable to open/create the offline CrashControl key in $ControlSetName."
            }

            $CrashControlKey.SetValue('CrashDumpEnabled', [int]0, [Microsoft.Win32.RegistryValueKind]::DWord)
            $CrashControlKey.SetValue('AutoReboot', [int]1, [Microsoft.Win32.RegistryValueKind]::DWord)
            $CrashControlKey.SetValue('FilterPages', [int]0, [Microsoft.Win32.RegistryValueKind]::DWord)
            $CrashControlKey.Flush()
        }
        finally {
            if ($null -ne $CrashControlKey) { $CrashControlKey.Close() }
        }
    }

    # Verify the critical values before closing the direct Registry API handle.
    foreach ($ControlSetName in $OfflineControlSets) {
        $VerifyKey = $null
        try {
            $VerifyKey = $OfflineSystemRoot.OpenSubKey(
                "zSYSTEM\$ControlSetName\$MemoryManagementRelativePath",
                $false
            )
            if ($null -eq $VerifyKey) {
                throw "Verification failed: Memory Management key could not be reopened in $ControlSetName."
            }

            $AutoValue = $VerifyKey.GetValue('AutomaticManagedPagefile', $null)
            $OsValue = $VerifyKey.GetValue('PagefileOnOsVolume', $null)
            $TempValue = $VerifyKey.GetValue('TemporaryPageFile', $null)
            $LegacyTempValue = $VerifyKey.GetValue('TempPageFile', $null)
            $SwapValue = $VerifyKey.GetValue('SwapfileControl', $null)
            $PagingValue = $VerifyKey.GetValue('PagingFiles', $null)

            if ([int]$AutoValue -ne 0 -or
                [int]$OsValue -ne 0 -or
                [int]$TempValue -ne 0 -or
                [int]$LegacyTempValue -ne 0 -or
                [int]$SwapValue -ne 0) {
                throw "Pagefile registry verification failed in $ControlSetName."
            }

            if ($null -eq $PagingValue -or @($PagingValue).Count -ne 0) {
                throw "PagingFiles is not an explicitly empty REG_MULTI_SZ in $ControlSetName."
            }
        }
        finally {
            if ($null -ne $VerifyKey) { $VerifyKey.Close() }
        }

        # SILENT: Write-Host "  Pagefile registry verification passed for $ControlSetName." -ForegroundColor Green
    }
}
finally {
    if ($null -ne $OfflineSystemSelect) { $OfflineSystemSelect.Close() }
    if ($null -ne $OfflineSystemRoot) { $OfflineSystemRoot.Close() }
}

# Remove any pagefile.sys/swapfile.sys that already exists in the mounted image.
# These files can have restrictive ownership/ACLs, so take ownership before deletion.
foreach ($PagingFile in @(
    (Join-Path $scratchDir 'pagefile.sys'),
    (Join-Path $scratchDir 'swapfile.sys')
)) {
    if (Test-Path -LiteralPath $PagingFile -PathType Leaf) {
        # SILENT: Write-Host "Removing existing paging file from mounted image: $PagingFile" -ForegroundColor Yellow

        & takeown.exe /F $PagingFile /A /D Y >$null 2>&1
        $takeOwnExitCode = $LASTEXITCODE
        if ($takeOwnExitCode -ne 0) {
            Write-Warning "Could not take ownership of '$PagingFile' (takeown.exe exit code $takeOwnExitCode). Continuing with deletion attempt."
        }

        & icacls.exe $PagingFile /grant '*S-1-5-32-544:(F)' /C /Q >$null 2>&1
        $icaclsExitCode = $LASTEXITCODE
        if ($icaclsExitCode -ne 0) {
            Write-Warning "Could not grant Administrators full control on '$PagingFile' (icacls.exe exit code $icaclsExitCode). Continuing with deletion attempt."
        }

        Remove-Item -LiteralPath $PagingFile -Force -ErrorAction SilentlyContinue

        if (Test-Path -LiteralPath $PagingFile -PathType Leaf) {
            Write-Warning "Paging file still exists in the mounted image after deletion attempt: $PagingFile"
        }
    }
}

# 67 - First-Logon Pagefile / DumpStack Cleanup (RunOnce)
# Retained as defensive cleanup for an orphaned/unlocked file.
# The primary prevention remains the offline SYSTEM-hive configuration above.
Write-Host "`n--- 67 - First-Logon Pagefile / DumpStack Cleanup (RunOnce) ---" -ForegroundColor Cyan

$PagefileRunOnceCommand = 'cmd.exe /c "attrib -s -h -r %SystemDrive%\pagefile.sys >nul 2>&1 & del /f /q %SystemDrive%\pagefile.sys >nul 2>&1 & attrib -s -h -r %SystemDrive%\swapfile.sys >nul 2>&1 & del /f /q %SystemDrive%\swapfile.sys >nul 2>&1 & attrib -s -h -r %SystemDrive%\DumpStack.log.tmp >nul 2>&1 & del /f /q %SystemDrive%\DumpStack.log.tmp >nul 2>&1"'

# Use the direct Registry API here as well.  This preserves the RunOnce cleanup
# without introducing another reg.exe operation against the offline SOFTWARE hive.
$RunOnceHive = $null
$RunOnceKey = $null
try {
    # SILENT: Write-Host "Registering first-logon pagefile/DumpStack cleanup directly in offline RunOnce..." -ForegroundColor DarkCyan

    $RunOnceHive = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
        [Microsoft.Win32.RegistryHive]::LocalMachine,
        [Microsoft.Win32.RegistryView]::Default
    )

    $RunOnceKey = $RunOnceHive.OpenSubKey(
        'zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
        $true
    )

    if ($null -eq $RunOnceKey) {
        $RunOnceKey = $RunOnceHive.CreateSubKey(
            'zSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
        )
    }

    if ($null -eq $RunOnceKey) {
        throw 'Unable to open/create the offline RunOnce key.'
    }

    $RunOnceKey.SetValue(
        'Micro11DeletePagefile',
        $PagefileRunOnceCommand,
        [Microsoft.Win32.RegistryValueKind]::String
    )
    $RunOnceKey.Flush()

    $RunOnceVerify = $RunOnceKey.GetValue(
        'Micro11DeletePagefile',
        $null,
        [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames
    )

    if ($null -eq $RunOnceVerify -or [string]$RunOnceVerify -ne $PagefileRunOnceCommand) {
        throw 'RunOnce value verification failed: the stored command does not match the expected cleanup command.'
    }

    # SILENT: Write-Host 'First-logon pagefile cleanup RunOnce entry registered successfully.' -ForegroundColor Green
}
finally {
    if ($null -ne $RunOnceKey) { $RunOnceKey.Close() }
    if ($null -ne $RunOnceHive) { $RunOnceHive.Close() }
}

