# 87 - Add Take Ownership Context Menu (SYSTEM32 CMD WORKER - NO MICRO11 FOLDER)
Write-Host "`n--- 87 - Add Take Ownership Context Menu ---" -ForegroundColor Cyan

$ClassesRoot = 'HKLM\zSOFTWARE\Classes'

# Remove Take Ownership registrations from older revisions.
# Use the .NET Registry API instead of reg.exe. A missing key is handled
# natively and does not create NativeCommandError records in the transcript.
$TakeOwnershipClassesCleanup = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('zSOFTWARE\Classes', $true)
if ($null -eq $TakeOwnershipClassesCleanup) {
    throw 'Unable to open HKLM\zSOFTWARE\Classes for Take Ownership cleanup.'
}
try {
    foreach ($subKey in @(
        '*\shell\TakeOwnership',
        'Directory\shell\TakeOwnership',
        'Drive\shell\TakeOwnership',
        '*\shell\runas',
        'Directory\shell\runas',
        'Drive\shell\runas'
    )) {
        $TakeOwnershipClassesCleanup.DeleteSubKeyTree($subKey, $false)
    }
}
finally {
    $TakeOwnershipClassesCleanup.Dispose()
}

# Remove the obsolete helper folder used by older revisions.
$OldTakeOwnershipDir = Join-Path $scratchDir 'Windows\Micro11'
if (Test-Path -LiteralPath $OldTakeOwnershipDir) {
    Remove-Item -LiteralPath $OldTakeOwnershipDir -Recurse -Force -ErrorAction SilentlyContinue
}

# Install one small CMD worker directly in System32.
# Explorer launches it explicitly through cmd.exe, so the implementation does
# not depend on the .cmd file association.
$TakeOwnershipWorker = Join-Path $scratchDir 'Windows\System32\TakeOwnership.cmd'

$TakeOwnershipWorkerContent = @'
@echo off
setlocal EnableExtensions DisableDelayedExpansion
title Take Ownership - Verbose

if "%~1"=="" exit /b 2
set "TARGET=%~1"
set "TAKEOWN_RC=999"
set "ICACLS_RC=999"
set "ROOT_TAKEOWN_RC=999"
set "ROOT_ICACLS_RC=999"

echo.
echo ============================================================
echo TAKE OWNERSHIP - VERBOSE
echo ============================================================
echo Target: "%TARGET%"
echo.

if exist "%TARGET%\" goto :Folder
goto :File

:File
echo [1/2] Taking ownership
takeown.exe /f "%TARGET%" /a
set "TAKEOWN_RC=%ERRORLEVEL%"
echo TAKEOWN exit code: %TAKEOWN_RC%
echo.
echo [2/2] Granting Administrators Full Control
icacls.exe "%TARGET%" /grant *S-1-5-32-544:F /c /l
set "ICACLS_RC=%ERRORLEVEL%"
echo ICACLS exit code: %ICACLS_RC%
set "RESULT=SUCCESS"
if not "%TAKEOWN_RC%"=="0" set "RESULT=FAILED"
if not "%ICACLS_RC%"=="0" set "RESULT=FAILED"
goto :Summary

:Folder
echo [1/4] Taking ownership recursively
takeown.exe /f "%TARGET%" /a /r /d y /skipsl
set "TAKEOWN_RC=%ERRORLEVEL%"
echo TAKEOWN recursive exit code: %TAKEOWN_RC%
echo.

echo [2/4] Granting Administrators Full Control recursively
rem /T processes the tree, /C continues after errors, /L does not follow links.
rem Native ICACLS verbose output displays each processed object and failures.
icacls.exe "%TARGET%" /grant *S-1-5-32-544:(OI)(CI)F /t /c /l
set "ICACLS_RC=%ERRORLEVEL%"
echo ICACLS recursive exit code: %ICACLS_RC%
echo.

echo [3/4] Confirming ownership of selected root
takeown.exe /f "%TARGET%" /a /skipsl
set "ROOT_TAKEOWN_RC=%ERRORLEVEL%"
echo TAKEOWN root exit code: %ROOT_TAKEOWN_RC%
echo.

echo [4/4] Confirming Full Control on selected root
icacls.exe "%TARGET%" /grant *S-1-5-32-544:(OI)(CI)F /c /l
set "ROOT_ICACLS_RC=%ERRORLEVEL%"
echo ICACLS root exit code: %ROOT_ICACLS_RC%
echo.

set "RESULT=SUCCESS"
if not "%TAKEOWN_RC%"=="0" set "RESULT=FAILED"
if not "%ICACLS_RC%"=="0" set "RESULT=FAILED"
if not "%ROOT_TAKEOWN_RC%"=="0" set "RESULT=FAILED"
if not "%ROOT_ICACLS_RC%"=="0" set "RESULT=FAILED"

:Summary
echo ============================================================
echo TAKE OWNERSHIP SUMMARY
echo ============================================================
echo TAKEOWN recursive/file exit code : %TAKEOWN_RC%
echo ICACLS recursive/file exit code  : %ICACLS_RC%
if not "%ROOT_TAKEOWN_RC%"=="999" echo TAKEOWN root exit code           : %ROOT_TAKEOWN_RC%
if not "%ROOT_ICACLS_RC%"=="999" echo ICACLS root exit code            : %ROOT_ICACLS_RC%
echo.
if "%RESULT%"=="SUCCESS" (
    echo SUCCESS: Ownership and permissions updated.
    exit /b 0
) else (
    echo FAILED: One or more ownership or permission operations reported an error.
    exit /b 1
)
'@

# Write ASCII deliberately: the worker contains only ASCII characters and
# cmd.exe handles this encoding reliably on all supported Windows architectures.
[System.IO.File]::WriteAllText(
    $TakeOwnershipWorker,
    $TakeOwnershipWorkerContent,
    [System.Text.Encoding]::ASCII
)

# Always invoke the worker through the native System32 cmd.exe.
# This avoids both the Explorer "no app associated" error and dependency on
# the .cmd file association.
$TakeOwnershipCommand = '"%SystemRoot%\System32\TakeOwnership.cmd" "%1"'

# Files
$FileTakeOwnership = "$ClassesRoot\*\shell\TakeOwnership"
& reg.exe add $FileTakeOwnership /ve /t REG_SZ /d 'Take Ownership' /f | Out-Null
& reg.exe add $FileTakeOwnership /v 'HasLUAShield' /t REG_SZ /d '' /f | Out-Null
& reg.exe add $FileTakeOwnership /v 'Icon' /t REG_EXPAND_SZ /d '%SystemRoot%\System32\imageres.dll,-78' /f | Out-Null
& reg.exe add $FileTakeOwnership /v 'NoWorkingDirectory' /t REG_SZ /d '' /f | Out-Null
$FileCommandKey = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey('zSOFTWARE\Classes\*\shell\TakeOwnership\command')
try {
    $FileCommandKey.SetValue('', $TakeOwnershipCommand, [Microsoft.Win32.RegistryValueKind]::ExpandString)
}
finally {
    if ($null -ne $FileCommandKey) { $FileCommandKey.Dispose() }
}

# Folders
$DirectoryTakeOwnership = "$ClassesRoot\Directory\shell\TakeOwnership"
& reg.exe add $DirectoryTakeOwnership /ve /t REG_SZ /d 'Take Ownership' /f | Out-Null
& reg.exe add $DirectoryTakeOwnership /v 'HasLUAShield' /t REG_SZ /d '' /f | Out-Null
& reg.exe add $DirectoryTakeOwnership /v 'Icon' /t REG_EXPAND_SZ /d '%SystemRoot%\System32\imageres.dll,-78' /f | Out-Null
& reg.exe add $DirectoryTakeOwnership /v 'NoWorkingDirectory' /t REG_SZ /d '' /f | Out-Null
$DirectoryCommandKey = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey('zSOFTWARE\Classes\Directory\shell\TakeOwnership\command')
try {
    $DirectoryCommandKey.SetValue('', $TakeOwnershipCommand, [Microsoft.Win32.RegistryValueKind]::ExpandString)
}
finally {
    if ($null -ne $DirectoryCommandKey) { $DirectoryCommandKey.Dispose() }
}

# Drives
$DriveTakeOwnership = "$ClassesRoot\Drive\shell\TakeOwnership"
& reg.exe add $DriveTakeOwnership /ve /t REG_SZ /d 'Take Ownership' /f | Out-Null
& reg.exe add $DriveTakeOwnership /v 'HasLUAShield' /t REG_SZ /d '' /f | Out-Null
& reg.exe add $DriveTakeOwnership /v 'Icon' /t REG_EXPAND_SZ /d '%SystemRoot%\System32\imageres.dll,-78' /f | Out-Null
& reg.exe add $DriveTakeOwnership /v 'NoWorkingDirectory' /t REG_SZ /d '' /f | Out-Null
$DriveCommandKey = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey('zSOFTWARE\Classes\Drive\shell\TakeOwnership\command')
try {
    $DriveCommandKey.SetValue('', $TakeOwnershipCommand, [Microsoft.Win32.RegistryValueKind]::ExpandString)
}
finally {
    if ($null -ne $DriveCommandKey) { $DriveCommandKey.Dispose() }
}

# 88 - Add Shift + Right-Click Open Command Window Here
Write-Host "`n--- 88 - Add Shift + Right-Click Open Command Window Here ---"
# Right-click inside a folder background
& reg.exe add 'HKLM\zSOFTWARE\Classes\Directory\Background\shell\OpenCommandWindowHere' '/ve' '/t' 'REG_SZ' '/d' 'Open Command Window Here' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Classes\Directory\Background\shell\OpenCommandWindowHere' '/v' 'Extended' '/t' 'REG_SZ' '/d' '' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Classes\Directory\Background\shell\OpenCommandWindowHere\command' '/ve' '/t' 'REG_SZ' '/d' 'cmd.exe /s /k pushd "%V"' '/f' | Out-Null

# Shift + right-click directly on a folder
& reg.exe add 'HKLM\zSOFTWARE\Classes\Directory\shell\OpenCommandWindowHere' '/ve' '/t' 'REG_SZ' '/d' 'Open Command Window Here' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Classes\Directory\shell\OpenCommandWindowHere' '/v' 'Extended' '/t' 'REG_SZ' '/d' '' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Classes\Directory\shell\OpenCommandWindowHere\command' '/ve' '/t' 'REG_SZ' '/d' 'cmd.exe /s /k pushd "%V"' '/f' | Out-Null

# Shift + right-click on a drive
& reg.exe add 'HKLM\zSOFTWARE\Classes\Drive\shell\OpenCommandWindowHere' '/ve' '/t' 'REG_SZ' '/d' 'Open Command Window Here' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Classes\Drive\shell\OpenCommandWindowHere' '/v' 'Extended' '/t' 'REG_SZ' '/d' '' '/f' | Out-Null
& reg.exe add 'HKLM\zSOFTWARE\Classes\Drive\shell\OpenCommandWindowHere\command' '/ve' '/t' 'REG_SZ' '/d' 'cmd.exe /s /k pushd "%V"' '/f' | Out-Null

Write-Host "Micro 11 Barebones Registry Tweaks have been applied!"

Write-Host "Unloading registry hives..."
foreach ($offlineHiveName in @('zCOMPONENTS','zDEFAULT','zNTUSER','zSOFTWARE','zSYSTEM')) {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $offlineHiveName)) {
 throw "Could not unload offline registry hive HKLM\$offlineHiveName. The hive must be released before continuing."
 }
}

} *> $null
Write-Host 'INSTALL.WIM registry hive tweaks Completed...' -ForegroundColor Green


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "CONFIGURING OFFLINE WINDOWS SERVICES" -ForegroundColor Gray
