 [pscustomobject]@{ Name='Xbox Live Auth Manager'; Keys=@('XblAuthManager'); Value=4 }
 [pscustomobject]@{ Name='Xbox Live Game Save'; Keys=@('XblGameSave'); Value=4 }
 [pscustomobject]@{ Name='Xbox Live Networking'; Keys=@('XboxNetApiSvc'); Value=4 }
 # Keep app deployment and shell support available; do not force trigger-start services to Automatic.
 [pscustomobject]@{ Name='AppX Deployment'; Keys=@('AppXSvc'); Value=3 }
 [pscustomobject]@{ Name='Client License'; Keys=@('ClipSVC'); Value=3 }
 [pscustomobject]@{ Name='Web Account Manager'; Keys=@('TokenBroker'); Value=3 }
 [pscustomobject]@{ Name='State Repository'; Keys=@('StateRepository'); Value=2 }
 [pscustomobject]@{ Name='System Events Broker'; Keys=@('SystemEventsBroker'); Value=2 }
 [pscustomobject]@{ Name='Background Tasks Infrastructure'; Keys=@('BrokerInfrastructure'); Value=2 }
)

# ============================================================
# Configure Offline Windows Services
# IMPORTANT: use reg.exe so PowerShell does not retain Registry
# provider objects that can keep HKLM\zSYSTEM locked.
# ============================================================

$servicesRoot = 'HKLM\zSYSTEM\ControlSet001\Services'

Write-Host "Configuring offline Windows services Completed..." -ForegroundColor Cyan

# Query the service key names once. Store strings only, not Registry objects.
$allServiceNames = @(
 & reg.exe query $servicesRoot 2>$null |
 ForEach-Object {
 if ($_ -match '^HKEY_LOCAL_MACHINE\\zSYSTEM\\ControlSet001\\Services\\(.+)$') {
 $matches[1]
 }
 }
)

if ($LASTEXITCODE -ne 0 -or $allServiceNames.Count -eq 0) {
 Write-Warning "Offline services registry path was not found or could not be queried: $servicesRoot"
}
else {
 foreach ($serviceConfig in $serviceConfigurations) {
 $matchedServiceNames = @()

 foreach ($keyPattern in $serviceConfig.Keys) {
 if ($keyPattern.EndsWith('*', [System.StringComparison]::Ordinal)) {
 $prefix = $keyPattern.Substring(0, $keyPattern.Length - 1)

 $matchedServiceNames += @(
 $allServiceNames | Where-Object {
 $_.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
 }
 )
 }
 else {
 if ($allServiceNames -contains $keyPattern) {
 $matchedServiceNames += $keyPattern
 }
 }
 }

 $matchedServiceNames = @(
 $matchedServiceNames |
 Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
 Sort-Object -Unique
 )

 if ($matchedServiceNames.Count -eq 0) {
 continue
 }

 if ($serviceConfig.Value -eq 5) {
 # Remove/Delete: delete the entire service key rather than just
 # disabling it. Uses reg.exe (not the Registry:: provider) so no
 # RegistryKey handles are left open against HKLM\zSYSTEM.
 foreach ($serviceName in $matchedServiceNames) {
 $servicePath = "$servicesRoot\$serviceName"

 & reg.exe delete $servicePath '/f' >$null 2>&1

 if ($LASTEXITCODE -eq 0) {
 # Service key removed silently.
 }
 else {
 # Expected/unsupported service removal failure: remain silent.
 }
 }
 continue
 }

 $startValue = switch ($serviceConfig.Value) {
 2 { 2 }
 3 { 3 }
 4 { 4 }
 default {
 continue
 }
 }

 foreach ($serviceName in $matchedServiceNames) {
 $servicePath = "$servicesRoot\$serviceName"

 & reg.exe add $servicePath '/v' 'Start' '/t' 'REG_DWORD' '/d' $startValue '/f' >$null 2>&1

 if ($LASTEXITCODE -eq 0) {
 # Service configured silently.
 }
 else {
 # Expected/unsupported service configuration failure: remain silent.
 }
 }
 }
}

# Clear all service-related variables before unloading the offline SYSTEM hive.
$serviceName = $null
$servicePath = $null
$matchedServiceNames = $null
$allServiceNames = $null
$keyPattern = $null
$prefix = $null
$startValue = $null
$serviceConfig = $null
$servicesRoot = $null

[GC]::Collect()
[GC]::WaitForPendingFinalizers()
[GC]::Collect()

Write-Host "Flushing and unloading offline registry hive HKLM\zSYSTEM..."

$systemHiveUnloaded = Invoke-RegUnloadWithRetry -HiveName 'zSYSTEM' -Attempts 30 -DelayMilliseconds 750
if ($systemHiveUnloaded) {
 Write-Host "Unloaded HKLM\zSYSTEM"
}

if (-not $systemHiveUnloaded) {
 throw "Unable to unload offline registry hive HKLM\zSYSTEM after 20 attempts. The hive is still in use."
}
} *> $null
Write-Host 'Configuring offline Windows services Completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "CUSTOM OFFLINE IMAGE FILE INJECTION - EXACT SOURCE -> DESTINATION MAPPINGS" -ForegroundColor Cyan
Write-Host "  [Stage 1] 8.1 Validate source files" -ForegroundColor Gray
Write-Host "  [Stage 2] 8.2 Inject files into the mounted image" -ForegroundColor Cyan
Write-Host "  [Stage 3] 8.3 Verify destination paths" -ForegroundColor Cyan
Write-Host "  [Stage 4] 8.4 Complete custom file injection" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
# ============================================================================
# CUSTOM OFFLINE IMAGE FILE INJECTION - EXACT SOURCE -> DESTINATION MAPPINGS
# ============================================================================
# Add individual files or directories here. Source paths are relative to the
# folder containing this script ($PSScriptRoot). Destination paths are relative
# to the mounted offline Windows image ($scratchDir).
# the exact destination directory:
# @{ Source = 'OfflineFiles\MyTool'; Destination = 'Program Files\MyTool' }
# ============================================================================
$offlineFileMappings = @(
 # Copy Notepad & Paint folder directly into the
 # offline image's Program Files folder.
 @{
 Source = "C:\Micro 11 Barebones Powershell Script\Calculator, Notepad & Paint\Program Files"
 Destination = 'Program Files'
 }
 # Copy Calculator files directly into the
 # offline image's Windows\System32 folder.
 @{
 Source = "C:\Micro 11 Barebones Powershell Script\Calculator, Notepad & Paint\System32"
 Destination = 'Windows\System32'
 }
 # Copy Start Menu Apps Shortcuts directly into the
 # offline image's ProgramData\Microsoft\Windows\Start Menu\Programs folder.
 @{
 Source = "C:\Micro 11 Barebones Powershell Script\Calculator, Notepad & Paint\Accessories"
 Destination = 'ProgramData\Microsoft\Windows\Start Menu\Programs'
 }
)

if ($offlineFileMappings.Count -gt 0) {
 Write-Host "Injecting custom files into the offline Windows image..." -ForegroundColor Green

 foreach ($mapping in $offlineFileMappings) {
 if (-not $mapping.Source -or -not $mapping.Destination) {
 Write-Warning "Skipping invalid offline file mapping: Source and Destination are required."
 continue
 }

 # Source can be relative to the script directory or an absolute path.
 if ([System.IO.Path]::IsPathRooted($mapping.Source)) {
 $sourcePath = $mapping.Source
 }
 else {
 $sourcePath = Join-Path -Path $PSScriptRoot -ChildPath $mapping.Source
 }

 # Destination is always relative to the mounted offline image.
 if ([System.IO.Path]::IsPathRooted($mapping.Destination)) {
 Write-Warning "Skipping mapping with an absolute destination: $($mapping.Destination)"
 continue
 }

 $destinationPath = Join-Path -Path $scratchDir -ChildPath $mapping.Destination

 if (-not (Test-Path -LiteralPath $sourcePath)) {
 Write-Warning "Source not found. Skipping: $sourcePath"
 continue
 }

 try {
 $sourceItem = Get-Item -LiteralPath $sourcePath -Force -ErrorAction Stop

 if ($sourceItem.PSIsContainer) {
 # Create the exact destination directory.
 New-Item `
 -ItemType Directory `
 -Path $destinationPath `
 -Force `
 -ErrorAction Stop | Out-Null

 # Copy CONTENTS of the source directory, not the source folder itself.
 Copy-Item `
 -Path (Join-Path -Path $sourcePath -ChildPath '*') `
 -Destination $destinationPath `
 -Recurse `
 -Force `
 -ErrorAction Stop
 }
 else {
 $destinationParent = Split-Path -Path $destinationPath -Parent

 if ($destinationParent) {
 New-Item `
 -ItemType Directory `
 -Path $destinationParent `
 -Force `
 -ErrorAction Stop | Out-Null
 }

 Copy-Item `
 -LiteralPath $sourcePath `
 -Destination $destinationPath `
 -Force `
 -ErrorAction Stop
 }

 Write-Host " Added: $($mapping.Source) -> $($mapping.Destination)" -ForegroundColor Yellow
 }
 catch {
 throw "Failed to inject '$($mapping.Source)' -> '$($mapping.Destination)': $($_.Exception.Message)"
 }
 }

 Write-Host "Custom offline file injection complete." -ForegroundColor Gray
}
else {
 Write-Host "No custom offline file mappings configured." -ForegroundColor Green
}
} *> $null
Write-Host 'Custom offline file injection complete.' -ForegroundColor Green




Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "REGISTRY CLEANUP -> HIVE REBUILD / COMPACTION" -ForegroundColor Cyan
Write-Host "  [Stage 1] 9.1 Prepare registry cleanup" -ForegroundColor Green
Write-Host "  [Stage 2] 9.2 Rebuild and compact offline hives" -ForegroundColor Yellow
Write-Host "  [Stage 3] 9.3 Verify compacted hive files" -ForegroundColor Gray
Write-Host "============================================================================" -ForegroundColor Gray
. {
# ============================================================================
# REGISTRY CLEANUP -> HIVE REBUILD / COMPACTION
# ============================================================================
# This stage intentionally runs AFTER component/package/file removal and
# BEFORE DISM StartComponentCleanup and WIM export.
# # It does NOT delete the Windows registry hives. Instead it:
# 1. Verifies the required System32\config hives.
# 2. Removes only stale registry transaction/log files AFTER the hive has been successfully rebuilt.
# 3. Loads each selected offline hive and saves it to a NEW hive file.
# 4. Validates the new hive by loading/unloading it.
# 5. Replaces the original only after successful validation.
# # SAM and SECURITY are deliberately excluded from the rebuild. They contain
# security/account information and should not be rewritten merely for size.
# ============================================================================
# OFFLINE REGISTRY ORPHAN / COMPONENT CLEANUP
# ============================================================================
# This is deliberately conservative. It does NOT delete entire Windows
# component registry branches. It removes only:
# 1. Empty registry keys left behind after component/package removal.
# 2. Disabled service registrations whose executable/DLL no longer exists.
# 3. AppX package-repository entries whose corresponding WindowsApps package
# directory no longer exists.
# 4. Empty servicing/component subkeys after the above cleanup.
# # This runs against an already-loaded offline hive and therefore happens
# BEFORE REG SAVE/validation, so the rebuilt hive contains the cleanup.
# ============================================================================
function Invoke-OfflineRegistryOrphanCleanup {
 param(
 [Parameter(Mandatory = $true)]
 [string]$HiveName,

 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $registryRoot = "Registry::HKEY_LOCAL_MACHINE\$HiveName"

 # The rebuild stage mounts hives under temporary names such as
 # zREBUILD_SOFTWARE. Derive the real hive type so the targeted cleanup
 # below actually runs against SYSTEM, SOFTWARE and COMPONENTS.
 $logicalHiveName = ($HiveName -replace '^zREBUILD_', '') -replace '^zVALIDATE_', ''
 $logicalHiveName = $logicalHiveName.ToUpperInvariant()

 if (-not (Test-Path -LiteralPath $registryRoot)) {
 Write-Warning "Offline cleanup hive is not mounted: $HiveName"
 return
 }

 function Remove-EmptyRegistryKeys {
 param(
 [Parameter(Mandatory = $true)]
 [string]$Path
 )

 # Never compact away cryptographic service roots. These keys can be
 # sparse while still being semantically required during early boot.
 if ($logicalHiveName -eq 'SYSTEM' -and ($Path -match '(?i)\\ControlSet\d{3}\Services\(?:CNG|KeyIso)(?:\\|$)')) {
 return
 }

 $children = @(Get-ChildItem -LiteralPath $Path -ErrorAction SilentlyContinue)

 foreach ($child in $children) {
 Remove-EmptyRegistryKeys -Path $child.PSPath
 }

 try {
 $key = Get-Item -LiteralPath $Path -ErrorAction Stop
 $remainingChildren = @(Get-ChildItem -LiteralPath $Path -ErrorAction SilentlyContinue)
 $valueNames = @($key.GetValueNames())

 # Only delete genuinely empty keys. This is intentionally much
 # safer than deleting arbitrary registry branches by name.
 if ($remainingChildren.Count -eq 0 -and $valueNames.Count -eq 0) {
 if ($Path -ne $registryRoot) {
 Remove-Item -LiteralPath $Path -Recurse -Force -Confirm:$false -ErrorAction SilentlyContinue
 }
 }
 }
 catch {
 # Registry keys that cannot be enumerated are left untouched.
 }
 }

 function Resolve-OfflineImagePath {
 param(
 [Parameter(Mandatory = $false)]
 [AllowEmptyString()]
 [AllowNull()]
 [string]$Value
 )

 if ([string]::IsNullOrWhiteSpace([string]$Value)) {
 return $null
 }

 # Do the offline SystemRoot substitutions BEFORE expanding environment
 # variables; otherwise %SystemRoot% would resolve to the host OS.
 $expanded = $Value.Trim().Trim('"')
 $expanded = $expanded -replace '(?i)^%SystemRoot%\\', "$WindowsRoot\\"
 $expanded = $expanded -replace '(?i)^\\SystemRoot\\', "$WindowsRoot\\"
 $expanded = $expanded -replace '(?i)^SystemRoot\\', "$WindowsRoot\\"
 $expanded = [Environment]::ExpandEnvironmentVariables($expanded)

 # Remove command-line arguments. Quoted executable paths are handled
 # first; unquoted paths stop at the first .exe/.sys/.dll extension.
 if ($expanded -match '^\s*"([^"]+\.(?:exe|sys|dll))"') {
 $resolvedPath = $Matches[1]
 if ($resolvedPath -match '^[A-Za-z]:\\') {
 $offlineVolumeRoot = Split-Path -Path $WindowsRoot -Parent
 return (Join-Path $offlineVolumeRoot $resolvedPath.Substring(3))
 }
 return $resolvedPath
 }

 if ($expanded -match '^\s*([^\s]+\.(?:exe|sys|dll))(?=\s|$)') {
 $resolvedPath = $Matches[1]
 if ($resolvedPath -match '^[A-Za-z]:\\') {
 $offlineVolumeRoot = Split-Path -Path $WindowsRoot -Parent
 return (Join-Path $offlineVolumeRoot $resolvedPath.Substring(3))
 }
 return $resolvedPath
 }

 return $null
 }

 Write-Host " Registry orphan cleanup: $HiveName (logical hive: $logicalHiveName)" -ForegroundColor Cyan
 if ($logicalHiveName -eq 'SYSTEM') {
 Write-Host ' BOOT-CRITICAL REGISTRY PROTECTION: driver Type 1/2/8 + storage stack preserved' -ForegroundColor Cyan
 }

 # ------------------------------------------------------------------------
 # SYSTEM: remove only disabled service registrations whose backing binary
 # has already been deleted. Shared svchost services are deliberately
 # skipped because their ImagePath points to svchost.exe, not ServiceDll.
 # ------------------------------------------------------------------------
 if ($logicalHiveName -eq 'SYSTEM') {
 foreach ($controlSet in @('ControlSet001', 'ControlSet002')) {
 $servicesPath = Join-Path $registryRoot "$controlSet\Services"

 if (-not (Test-Path -LiteralPath $servicesPath)) {
 continue
 }

 $protectedServices = @(
 'ACPI','AFD','AppID','Appinfo','AppReadiness','AppXSvc','ClipSVC','InstallService','TokenBroker','BFE','BrokerInfrastructure',
 'CryptSvc','CNG','KeyIso','DcomLaunch','Dhcp','Dnscache','EventLog','FltMgr',
 'LSM','MpsSvc','NlaSvc','PlugPlay','Power','ProfSvc','RpcEptMapper',
 'RpcSs','SamSs','Schedule','SecurityHealthService','StateRepository',
 'SystemEventsBroker','TrustedInstaller','UserManager','WinDefend',
 'Winmgmt','Winlogon','WinRM','W32Time','WpnService','wuauserv',
 'WaaSMedicSvc','UsoSvc'
 )

 # Cryptographic/early-boot services are never eligible for orphan cleanup.
 # CNG and KeyIso are especially sensitive: a stale-looking registry
 # reference must not be treated as proof that the service is disposable.
 $protectedCryptoServices = @('CNG','KeyIso','CryptSvc')

 foreach ($service in @(Get-ChildItem -LiteralPath $servicesPath -ErrorAction SilentlyContinue)) {
 $serviceName = $service.PSChildName

 if (($protectedServices -contains $serviceName) -or ($protectedCryptoServices -contains $serviceName)) {
 continue
 }

 try {
 # Never remove driver service registrations from the generic
 # filesystem-orphan pass. Type 1/2/8 covers boot/kernel drivers.
 $serviceType = $null
 try {
 $serviceProps = Get-ItemProperty -LiteralPath $service.PSPath -ErrorAction SilentlyContinue
 if ($null -ne $serviceProps) {
 $typeProperty = $serviceProps.PSObject.Properties['Type']
 if ($null -ne $typeProperty -and $null -ne $typeProperty.Value) {
 $serviceType = [int]$typeProperty.Value
 }
 }
 } catch { $serviceType = $null }
 if ($null -ne $serviceType -and (($serviceType -band 0x1) -or ($serviceType -band 0x2) -or ($serviceType -band 0x8))) { continue }

 # Explicit storage-stack protection for early boot.
 if ($serviceName -in @('disk','partmgr','volmgr','volsnap','mountmgr','storport','storahci','stornvme','classpnp','spaceport','fvevol','Wof','vdrvroot','iaStorV','iaStorAVC','iaStorAC','UASPStor','USBSTOR','usbhub','usbhub3','storvsp','vioscsi','pvscsi')) { continue }

 $start = (Get-ItemProperty -LiteralPath $service.PSPath -Name Start -ErrorAction SilentlyContinue).Start
 if ($null -eq $start) { continue }

 # AGGRESSIVE MODE:
 # Remove an orphaned service registration whenever its backing
 # EXE/SYS/DLL is already absent from the offline image.
 # The previous version restricted this to Start=4. That left
 # broken Manual/Demand-Start services behind and kept their
 # registry trees in SYSTEM. Critical/core services remain
 # protected above.
 $imagePath = (Get-ItemProperty -LiteralPath $service.PSPath -Name ImagePath -ErrorAction SilentlyContinue).ImagePath
 $serviceDll = $null
 $parametersPath = Join-Path $service.PSPath 'Parameters'

 if (Test-Path -LiteralPath $parametersPath) {
 $serviceDll = (Get-ItemProperty -LiteralPath $parametersPath -Name ServiceDll -ErrorAction SilentlyContinue).ServiceDll
 }

 # Shared-process services use svchost.exe and must be
 # checked through ServiceDll instead of ImagePath.
 if ($imagePath -match '(?i)\\svchost\.exe(?:\s|$)') {
 if (-not $serviceDll) {
 continue
 }

 if ([string]::IsNullOrWhiteSpace([string]$serviceDll)) { continue }
 $dllPath = Resolve-OfflineImagePath -Value ([string]$serviceDll)
 if ($dllPath -and -not (Test-Path -LiteralPath $dllPath -PathType Leaf)) {
 Write-Host " Removing orphaned disabled service: $serviceName" -ForegroundColor Green
 Remove-Item -LiteralPath $service.PSPath -Recurse -Force -ErrorAction SilentlyContinue
 }

 continue
 }

 if ([string]::IsNullOrWhiteSpace([string]$imagePath)) { continue }
 $binaryPath = Resolve-OfflineImagePath -Value ([string]$imagePath)
 if ($binaryPath -and -not (Test-Path -LiteralPath $binaryPath -PathType Leaf)) {
 Write-Host " Removing orphaned disabled service: $serviceName" -ForegroundColor Yellow
 Remove-Item -LiteralPath $service.PSPath -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
 catch {
 # Leave uncertain service registrations untouched.
 }
 }

 # AGGRESSIVE MODE: remove stale service performance-counter
 # registrations when their provider DLL is already gone.
 # These registrations are not required for service startup.
 foreach ($service in @(Get-ChildItem -LiteralPath $servicesPath -ErrorAction SilentlyContinue)) {
 try {
 $performancePath = Join-Path $service.PSPath 'Performance'
 if (-not (Test-Path -LiteralPath $performancePath)) {
 continue
 }

 $library = (Get-ItemProperty -LiteralPath $performancePath -Name Library -ErrorAction SilentlyContinue).Library
 if ([string]::IsNullOrWhiteSpace($library)) {
 continue
 }

 if ([string]::IsNullOrWhiteSpace([string]$library)) { continue }
 $libraryPath = Resolve-OfflineImagePath -Value ([string]$library)
 if ($libraryPath -and -not (Test-Path -LiteralPath $libraryPath -PathType Leaf)) {
 Write-Host " Removing orphaned service Performance registration: $($service.PSChildName)" -ForegroundColor Gray
 Remove-Item -LiteralPath $performancePath -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
 catch {
 # Leave uncertain performance registrations untouched.
 }
 }
 }
 }

 # ------------------------------------------------------------------------
 # SOFTWARE: remove AppX repository records only when the corresponding
 # WindowsApps package directory is gone. This avoids deleting live AppX
 # registrations for packages that remain in the image.
 # ------------------------------------------------------------------------
 if ($logicalHiveName -eq 'SOFTWARE') {
 $windowsAppsPath = Join-Path $WindowsRoot 'Program Files\WindowsApps'
 $existingPackages = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

 if (Test-Path -LiteralPath $windowsAppsPath -PathType Container) {
 foreach ($packageDirectory in @(Get-ChildItem -LiteralPath $windowsAppsPath -Directory -Force -ErrorAction SilentlyContinue)) {
 [void]$existingPackages.Add($packageDirectory.Name)
 }
 }

 $packageRepositoryPaths = @(
 (Join-Path $registryRoot 'Microsoft\Windows\CurrentVersion\Appx\PackageRepository\Packages'),
 (Join-Path $registryRoot 'Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\Applications')
 )

 foreach ($repositoryPath in $packageRepositoryPaths) {
 if (-not (Test-Path -LiteralPath $repositoryPath)) {
 continue
 }

 foreach ($packageKey in @(Get-ChildItem -LiteralPath $repositoryPath -ErrorAction SilentlyContinue)) {
 $packageName = $packageKey.PSChildName

 # Restrict this automatic deletion to normal Microsoft Store
 # package names. Unknown/custom registry entries are left.
 if ($packageName -notmatch '(?i)__[a-z0-9]{8,}$') {
 continue
 }

 if (-not $existingPackages.Contains($packageName)) {
 Write-Host " Removing orphaned AppX registration: $packageName" -ForegroundColor Green
 Remove-Item -LiteralPath $packageKey.PSPath -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
 }

 # Remove uninstall records that explicitly point into WindowsApps but
 # whose package directory no longer exists. Normal Win32 uninstall
 # entries are not touched.
 $uninstallPath = Join-Path $registryRoot 'Microsoft\Windows\CurrentVersion\Uninstall'
 if (Test-Path -LiteralPath $uninstallPath) {
 foreach ($entry in @(Get-ChildItem -LiteralPath $uninstallPath -ErrorAction SilentlyContinue)) {
 try {
 $installLocation = (Get-ItemProperty -LiteralPath $entry.PSPath -Name InstallLocation -ErrorAction SilentlyContinue).InstallLocation
 if ([string]::IsNullOrWhiteSpace($installLocation)) {
 continue
 }

 if ($installLocation -match '(?i)WindowsApps') {
 $resolvedLocation = [Environment]::ExpandEnvironmentVariables($installLocation.Trim('"'))
 if (-not (Test-Path -LiteralPath $resolvedLocation -PathType Container)) {
 Write-Host " Removing orphaned WindowsApps uninstall record: $($entry.PSChildName)" -ForegroundColor Cyan
 Remove-Item -LiteralPath $entry.PSPath -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
 }
 catch {
 # Leave uncertain uninstall records untouched.
 }
 }
 }
 }

 # ------------------------------------------------------------------------
 # COMPONENTS / SOFTWARE / SYSTEM: remove only empty keys left after the
 # targeted cleanup. Never recursively delete non-empty servicing data.
 # ------------------------------------------------------------------------
 $emptyKeyRoots = switch ($logicalHiveName) {
 'COMPONENTS' {
 @(
 $registryRoot,
 (Join-Path $registryRoot 'DerivedData'),
 (Join-Path $registryRoot 'CanonicalData')
 )
 }
 'SOFTWARE' {
 @(
 (Join-Path $registryRoot 'Microsoft\Windows\CurrentVersion\Appx'),
 (Join-Path $registryRoot 'Microsoft\Windows\CurrentVersion\Uninstall')
 )
 }
 'SYSTEM' {
 @(
 (Join-Path $registryRoot 'ControlSet001\Services'),
 (Join-Path $registryRoot 'ControlSet002\Services')
 )
 }
 default { @() }
 }

 # empty-key compaction disabled for this isolation test.
 if($false){
 foreach ($emptyRoot in $emptyKeyRoots) {
 if (Test-Path -LiteralPath $emptyRoot) {
 Remove-EmptyRegistryKeys -Path $emptyRoot
 }
 }
 }
}

function Invoke-InstallOfflineRegistryHiveRebuild {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $configPath = Join-Path $WindowsRoot 'System32\config'

 if (-not (Test-Path -LiteralPath $configPath -PathType Container)) {
 throw "Offline registry directory was not found: $configPath"
 }

 # These are real registry hives and are safe candidates for a save/rebuild
 # after all offline registry edits have finished. RegSaveKeyEx(REG_LATEST_FORMAT) rebuilds the
 # hive file from the live hive structure, reclaiming unused hive-file slack
 # created by deletions. It does not use an unsafe export/import conversion.
 $hivesToRebuild = @(
 'COMPONENTS'
 'DEFAULT'
 'DRIVERS'
 'SOFTWARE'
 'SYSTEM'
 )

 # BBI, BCD-Template and ELAM are not treated as normal registry hives.
 # SAM and SECURITY are intentionally left untouched.
 $configEntries = @(
 'BBI'
 'BCD-Template'
 'COMPONENTS'
 'DEFAULT'
 'DRIVERS'
 'ELAM'
 'SAM'
 'SECURITY'
 'SOFTWARE'
 'SYSTEM'
 )

 Write-Host ''
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host 'OFFLINE SYSTEM32\CONFIG ANALYSIS' -ForegroundColor Cyan
 Write-Host '============================================================' -ForegroundColor Cyan

 foreach ($entry in $configEntries) {
 $entryPath = Join-Path $configPath $entry

 if (Test-Path -LiteralPath $entryPath -PathType Leaf) {
 $sizeMB = (Get-Item -LiteralPath $entryPath -Force).Length / 1MB
 Write-Host (' {0,-14} {1,10:N2} MB' -f $entry, $sizeMB)
 }
 else {
 Write-Warning "Missing config entry: $entry"
 }
 }

 # Use a temporary directory OUTSIDE the Windows image.
 # This prevents backup/rebuild files from becoming part of the WIM.
 $workRoot = Join-Path $env:TEMP ("Micro11-HiveRebuild-" + [guid]::NewGuid().ToString('N'))

 New-Item -ItemType Directory `
 -Path $workRoot `
 -Force `
 -ErrorAction Stop | Out-Null

 try {

 foreach ($hive in $hivesToRebuild) {

 $sourceHive = Join-Path $configPath $hive
 $backupHive = Join-Path $workRoot "$hive.original"
 $rebuiltHive = Join-Path $workRoot "$hive.rebuilt"

 if (-not (Test-Path -LiteralPath $sourceHive -PathType Leaf)) {
 Write-Warning "Skipping missing hive: $hive"
 continue
 }

 $originalSize = (Get-Item -LiteralPath $sourceHive -Force).Length

 Write-Host ''
 Write-Host "Rebuilding registry hive: $hive" -ForegroundColor Cyan

 # Make a host-side emergency backup.
 Copy-Item `
 -LiteralPath $sourceHive `
 -Destination $backupHive `
 -Force `
 -ErrorAction Stop

 Remove-Item `
 -LiteralPath $rebuiltHive `
 -Force `
 -ErrorAction SilentlyContinue

 $tempHiveName = "zREBUILD_$hive"

 # Ensure our temporary name is not already mounted.
 & reg.exe unload "HKLM\$tempHiveName" > $null 2>&1

 # Load the OFFLINE hive.
 & reg.exe load "HKLM\$tempHiveName" $sourceHive > $null 2>&1

 if ($LASTEXITCODE -ne 0) {
 Write-Warning "Could not load offline hive $hive. Original retained."
 continue
 }

 # Remove safe unused/orphaned registry data while the hive is loaded.
 # The subsequent native latest-format save captures the cleaned registry into a new hive.
 try {
 Invoke-OfflineRegistryOrphanCleanup -HiveName $tempHiveName -WindowsRoot $WindowsRoot
 }
 catch {
 Write-Warning "Offline registry orphan cleanup failed for ${hive}: $($_.Exception.Message)"
 }

 $saveExitCode = 1

 try {
 # Saving a loaded hive to a new file creates a fresh hive image
 # instead of carrying the original file's unused file space.
 $saveExitCode = Invoke-NativeRegistryHiveSaveLatest -HiveName $tempHiveName -DestinationPath $rebuiltHive
 }
 finally {
 # Always unload our temporary hive and wait until the file handle
 # is released. Do not copy over the source hive while REG still
 # owns an open handle to it.
 if (-not (Invoke-RegUnloadWithRetry -HiveName $tempHiveName -Attempts 40 -DelayMilliseconds 500)) {
 throw "Could not unload temporary registry hive HKLM\$tempHiveName. The source hive must remain untouched."
 }
 }

 if ($saveExitCode -ne 0 -or -not (Test-Path -LiteralPath $rebuiltHive -PathType Leaf)) {
 Write-Warning "Native/latest-format hive save failed for $hive. Original retained."
 continue
 }

 $rebuiltSize = (Get-Item -LiteralPath $rebuiltHive -Force).Length

 if ($rebuiltSize -le 0) {
 Write-Warning "Rebuilt $hive is empty. Original retained."
 continue
 }

 # ------------------------------------------------------------
 # Validate the newly-created hive BEFORE replacing the original.
 # ------------------------------------------------------------

 $validationHiveName = "zVALIDATE_$hive"

 & reg.exe unload "HKLM\$validationHiveName" > $null 2>&1
 & reg.exe load "HKLM\$validationHiveName" $rebuiltHive > $null 2>&1

 $validationLoadOK = ($LASTEXITCODE -eq 0)

 if ($validationLoadOK) {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $validationHiveName -Attempts 40 -DelayMilliseconds 500)) {
 throw "Could not unload validation hive HKLM\$validationHiveName. The rebuilt hive will not replace the original."
 }
 }

 if (-not $validationLoadOK) {
 Write-Warning "Validation failed for rebuilt $hive. Original retained."
 continue
 }

 # ------------------------------------------------------------
 # Install rebuilt hive only after validation succeeds.
 # ------------------------------------------------------------

 Copy-Item `
 -LiteralPath $rebuiltHive `
 -Destination $sourceHive `
 -Force `
 -ErrorAction Stop

 $finalSize = (Get-Item -LiteralPath $sourceHive -Force).Length

 $differenceMB = ($originalSize - $finalSize) / 1MB
 $percent = if ($originalSize -gt 0) {
 (($originalSize - $finalSize) / $originalSize) * 100
 }
 else {
 0
 }

 if ($finalSize -lt $originalSize) {
 Write-Host (
 ' {0}: {1:N2} MB -> {2:N2} MB | saved {3:N2} MB ({4:N1}%)' -f
 $hive,
 ($originalSize / 1MB),
 ($finalSize / 1MB),
 $differenceMB,
 $percent
 ) -ForegroundColor Green
 }
 elseif ($finalSize -eq $originalSize) {
 Write-Host (
 ' {0}: {1:N2} MB -> {2:N2} MB | no size change' -f
 $hive,
 ($originalSize / 1MB),
 ($finalSize / 1MB)
 ) -ForegroundColor Yellow
 }
 else {
 # Never keep a larger rebuilt hive.
 Copy-Item `
 -LiteralPath $backupHive `
 -Destination $sourceHive `
 -Force `
 -ErrorAction Stop

 Write-Host (
 ' {0}: rebuilt hive was larger ({1:N2} MB -> {2:N2} MB); original retained.' -f
 $hive,
 ($originalSize / 1MB),
 ($rebuiltSize / 1MB)
 ) -ForegroundColor Yellow

 continue
 }

 # ------------------------------------------------------------
 # Only after a successful rebuild, remove old registry log files.
 # These are not registry hives.
 # ------------------------------------------------------------

 $transactionFiles = @(
 "$configPath\$hive.LOG",
 "$configPath\$hive.LOG1",
 "$configPath\$hive.LOG2"
 )

 foreach ($transactionFile in $transactionFiles) {

 if (Test-Path -LiteralPath $transactionFile -PathType Leaf) {

 Remove-Item `
 -LiteralPath $transactionFile `
 -Force `
 -ErrorAction SilentlyContinue
 }
 }
 }

 }
 finally {

 # Make sure our host-side backup directory never enters the WIM.
 if (Test-Path -LiteralPath $workRoot) {
 Remove-Item `
 -LiteralPath $workRoot `
 -Recurse `
 -Force `
 -ErrorAction SilentlyContinue
 }
 }

 Write-Host ''
 Write-Host 'Final System32\config sizes:' -ForegroundColor Cyan

 foreach ($entry in $configEntries) {

 $entryPath = Join-Path $configPath $entry

 if (Test-Path -LiteralPath $entryPath -PathType Leaf) {

 $sizeMB = (Get-Item -LiteralPath $entryPath -Force).Length / 1MB

 Write-Host (' {0,-14} {1,10:N2} MB' -f $entry, $sizeMB)
 }
 }

 Write-Host ''
 Write-Host 'Registry hive rebuild stage completed.' -ForegroundColor Green
}

# ============================================================================
# OFFLINE zNTUSER / zSOFTWARE REGISTRY CLEANUP
# ============================================================================
# Purpose:
# * Remove empty registry keys left behind by component/package removal.
# * Remove clearly orphaned AppX registrations when their recorded package
# path no longer exists in the offline image.
# * Remove clearly orphaned Uninstall entries only when InstallLocation is
# an absolute path and that path no longer exists.
# * Remove stale empty branches after the targeted cleanup.
# # IMPORTANT:
# This is intentionally conservative. It does NOT delete large Windows
# registry branches merely because their names look unused.
# # HIVE-UNLOAD FIX:
# Registry-provider objects can retain native RegistryKey handles after
# Get-ChildItem/GetValue operations. Those handles can prevent reg.exe from
# unloading the offline SOFTWARE hive. This version explicitly disposes
# RegistryKey objects, clears provider references, forces finalization, and
# only throws AFTER all final unload attempts have completed.
# ============================================================================

function Close-OfflineRegistryObjects {
 param(
 [AllowNull()]
 [object[]]$Objects
 )

 foreach ($obj in @($Objects)) {
 if ($null -eq $obj) { continue }

 try {
 if ($obj -is [System.IDisposable]) {
 $obj.Dispose()
 }
 }
 catch {
 # Disposal is best-effort. The hive unload retry handles any
 # remaining transient handles.
 }
 }
}

function Invoke-OfflineUserAndSoftwareRegistryCleanup {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $softwareHiveFile = Join-Path $WindowsRoot 'System32\config\SOFTWARE'

 # NTUSER.DAT is stored in the image root Users directory.
 $imageRoot = Split-Path -Path $WindowsRoot -Parent
 $ntuserHiveFile = Join-Path $imageRoot 'Users\Default\NTUSER.DAT'

 $softwareHiveName = 'zSOFTWARE_CLEAN'
 $ntuserHiveName = 'zNTUSER_CLEAN'

 $loadedSoftware = $false
 $loadedNtuser = $false
 $removedEmpty = 0
 $removedAppx = 0
 $removedUninst = 0

 # IMPORTANT:
 # Do NOT use PowerShell Registry:: provider objects in this cleanup.
 # Get-ChildItem/Remove-Item on Registry:: can leave native RegistryKey
 # handles alive even after the pipeline variables are cleared. Those
 # handles are then capable of blocking REG UNLOAD.
 # # This version uses System.Win32.RegistryKey directly and disposes every
 # key explicitly. The hive is therefore released before reg.exe unload.

 function Remove-EmptyRegistrySubKeys {
 param(
 [Parameter(Mandatory = $true)]
 [Microsoft.Win32.RegistryKey]$ParentKey
 )

 $removed = 0

 foreach ($subKeyName in @($ParentKey.GetSubKeyNames())) {
 $child = $null

 try {
 # Open writable so the parent can delete this child if it
 # becomes empty after its descendants are removed.
 $child = $ParentKey.OpenSubKey($subKeyName, $true)

 if ($null -eq $child) {
 continue
 }

 # Bottom-up traversal: descendants are removed first, which
 # can make their parent empty.
 $removed += Remove-EmptyRegistrySubKeys -ParentKey $child
 }
 catch {
 # Protected/problematic keys are intentionally skipped.
 }
 finally {
 if ($null -ne $child) {
 try { $child.Dispose() } catch {}
 $child = $null
 }
 }

 # Re-open the child only to inspect its final state. No registry
 # provider wrappers are created and the handle is disposed before
 # DeleteSubKeyTree is called on the parent.
 $checkKey = $null
 $isEmpty = $false

 try {
 $checkKey = $ParentKey.OpenSubKey($subKeyName, $false)

 if ($null -ne $checkKey) {
 $isEmpty = (
 @($checkKey.GetSubKeyNames()).Count -eq 0 -and
 @($checkKey.GetValueNames()).Count -eq 0
 )
 }
 }
 catch {
 $isEmpty = $false
 }
 finally {
 if ($null -ne $checkKey) {
 try { $checkKey.Dispose() } catch {}
 $checkKey = $null
 }
 }

 if ($isEmpty) {
 try {
 $ParentKey.DeleteSubKeyTree($subKeyName)
 $removed++
 }
 catch {
 # Leave protected/problematic keys untouched.
 }
 }
 }

 return $removed
 }

 function Test-OfflinePathMissing {
 param(
 [AllowNull()]
 [object]$PathValue
 )

 if (-not ($PathValue -is [string])) {
 return $false
 }

 $path = $PathValue.Trim()
 if (-not $path) {
 return $false
 }

 try {
 $expanded = [Environment]::ExpandEnvironmentVariables($path)

 # Only process absolute filesystem paths. Registry/package
 # identifiers and relative paths are deliberately ignored.
 if (-not [System.IO.Path]::IsPathRooted($expanded)) {
 return $false
 }

 return -not (Test-Path -LiteralPath $expanded)
 }
 catch {
 return $false
 }
 }

 Write-Host ''
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host 'OFFLINE zSOFTWARE / zNTUSER REGISTRY CLEANUP' -ForegroundColor Cyan
 Write-Host '============================================================' -ForegroundColor Cyan

 try {
 # Ensure temporary names are not already mounted.
 & reg.exe unload "HKLM\$softwareHiveName" > $null 2>&1
 & reg.exe unload "HKLM\$ntuserHiveName" > $null 2>&1

 if (-not (Test-Path -LiteralPath $softwareHiveFile -PathType Leaf)) {
 throw "SOFTWARE hive not found: $softwareHiveFile"
 }

 if (-not (Test-Path -LiteralPath $ntuserHiveFile -PathType Leaf)) {
 Write-Warning "Default NTUSER.DAT not found: $ntuserHiveFile"
 }

 & reg.exe load "HKLM\$softwareHiveName" $softwareHiveFile > $null 2>&1
 if ($LASTEXITCODE -ne 0) {
 throw "Could not load SOFTWARE hive for cleanup."
 }
 $loadedSoftware = $true

 if (Test-Path -LiteralPath $ntuserHiveFile -PathType Leaf) {
 & reg.exe load "HKLM\$ntuserHiveName" $ntuserHiveFile > $null 2>&1
 if ($LASTEXITCODE -eq 0) {
 $loadedNtuser = $true
 }
 else {
 Write-Warning 'Could not load Default NTUSER.DAT. SOFTWARE cleanup will continue.'
 }
 }

 $machineKey = $null
 $softwareRootKey = $null
 $ntuserRootKey = $null

 try {
 $machineKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
 [Microsoft.Win32.RegistryHive]::LocalMachine,
 [Microsoft.Win32.RegistryView]::Default
 )

 # ----------------------------------------------------------------
 # Remove clearly orphaned AppX registrations from SOFTWARE.
 # ----------------------------------------------------------------
 $softwareRootKey = $machineKey.OpenSubKey($softwareHiveName, $true)

 if ($null -ne $softwareRootKey) {
 $appxApplicationsKey = $null

 try {
 $appxApplicationsKey = $softwareRootKey.OpenSubKey(
 'Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\Applications',
 $true
 )

 if ($null -ne $appxApplicationsKey) {

 foreach ($packageName in @($appxApplicationsKey.GetSubKeyNames())) {
 $packageKey = $null

 try {
 $packageKey = $appxApplicationsKey.OpenSubKey($packageName, $true)
 if ($null -eq $packageKey) { continue }

 $pathValue = $null

 foreach ($valueName in @('Path','PackageRootFolder','InstallLocation')) {
 $candidate = $packageKey.GetValue(
 $valueName,
 $null,
 [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames
 )

 if ($candidate -is [string] -and $candidate.Trim()) {
 $pathValue = $candidate.Trim()
 break
 }
 }

 if ($false -and (Test-OfflinePathMissing -PathValue $pathValue)) {
 $packageKey.Dispose()
 $packageKey = $null

 $appxApplicationsKey.DeleteSubKeyTree($packageName)
 $removedAppx++
 }
 }
 catch {
 Write-Warning "Skipped AppX registration '$packageName': $($_.Exception.Message)"
 }
 finally {
 if ($null -ne $packageKey) {
 try { $packageKey.Dispose() } catch {}
 $packageKey = $null
 }
 }
 }
 }
 }
 finally {
 if ($null -ne $appxApplicationsKey) {
 try { $appxApplicationsKey.Dispose() } catch {}
 $appxApplicationsKey = $null
 }
 }

 # ----------------------------------------------------------------
 # Remove orphaned uninstall registrations from SOFTWARE.
 # ----------------------------------------------------------------
 foreach ($uninstallPath in @(
 'Microsoft\Windows\CurrentVersion\Uninstall',
 'WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
 )) {
 $uninstallRootKey = $null

 try {
 $uninstallRootKey = $softwareRootKey.OpenSubKey($uninstallPath, $true)

 if ($null -eq $uninstallRootKey) { continue }


 foreach ($entryName in @($uninstallRootKey.GetSubKeyNames())) {
 $entryKey = $null

 try {
 $entryKey = $uninstallRootKey.OpenSubKey($entryName, $false)
 if ($null -eq $entryKey) { continue }

 $installLocation = $entryKey.GetValue(
 'InstallLocation',
 $null,
 [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames
 )

 if (Test-OfflinePathMissing -PathValue $installLocation) {
 $entryKey.Dispose()
 $entryKey = $null

 $uninstallRootKey.DeleteSubKeyTree($entryName)
 $removedUninst++
 }
 }
 catch {
 Write-Warning "Skipped Uninstall entry '$entryName': $($_.Exception.Message)"
 }
 finally {
 if ($null -ne $entryKey) {
 try { $entryKey.Dispose() } catch {}
 $entryKey = $null
 }
 }
 }
 }
 finally {
 if ($null -ne $uninstallRootKey) {
 try { $uninstallRootKey.Dispose() } catch {}
 $uninstallRootKey = $null
 }
 }
 }
 }

 # ----------------------------------------------------------------
 # Remove empty keys from zSOFTWARE and zNTUSER.
 # ----------------------------------------------------------------
 if ($null -ne $softwareRootKey) {

 # Six passes are retained from the previous implementation.
 # Bottom-up recursion normally removes the chain in one pass;
 # additional passes provide a safety margin for keys skipped
 # during a prior traversal.
 # V36 corrected baseline: global SOFTWARE empty-key recursion disabled.
 if($false){ for ($pass = 1; $pass -le 6; $pass++) {
 $removedThisPass = Remove-EmptyRegistrySubKeys -ParentKey $softwareRootKey
 $removedEmpty += $removedThisPass

 if ($removedThisPass -eq 0) { break }
 } }
 }

 if ($loadedNtuser) {
 $ntuserRootKey = $machineKey.OpenSubKey($ntuserHiveName, $true)

 if ($null -ne $ntuserRootKey) {

 # V37 isolation test: enable ONLY the global NTUSER empty-key recursion.
 if($true){ for ($pass = 1; $pass -le 6; $pass++) {
 $removedThisPass = Remove-EmptyRegistrySubKeys -ParentKey $ntuserRootKey
 $removedEmpty += $removedThisPass

 if ($removedThisPass -eq 0) { break }
 } }
 }
 }

 Write-Host 'zSOFTWARE / zNTUSER registry cleanup complete.' -ForegroundColor Green
 }
 finally {
 # Close all .NET RegistryKey objects before REG UNLOAD.
 if ($null -ne $ntuserRootKey) {
 try { $ntuserRootKey.Dispose() } catch {}
 $ntuserRootKey = $null
 }

 if ($null -ne $softwareRootKey) {
 try { $softwareRootKey.Dispose() } catch {}
 $softwareRootKey = $null
 }

 if ($null -ne $machineKey) {
 try { $machineKey.Dispose() } catch {}
 $machineKey = $null
 }

 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 Start-Sleep -Milliseconds 500
 }
 }
 finally {
 # The cleanup above uses only explicitly disposable .NET RegistryKey
 # objects. By the time these commands run there should be no registry
 # provider handles left in this PowerShell process.

 if ($loadedNtuser) {
 if (-not (Invoke-RegUnloadWithRetry `
 -HiveName $ntuserHiveName `
 -Attempts 40 `
 -DelayMilliseconds 500)) {

 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 Start-Sleep -Milliseconds 1000

 & reg.exe unload "HKLM\$ntuserHiveName" > $null 2>&1
 }

 & reg.exe query "HKLM\$ntuserHiveName" > $null 2>&1
 if ($LASTEXITCODE -eq 0) {
 throw "Could not fully unload HKLM\$ntuserHiveName. The NTUSER hive is still in use and must be released before continuing."
 }
 }

 if ($loadedSoftware) {
 if (-not (Invoke-RegUnloadWithRetry `
 -HiveName $softwareHiveName `
 -Attempts 40 `
 -DelayMilliseconds 500)) {

 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 Start-Sleep -Milliseconds 1000

 & reg.exe unload "HKLM\$softwareHiveName" > $null 2>&1
 }

 & reg.exe query "HKLM\$softwareHiveName" > $null 2>&1
 if ($LASTEXITCODE -eq 0) {
 throw "Could not fully unload HKLM\$softwareHiveName. The SOFTWARE hive is still in use and must be released before continuing."
 }
 }
 }
}


# ============================================================================
# OFFLINE DEFAULT NTUSER.DAT REBUILD / COMPACTION
# ============================================================================
# Purpose:
# * Compact the Default user's NTUSER.DAT after zNTUSER cleanup.
# * Remove unused hive file slack by a native latest-format save into a fresh hive.
# * Validate the rebuilt hive before replacing the original.
# * Remove NTUSER transaction logs only after a successful replacement.
# ============================================================================
function Invoke-OfflineDefaultNtUserHiveRebuild {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $imageRoot = Split-Path -Path $WindowsRoot -Parent
 $sourceHive = Join-Path $imageRoot 'Users\Default\NTUSER.DAT'

 if (-not (Test-Path -LiteralPath $sourceHive -PathType Leaf)) {
 Write-Warning "Default NTUSER.DAT not found. Skipping NTUSER compaction: $sourceHive"
 return
 }

 $workRoot = Join-Path $env:TEMP ("Micro11-NTUSER-Rebuild-" + [guid]::NewGuid().ToString('N'))
 $backupHive = Join-Path $workRoot 'NTUSER.DAT.original'
 $rebuiltHive = Join-Path $workRoot 'NTUSER.DAT.rebuilt'
 $tempHiveName = 'zNTUSER_REBUILD'

 New-Item -ItemType Directory -Path $workRoot -Force -ErrorAction Stop | Out-Null

 try {
 $originalSize = (Get-Item -LiteralPath $sourceHive -Force).Length

 Copy-Item -LiteralPath $sourceHive -Destination $backupHive -Force -ErrorAction Stop
 Remove-Item -LiteralPath $rebuiltHive -Force -ErrorAction SilentlyContinue

 & reg.exe unload "HKLM\$tempHiveName" > $null 2>&1
 & reg.exe load "HKLM\$tempHiveName" $sourceHive > $null 2>&1

 if ($LASTEXITCODE -ne 0) {
 Write-Warning 'Could not load Default NTUSER.DAT for compaction. Original retained.'
 return
 }

 $saveExitCode = 1
 try {
 $saveExitCode = Invoke-NativeRegistryHiveSaveLatest -HiveName $tempHiveName -DestinationPath $rebuiltHive
 }
 finally {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $tempHiveName -Attempts 40 -DelayMilliseconds 500)) {
 throw "Could not unload temporary NTUSER rebuild hive HKLM\$tempHiveName."
 }
 }

 if ($saveExitCode -ne 0 -or -not (Test-Path -LiteralPath $rebuiltHive -PathType Leaf)) {
 Write-Warning 'Native/latest-format hive save failed for Default NTUSER.DAT. Original retained.'
 return
 }

 $rebuiltSize = (Get-Item -LiteralPath $rebuiltHive -Force).Length
 if ($rebuiltSize -le 0) {
 Write-Warning 'Rebuilt Default NTUSER.DAT is empty. Original retained.'
 return
 }

 # Validate the new hive before replacing the original.
 $validationHiveName = 'zNTUSER_VALIDATE'
 & reg.exe unload "HKLM\$validationHiveName" > $null 2>&1
 & reg.exe load "HKLM\$validationHiveName" $rebuiltHive > $null 2>&1
 $validationLoadOK = ($LASTEXITCODE -eq 0)

 if ($validationLoadOK) {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $validationHiveName -Attempts 40 -DelayMilliseconds 500)) {
 throw "Could not unload validation hive HKLM\$validationHiveName. Original NTUSER.DAT retained."
 }
 }

 if (-not $validationLoadOK) {
 Write-Warning 'Validation failed for rebuilt Default NTUSER.DAT. Original retained.'
 return
 }

 if ($rebuiltSize -lt $originalSize) {
 Copy-Item -LiteralPath $rebuiltHive -Destination $sourceHive -Force -ErrorAction Stop

 $finalSize = (Get-Item -LiteralPath $sourceHive -Force).Length
 $savedMB = ($originalSize - $finalSize) / 1MB
 $percent = (($originalSize - $finalSize) / $originalSize) * 100

 Write-Host (
 ' NTUSER.DAT: {0:N2} MB -> {1:N2} MB | saved {2:N2} MB ({3:N1}%)' -f
 ($originalSize / 1MB),
 ($finalSize / 1MB),
 $savedMB,
 $percent
 ) -ForegroundColor Green

 # Remove transaction logs only after a validated smaller hive is installed.
 foreach ($transactionFile in @(
 "$imageRoot\Users\Default\NTUSER.DAT.LOG",
 "$imageRoot\Users\Default\NTUSER.DAT.LOG1",
 "$imageRoot\Users\Default\NTUSER.DAT.LOG2"
 )) {
 if (Test-Path -LiteralPath $transactionFile -PathType Leaf) {
 Remove-Item -LiteralPath $transactionFile -Force -ErrorAction SilentlyContinue
 }
 }
 }
 elseif ($rebuiltSize -eq $originalSize) {
 Write-Host ' NTUSER.DAT: no size change; original retained.' -ForegroundColor Yellow
 }
 else {
 Write-Host (
 ' NTUSER.DAT: rebuilt hive was larger ({0:N2} MB -> {1:N2} MB); original retained.' -f
 ($originalSize / 1MB),
 ($rebuiltSize / 1MB)
 ) -ForegroundColor Yellow
 }
 }
 finally {
 if (Test-Path -LiteralPath $workRoot) {
 Remove-Item -LiteralPath $workRoot -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
}


# ============================================================================
# OFFLINE SYSTEM32\CONFIG REGISTRY LOG CLEANUP
# ============================================================================
function Remove-OfflineRegistryHiveLogFiles {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $configPath = Join-Path $WindowsRoot 'System32\config'

 if (-not (Test-Path -LiteralPath $configPath -PathType Container)) {
 Write-Warning "Registry config directory was not found: $configPath"
 return
 }

 # These are the registry hives/log sets requested for cleanup.
 # Only transactional log files belonging to the exact hive names are
 # removed. Core hive files themselves are never deleted.
 $hives = @(
 'COMPONENTS',
 'DEFAULT',
 'DRIVERS',
 'SOFTWARE',
 'SYSTEM',
 'SAM',
 'SECURITY',
 'ELAM',
 'BBI',
 'BCD-Template'
 )

 $logSuffixes = @(
 '.LOG',
 '.LOG1',
 '.LOG2'
 )

 Write-Host ''
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host 'OFFLINE SYSTEM32\CONFIG REGISTRY LOG CLEANUP' -ForegroundColor Cyan
 Write-Host '============================================================' -ForegroundColor Cyan

 $removedCount = 0
 $removedBytes = [int64]0

 foreach ($hive in $hives) {
 $candidateFiles = New-Object System.Collections.Generic.List[System.IO.FileInfo]

 foreach ($suffix in $logSuffixes) {
 $logPath = Join-Path $configPath ($hive + $suffix)
 if (Test-Path -LiteralPath $logPath -PathType Leaf) {
 $candidateFiles.Add((Get-Item -LiteralPath $logPath -Force -ErrorAction SilentlyContinue))
 }
 }

 # Registry transaction-manager sidecars created for loaded hives use
 # names such as COMPONENTS{GUID}.TM.blf and
 # COMPONENTS{GUID}.TMContainer00000000000000000001.regtrans-ms.
 # Match only files belonging to the exact hive name.
 $escapedHive = [regex]::Escape($hive)
 foreach ($file in @(Get-ChildItem -LiteralPath $configPath -File -Force -ErrorAction SilentlyContinue)) {
 if ($file.Name -match ("(?i)^$escapedHive\{[0-9a-f-]+\}\.TM\.blf$") -or
 $file.Name -match ("(?i)^$escapedHive\{[0-9a-f-]+\}\.TMContainer[0-9]+\.regtrans-ms$")) {
 if (-not $candidateFiles.Contains($file)) {
 $candidateFiles.Add($file)
 }
 }
 }

 foreach ($logFile in @($candidateFiles)) {
 if ($null -eq $logFile) { continue }
 try {
 $logSize = $logFile.Length
 Remove-Item -LiteralPath $logFile.FullName -Force -ErrorAction Stop
 $removedCount++
 $removedBytes += $logSize

 Write-Host (
 ' Removed: {0} ({1:N2} MB)' -f
 $logFile.Name,
 ($logSize / 1MB)
 )
 }
 catch {
 Write-Warning (
 'Unable to remove registry transaction file {0}: {1}' -f
 $logFile.FullName,
 $_.Exception.Message
 )
 }
 }
 }

 # The config\TxR directory can contain registry transaction files that are
 # no longer needed once all offline hives have been cleanly unloaded and
 # validated. Remove files only; keep the directory itself.
 $txrPath = Join-Path $configPath 'TxR'
 if (Test-Path -LiteralPath $txrPath -PathType Container) {
 foreach ($txrFile in @(Get-ChildItem -LiteralPath $txrPath -File -Force -ErrorAction SilentlyContinue)) {
 try {
 $txrSize = $txrFile.Length
 Remove-Item -LiteralPath $txrFile.FullName -Force -ErrorAction Stop
 $removedCount++
 $removedBytes += $txrSize
 Write-Host (' Removed TxR: {0} ({1:N2} MB)' -f $txrFile.Name, ($txrSize / 1MB))
 }
 catch {
 Write-Warning ('Unable to remove TxR file {0}: {1}' -f $txrFile.FullName, $_.Exception.Message)
 }
 }
 }

 if ($removedCount -eq 0) {
 Write-Host ' No matching registry transaction log files were found.' -ForegroundColor Yellow
 }
 else {
 Write-Host (
 ' Registry log cleanup: removed {0} file(s), reclaimed {1:N2} MB.' -f
 $removedCount,
 ($removedBytes / 1MB)
 ) -ForegroundColor Green
 }

 Write-Host 'Registry log cleanup completed.'
 Write-Host ''
}

# ============================================================================
# MAXIMUM-AGGRESSIVE OFFLINE SYSTEM / SOFTWARE REGISTRY COMPACTION
# ============================================================================
# Purpose:
# Physically reduce SYSTEM and SOFTWARE hive size after the component/file
# removal stages have completed.
# # Strategy:
# 1. Preserve disabled service registrations. Start=4 is sufficient and avoids
# dependency/startup retry problems caused by deleting service definitions.
# 2. Remove only service registrations whose executable/ServiceDll is genuinely
# missing from the offline image, while protecting core/virtualization entries.
# 3. Remove stale service metadata left under SOFTWARE\Svchost when the
# referenced service no longer exists.
# 4. Remove orphaned SOFTWARE App Paths and uninstall registrations only when
# their recorded executable/location is an absolute offline path and the
# target is definitely absent.
# 5. Empty-key compaction is disabled in V30 for isolation testing.
# 6. Leave CBS/COMPONENTS servicing metadata intact. Deleting servicing
# databases blindly can make DISM, SFC, updates, OOBE or future servicing
# unusable.
# # IMPORTANT:
# Disabled service registrations are preserved. Only registrations proven
# orphaned by a missing backing file are eligible for removal. Kernel/boot
# drivers and virtualization-related services are explicitly protected.
# ============================================================================

function Invoke-MaximumAggressiveOfflineRegistryCompaction {
 param(
 [Parameter(Mandatory)] [string] $WindowsRoot
 )

 $configPath = Join-Path $WindowsRoot 'System32\config'
 $systemHiveFile = Join-Path $configPath 'SYSTEM'
 $softwareHiveFile = Join-Path $configPath 'SOFTWARE'

 if (-not (Test-Path -LiteralPath $systemHiveFile -PathType Leaf)) {
 throw "SYSTEM hive not found: $systemHiveFile"
 }
 if (-not (Test-Path -LiteralPath $softwareHiveFile -PathType Leaf)) {
 throw "SOFTWARE hive not found: $softwareHiveFile"
 }

 $systemName = 'zSYSTEM_MAXCLEAN'
 $softwareName = 'zSOFTWARE_MAXCLEAN'
 $machine = $null
 $systemRoot = $null
 $softwareRoot = $null

 # Services which must never be deleted by this pass.
 # These are deliberately conservative because removing a service key is
 # substantially more destructive than setting Start=4.
 $protectedServices = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
 @(
 'ACPI','AFD','AppID','Appinfo','AppReadiness','TokenBroker','AudioEndpointBuilder','Audiosrv',
 'BFE','BrokerInfrastructure','CryptSvc','CNG','KeyIso','DcomLaunch','Dhcp','Dnscache',
 'EventLog','EventSystem','gpsvc','IKEEXT','iphlpsvc','LanmanWorkstation',
 'LSM','mpssvc','NlaSvc','nsi','PlugPlay','Power','ProfSvc','RpcEptMapper',
 'RpcSs','SamSs','Schedule','SecurityHealthService','SENS','ShellHWDetection',
 'StateRepository','StorSvc','SystemEventsBroker','TermService','Themes',
 'TimeBrokerSvc','TrustedInstaller','UserManager','UsoSvc','VaultSvc',
 'WinDefend','Winmgmt','Winlogon','WlanSvc','WpnService','WSearch','W32Time',
 'BITS','Browser','LanmanServer','Spooler','Tcpip','Tcpip6','Netman',
 'disk','partmgr','volmgr','volsnap','mountmgr','storport','storahci','stornvme','classpnp','spaceport','fvevol','Wof','vdrvroot',
 'iaStorV','iaStorAVC','iaStorAC','UASPStor','USBSTOR','usbhub','usbhub3','storvsp','vioscsi','pvscsi',
 'NlaSvc','Netlogon','ProfSvc','Sstpsvc','RasMan','RasAuto','MpsSvc',
 'CryptSvc','msiserver','AppXSvc','ClipSVC','InstallService','LicenseManager',
 'RpcLocator','PlugPlay','UserDataSvc','WpnUserService'
 ) | ForEach-Object { [void]$protectedServices.Add($_) }

 # Service names explicitly disabled by the existing service section.
 $configuredDisabled = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
 if ($null -ne $script:serviceConfigurations) {
 foreach ($entry in $script:serviceConfigurations) {
 if ($entry.Value -eq 4) {
 foreach ($keyPattern in $entry.Keys) {
 if ($keyPattern -notlike '*_*') {
 [void]$configuredDisabled.Add($keyPattern)
 }
 }
 }
 }
 }

 function Test-MaxCleanProtectedService {
 param([string]$Name)
 if ([string]::IsNullOrWhiteSpace($Name)) { return $true }
 if ($protectedServices.Contains($Name)) { return $true }
 # Preserve VMware and VirtualBox service/driver families. Hyper-V is intentionally not protected.
 if ($Name -match '(?i)^(?:vmware|vm3d|vmx|vbox)') { return $true }
 # Cryptographic services are boot/security critical and must never be
 # classified as orphaned by filesystem-based cleanup.
 if ($Name -ieq 'CNG' -or $Name -ieq 'KeyIso' -or $Name -ieq 'CryptSvc') { return $true }
 # Protect the per-user service families unless explicitly targeted by
 # the existing configuration list. Their instance names contain '_'.
 foreach ($base in @('WpnUserService','cbdhsvc','BcastDVRUserService','CaptureService','MessagingService','PimIndexMaintenanceSvc','UserDataSvc','UnistoreSvc','OneSyncSvc','CDPUserSvc')) {
 if ($Name -ieq $base -or $Name -like ($base + '_*')) {
 return $true
 }
 }
 return $false
 }

 function Convert-MaxCleanPath {
 param([string]$Value)
 if ([string]::IsNullOrWhiteSpace($Value)) { return $null }

 # Expand variables first, then extract ONLY the backing file from ImagePath.
 # Quoted service paths may contain arguments after the executable.
 $raw = [Environment]::ExpandEnvironmentVariables($Value.Trim())
 $p = $null

 if ($raw -match '^\s*"([^"]+\.(?:exe|dll|sys|com|cpl|ocx))"(?:\s|$)') {
 $p = $Matches[1]
 } elseif ($raw -match '^\s*([^"].*?\.(?:exe|dll|sys|com|cpl|ocx))(?=\s+(?:[-/]|\\)|$)') {
 $p = $Matches[1].Trim()
 } elseif ($raw -match '^\s*([^"].*?\.(?:exe|dll|sys|com|cpl|ocx))\s*$') {
 $p = $Matches[1].Trim()
 } else {
 # Ambiguous ImagePath: preserve the service instead of guessing.
 return $null
 }

 $p = $p -replace '^\\SystemRoot\\', ($WindowsRoot.TrimEnd('\') + '\')
 $p = $p -replace '^SystemRoot\\', ($WindowsRoot.TrimEnd('\') + '\')
 $p = $p -replace '^%SystemRoot%\\', ($WindowsRoot.TrimEnd('\') + '\')
 $p = $p -replace '^%windir%\\', ($WindowsRoot.TrimEnd('\') + '\')
 $p = $p -replace '^\\\?\\', ''
 if ($p -notmatch '^[A-Za-z]:\\') { return $null }

 # Absolute offline service paths belong to the mounted target image.
 $offlineVolumeRoot = Split-Path -Path $WindowsRoot -Parent
 $relative = $p.Substring(3)
 return (Join-Path $offlineVolumeRoot $relative)
 }

 function Test-MaxCleanBackingFile {
 param([string]$Value)
 $p = Convert-MaxCleanPath $Value
 if ($null -eq $p) { return $true } # Cannot safely resolve -> preserve.
 return (Test-Path -LiteralPath $p -PathType Leaf)
 }

 function Remove-MaxCleanEmptyKeys {
 param([Microsoft.Win32.RegistryKey]$Key)
 if ($null -eq $Key) { return }
 try {
 $keyPath = $Key.Name
 if ($keyPath -match '(?i)\\ControlSet\d{3}\Services\(?:CNG|KeyIso|CryptSvc|disk|partmgr|volmgr|volsnap|mountmgr|storport|storahci|stornvme|classpnp|spaceport|fvevol|Wof|vdrvroot|iaStorV|iaStorAVC|iaStorAC|UASPStor|USBSTOR|usbhub|usbhub3|storvsp|vioscsi|pvscsi)(?:\\|$)') { return }
 } catch { return }
 $children = @($Key.GetSubKeyNames())
 foreach ($child in $children) {
 $sub = $null
 try {
 $sub = $Key.OpenSubKey($child, $true)
 if ($null -ne $sub) {
 Remove-MaxCleanEmptyKeys $sub
 $sub.Dispose()
 $sub = $null
 }
 $remaining = $null
 try {
 $remaining = $Key.OpenSubKey($child, $false)
 $empty = ($remaining.GetSubKeyCount() -eq 0 -and $remaining.ValueCount -eq 0)
 } finally {
 if ($null -ne $remaining) { $remaining.Dispose() }
 }
 if ($empty) { [void]$Key.DeleteSubKey($child, $false) }
 } catch { }
 finally { if ($null -ne $sub) { $sub.Dispose() } }
 }
 }

 try {
 & reg.exe unload "HKLM\$systemName" > $null 2>&1
 & reg.exe unload "HKLM\$softwareName" > $null 2>&1

 & reg.exe load "HKLM\$systemName" $systemHiveFile > $null 2>&1
 if ($LASTEXITCODE -ne 0) { throw "Could not load SYSTEM hive for maximum cleanup." }
 & reg.exe load "HKLM\$softwareName" $softwareHiveFile > $null 2>&1
 if ($LASTEXITCODE -ne 0) { throw "Could not load SOFTWARE hive for maximum cleanup." }

 $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
 [Microsoft.Win32.RegistryHive]::LocalMachine,
 [Microsoft.Win32.RegistryView]::Default
 )
 $systemRoot = $machine.OpenSubKey($systemName, $true)
 $softwareRoot = $machine.OpenSubKey($softwareName, $true)

 if ($null -eq $systemRoot -or $null -eq $softwareRoot) {
 throw 'Could not obtain writable handles to the temporary SYSTEM/SOFTWARE hives.'
 }

 $removedServices = 0
 $missingServices = 0
 $serviceMetadataRemoved = 0
 $appPathsRemoved = 0
 $uninstallRemoved = 0

 # --------------------------------------------------------------------
 # Process every real SYSTEM ControlSet.
 # --------------------------------------------------------------------
 foreach ($controlSet in @($systemRoot.GetSubKeyNames() | Where-Object { $_ -match '^ControlSet\d{3}$' })) {
 $services = $null
 try {
 $services = $systemRoot.OpenSubKey("$controlSet\Services", $true)
 if ($null -eq $services) { continue }

 foreach ($serviceName in @($services.GetSubKeyNames())) {
 if (Test-MaxCleanProtectedService $serviceName) { continue }

 $svc = $null
 try {
 $svc = $services.OpenSubKey($serviceName, $false)
 if ($null -eq $svc) { continue }

 $type = 16
 $start = -1
 try { $type = [int]$svc.GetValue('Type', 16) } catch { }
 try { $start = [int]$svc.GetValue('Start', -1) } catch { }

 # Never delete kernel/boot drivers in the aggressive pass.
 # Type 1/2/8 are driver/boot-driver classes; keep them.
 if ($type -band 0x1 -or $type -band 0x2 -or $type -band 0x8) { continue }

 $imagePath = [string]$svc.GetValue('ImagePath', '')
 $serviceDll = ''
 $params = $svc.OpenSubKey('Parameters', $false)
 if ($null -ne $params) {
 try { $serviceDll = [string]$params.GetValue('ServiceDll', '') } catch { }
 $params.Dispose()
 }

 $definitelyOrphaned = $false

 if (-not [string]::IsNullOrWhiteSpace($serviceDll)) {
 $definitelyOrphaned = -not (Test-MaxCleanBackingFile $serviceDll)
 } elseif (-not [string]::IsNullOrWhiteSpace($imagePath)) {
 # Only classify as orphan when the path can be
 # resolved to an absolute filesystem path.
 $resolved = Convert-MaxCleanPath $imagePath
 if ($null -ne $resolved) {
 $definitelyOrphaned = -not (Test-MaxCleanBackingFile $imagePath)
 }
 }

 if ($definitelyOrphaned) {
 try {
 [void]$services.DeleteSubKeyTree($serviceName)
 $removedServices++
 if ($definitelyOrphaned) { $missingServices++ }
 } catch { }
 }
 } catch { }
 finally { if ($null -ne $svc) { $svc.Dispose() } }
 }
 }
 finally { if ($null -ne $services) { $services.Dispose() } }
 }

 # --------------------------------------------------------------------
 # Clean SOFTWARE\Microsoft\Windows NT\CurrentVersion\Svchost.
 # Remove only service names that no longer exist in any ControlSet.
 # --------------------------------------------------------------------
 $allServiceNames = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
 foreach ($controlSet in @($systemRoot.GetSubKeyNames() | Where-Object { $_ -match '^ControlSet\d{3}$' })) {
 $services = $null
 try {
 $services = $systemRoot.OpenSubKey("$controlSet\Services", $false)
 if ($null -eq $services) { continue }
 foreach ($n in $services.GetSubKeyNames()) { [void]$allServiceNames.Add($n) }
 } catch { }
 finally { if ($null -ne $services) { $services.Dispose() } }
 }

 $svchost = $null
 try {
 $svchost = $softwareRoot.OpenSubKey('Microsoft\Windows NT\CurrentVersion\Svchost', $true)
 if ($null -ne $svchost) {
 foreach ($valueName in @($svchost.GetValueNames())) {
 try {
 $value = $svchost.GetValue($valueName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 if ($value -is [Array]) {
 $newValues = @($value | Where-Object { $allServiceNames.Contains([string]$_) })
 if ($newValues.Count -eq 0) {
 [void]$svchost.DeleteValue($valueName, $false)
 $serviceMetadataRemoved++
 } elseif ($newValues.Count -ne $value.Count) {
 $svchost.SetValue($valueName, [string[]]$newValues, [Microsoft.Win32.RegistryValueKind]::MultiString)
 $serviceMetadataRemoved++
 }
 }
 } catch { }
 }
 }
 } finally { if ($null -ne $svchost) { $svchost.Dispose() } }

 # --------------------------------------------------------------------
 # SOFTWARE App Paths: remove only entries whose default executable
 # path is absolute and definitely missing.
 # --------------------------------------------------------------------
 foreach ($appPathsBranch in @(
 'Microsoft\Windows\CurrentVersion\App Paths',
 'WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths'
 )) {
 $branch = $null
 try {
 $branch = $softwareRoot.OpenSubKey($appPathsBranch, $true)
 if ($null -eq $branch) { continue }
 foreach ($name in @($branch.GetSubKeyNames())) {
 $key = $null
 try {
 $key = $branch.OpenSubKey($name, $false)
 if ($null -eq $key) { continue }
 $default = [string]$key.GetValue('', '')
 $resolved = Convert-MaxCleanPath $default
 if ($null -ne $resolved -and -not (Test-Path -LiteralPath $resolved -PathType Leaf)) {
 [void]$branch.DeleteSubKeyTree($name)
 $appPathsRemoved++
 }
 } catch { }
 finally { if ($null -ne $key) { $key.Dispose() } }
 }
 } catch { }
 finally { if ($null -ne $branch) { $branch.Dispose() } }
 }

 # --------------------------------------------------------------------
 # D. SOFTWARE uninstall entries: remove only entries with an explicit,
 # absolute InstallLocation that is definitely absent. This avoids
 # deleting MSI entries that legitimately omit InstallLocation.
 # --------------------------------------------------------------------
 foreach ($uninstallBranch in @(
 'Microsoft\Windows\CurrentVersion\Uninstall',
 'WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
 )) {
 $branch = $null
 try {
 $branch = $softwareRoot.OpenSubKey($uninstallBranch, $true)
 if ($null -eq $branch) { continue }
 foreach ($name in @($branch.GetSubKeyNames())) {
 $key = $null
 try {
 $key = $branch.OpenSubKey($name, $false)
 if ($null -eq $key) { continue }
 $location = [string]$key.GetValue('InstallLocation', '')
 if (-not [string]::IsNullOrWhiteSpace($location)) {
 $location = [Environment]::ExpandEnvironmentVariables($location.Trim().Trim('"'))
 if ($location -match '^[A-Za-z]:\\' -and -not (Test-Path -LiteralPath $location)) {
 [void]$branch.DeleteSubKeyTree($name)
 $uninstallRemoved++
 }
 }
 } catch { }
 finally { if ($null -ne $key) { $key.Dispose() } }
 }
 } catch { }
 finally { if ($null -ne $branch) { $branch.Dispose() } }
 }

 # Dispose all handles before unloading.
 $systemRoot.Dispose(); $systemRoot = $null
 $softwareRoot.Dispose(); $softwareRoot = $null
 $machine.Dispose(); $machine = $null
 [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()

 Write-Host ''
 Write-Host 'MAXIMUM-AGGRESSIVE REGISTRY COMPACTION' -ForegroundColor Cyan
 Write-Host (' Disabled/orphan service keys removed : {0}' -f $removedServices) -ForegroundColor Yellow
 Write-Host (' Missing-binary service keys removed : {0}' -f $missingServices) -ForegroundColor Yellow
 Write-Host (' Svchost metadata entries changed : {0}' -f $serviceMetadataRemoved) -ForegroundColor Yellow
 Write-Host (' Orphan App Paths removed : {0}' -f $appPathsRemoved) -ForegroundColor Yellow
 Write-Host (' Orphan uninstall entries removed : {0}' -f $uninstallRemoved) -ForegroundColor Yellow
 Write-Host ' COMPONENTS/CBS servicing database : PRESERVED' -ForegroundColor Cyan

 }
 finally {
 if ($null -ne $systemRoot) { $systemRoot.Dispose() }
 if ($null -ne $softwareRoot) { $softwareRoot.Dispose() }
 if ($null -ne $machine) { $machine.Dispose() }
 [GC]::Collect(); [GC]::WaitForPendingFinalizers()

 if (-not (Invoke-RegUnloadWithRetry -HiveName $systemName -Attempts 40 -DelayMilliseconds 250)) {
 throw "Could not unload maximum-clean SYSTEM hive HKLM\$systemName."
 }
 if (-not (Invoke-RegUnloadWithRetry -HiveName $softwareName -Attempts 40 -DelayMilliseconds 250)) {
 throw "Could not unload maximum-clean SOFTWARE hive HKLM\$softwareName."
 }
 }
}


# ============================================================================
# ULTRA-AGGRESSIVE SOFTWARE HIVE REDUCTION
# ============================================================================
# This pass is deliberately SOFTWARE-only. It first profiles the largest
# registry structures by estimated key/value payload, then removes high-
# confidence disposable/orphaned structures. The profile is written to the
# transcript so the next run can be compared against the previous one.
# # IMPORTANT: registry hives do not expose their physical cell allocation per
# key. The profiler therefore reports an ESTIMATED logical footprint based
# on key names, value names and value data. RegSaveKeyEx(REG_LATEST_FORMAT)
# performs the actual physical compaction afterward.
# # The following classes are intentionally targeted:
# * stale AppX/AppModel repository records whose package directory is gone
# * stale AppXAllUserStore application records
# * stale COM registrations whose referenced server binaries are gone
# * orphan App Paths / uninstall records
# * disposable Explorer/MUI/cache metadata
# * MSI Installer UserData/Products/Features metadata ONLY when explicitly
# enabled below (default enabled for a frozen Micro 11 image)
# # CBS/COMPONENTS, Windows NT core configuration, profile infrastructure and
# servicing policy are NOT touched by this function.
# # safety boundary: no global SOFTWARE empty-key sweep. Empty-key compaction
# is restricted to explicitly disposable Explorer/cache branches.
# ============================================================================
function Invoke-UltraAggressiveSoftwareRegistryReduction {
 param(
 [Parameter(Mandatory = $true)] [string]$WindowsRoot
 )

 $softwareHiveFile = Join-Path $WindowsRoot 'System32\config\SOFTWARE'
 $hiveName = 'zSOFTWARE_ULTRA'
 $loaded = $false
 $removedKeys = 0
 $removedAppModel = 0
 $removedAppxStore = 0
 $removedCom = 0
 $removedCache = 0
 $removedInstaller = 0

 # Frozen/debloated image mode. MSI repair/advertised-install metadata is
 # not useful for this image and can account for a substantial SOFTWARE
 # hive footprint. Set to $false if MSI self-repair must remain available.
 $deleteInstallerMetadata = $true # V30: enable MSI installer metadata cleanup

 function Get-UltraValueBytes {
 param([object]$Value, [Microsoft.Win32.RegistryValueKind]$Kind)
 try {
 if ($null -eq $Value) { return 0L }
 if ($Value -is [byte[]]) { return [int64]$Value.Length }
 if ($Value -is [string]) { return [int64](([Text.Encoding]::Unicode.GetByteCount([string]$Value)) + 2) }
 if ($Value -is [string[]]) { return [int64](([Text.Encoding]::Unicode.GetByteCount(($Value -join [char]0))) + 2) }
 if ($Value -is [int[]]) { return [int64]($Value.Length * 4) }
 if ($Value -is [long[]]) { return [int64]($Value.Length * 8) }
 return 8L
 } catch { return 0L }
 }

 function Measure-UltraRegistryTree {
 param(
 [Parameter(Mandatory=$true)] [Microsoft.Win32.RegistryKey]$Key,
 [Parameter(Mandatory=$true)] [string]$Path,
 [int]$Depth = 0,
 [int]$MaxDepth = 12
 )
 $result = [pscustomobject]@{ Path=$Path; Keys=1L; Values=0L; DataBytes=0L; EstimatedBytes=0L }
 try {
 foreach ($vn in @($Key.GetValueNames())) {
 try {
 $kind = $Key.GetValueKind($vn)
 $v = $Key.GetValue($vn, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 $result.Values++
 $result.DataBytes += Get-UltraValueBytes -Value $v -Kind $kind
 $result.EstimatedBytes += 16 + ([Text.Encoding]::Unicode.GetByteCount([string]$vn)) + (Get-UltraValueBytes -Value $v -Kind $kind)
 } catch {}
 }
 if ($Depth -ge $MaxDepth) { return $result }
 foreach ($sn in @($Key.GetSubKeyNames())) {
 $child=$null
 try {
 $child=$Key.OpenSubKey($sn,$false)
 if ($null -eq $child) { continue }
 $r=Measure-UltraRegistryTree -Key $child -Path ($Path+'\\'+$sn) -Depth ($Depth+1) -MaxDepth $MaxDepth
 $result.Keys += $r.Keys; $result.Values += $r.Values
 $result.DataBytes += $r.DataBytes; $result.EstimatedBytes += $r.EstimatedBytes
 } catch {} finally { if($null -ne $child){$child.Dispose()} }
 }
 } catch {}
 return $result
 }

 function Test-UltraMissingPath {
 param([object]$Value)
 if ($Value -isnot [string]) { return $false }
 $p=[string]$Value
 if ([string]::IsNullOrWhiteSpace($p)) { return $false }
 $p=$p.Trim().Trim('"')

 # Offline-image aware path normalization. Never use host environment
 # expansion to decide whether an offline image file exists.
 $p=$p -replace '(?i)^%SystemRoot%\\', "$WindowsRoot\\"
 $p=$p -replace '(?i)^%windir%\\', "$WindowsRoot\\"
 $p=$p -replace '(?i)^\\SystemRoot\\', "$WindowsRoot\\"
 $p=$p -replace '(?i)^%ProgramFiles%\\', ((Join-Path $WindowsRoot 'Program Files') + '\\')
 $p=$p -replace '(?i)^%ProgramFiles\(x86\)%\\', ((Join-Path $WindowsRoot 'Program Files (x86)') + '\\')
 $p=$p -replace '(?i)^%ProgramData%\\', ((Join-Path $WindowsRoot 'ProgramData') + '\\')

 if ($p -notmatch '^[A-Za-z]:\\') { return $false }

 # A path on another drive is not safe to classify as missing from the
 # offline image.
 $imageDrive=[System.IO.Path]::GetPathRoot($WindowsRoot)
 $pathDrive=[System.IO.Path]::GetPathRoot($p)
 if ($pathDrive -and $imageDrive -and ($pathDrive -ne $imageDrive)) { return $false }

 # Rebase ordinary absolute paths from the image drive into WindowsRoot.
 $drive=[regex]::Escape($imageDrive)
 if ($p -match ('(?i)^' + $drive + 'Windows\\')) {
 $relative=$p.Substring($imageDrive.Length)
 $p=Join-Path $WindowsRoot $relative
 } elseif ($p -match ('(?i)^' + $drive + '(Program Files|Program Files \(x86\)|ProgramData|Users)\\')) {
 $relative=$p.Substring($imageDrive.Length)
 $p=Join-Path $WindowsRoot $relative
 } else {
 return $false
 }

 return -not (Test-Path -LiteralPath $p -PathType Leaf)
 }

 function Remove-UltraOrphanComBranch {
 param([Microsoft.Win32.RegistryKey]$Parent, [string]$BranchPath)
 $removed=0
 $branch=$null
 try {
 $branch=$Parent.OpenSubKey($BranchPath,$true)
 if($null -eq $branch){return 0}
 foreach($name in @($branch.GetSubKeyNames())){
 $k=$null; $missing=$false
 try{
 $k=$branch.OpenSubKey($name,$false); if($null -eq $k){continue}
 foreach($vn in @('InprocServer32','InprocServerX86','InprocHandler32','LocalServer32','LocalServer')){
 if(-not $k.GetValueNames().Contains($vn)){continue}
 $v=$k.GetValue($vn,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 if(Test-UltraMissingPath $v){$missing=$true;break}
 }
 }catch{} finally{if($null -ne $k){$k.Dispose()}}
 if($missing){try{$branch.DeleteSubKeyTree($name);$removed++}catch{}}
 }
 }catch{} finally{if($null -ne $branch){$branch.Dispose()}}
 return $removed
 }

 try {
