 try{
 $k=$root.OpenSubKey($top,$false)
 if($null -ne $k){$profile += Measure-UltraRegistryTree -Key $k -Path $top -MaxDepth 10}
 }catch{}finally{if($null -ne $k){$k.Dispose()}}
 }
 $profile | Sort-Object EstimatedBytes -Descending | Select-Object -First 40 | ForEach-Object {
 Write-Host (' TOP SOFTWARE TREE: {0} | keys={1:N0} values={2:N0} data={3:N2} MB estimate={4:N2} MB' -f $_.Path,$_.Keys,$_.Values,($_.DataBytes/1MB),($_.EstimatedBytes/1MB)) -ForegroundColor Cyan
 }

 # AppModel repository: remove package records only when their package
