 foreach($repoPath in @(
 'Microsoft\Windows\CurrentVersion\AppModel\Repository\Packages',
 'Microsoft\Windows\CurrentVersion\AppModel\Repository\Families',
 'Microsoft\Windows\CurrentVersion\AppModel\Repository\Applications'
 )){
 $branch=$null
