 foreach($vn in @('PackageRootFolder','InstallLocation','Path')){
 $v=$k.GetValue($vn,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 if($v -is [string] -and $v.Trim()){ $pathValue=$v;break }
 }
 }catch{}finally{if($null -ne $k){$k.Dispose()}}
 if((Test-UltraMissingPath $pathValue)){try{$branch.DeleteSubKeyTree($name);$removedAppModel++}catch{}}
 }
 }catch{}finally{if($null -ne $branch){$branch.Dispose()}}
 }

 # AppXAllUserStore: remove application records whose package path is gone.
