 if($null -ne $appx){
 foreach($name in @($appx.GetSubKeyNames())){
 $k=$null;$pv=$null
 try{
 $k=$appx.OpenSubKey($name,$false);if($null -eq $k){continue}
 foreach($vn in @('Path','PackageRootFolder','InstallLocation')){
 $v=$k.GetValue($vn,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 if($v -is [string] -and $v.Trim()){$pv=$v;break}
 }
 }catch{}finally{if($null -ne $k){$k.Dispose()}}
 # Delete only when BOTH conditions are satisfied:
 # - the package identity is confirmed as successfully removed by DISM;
 # - the referenced package path is absent from the OFFLINE image.
 $appxPrefix=$null
 if($name -match '^([^_]+)'){$appxPrefix=$matches[1]}
 $evidence=$false
 if($appxPrefix){
 foreach($removed in @($removedProvisionedAppxPackages)){
 if(([string]$removed) -like ($appxPrefix + '_*')){$evidence=$true;break}
 }
 }
 if($evidence -and (Test-UltraMissingPath $pv)){try{$appx.DeleteSubKeyTree($name);$removedAppxStore++}catch{}}
 }
 }
 }catch{}finally{if($null -ne $appx){$appx.Dispose()}}

 # COM: aggressively remove only registrations whose actual server path
 # is definitely absent. Both native and WOW6432Node trees are scanned.
 if($true){
 foreach($comPath in @(
 'Classes\CLSID','WOW6432Node\Classes\CLSID',
 'Classes\Interface','WOW6432Node\Classes\Interface',
 'Classes\TypeLib','WOW6432Node\Classes\TypeLib'
 )){
 {$removedCom += Remove-UltraOrphanComBranch -Parent $root -BranchPath $comPath}
 }
 }

 # Disposable machine-level caches/remembered UI state. These are not
 # OS boot/service configuration and are regenerated when required.
 if($true){
 foreach($cachePath in @(
 'Microsoft\Windows\CurrentVersion\Explorer\RecentDocs',
 'Microsoft\Windows\CurrentVersion\Explorer\RunMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\UserAssist',
 'Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\OpenSavePidlMRU',
