 'Microsoft\Windows\CurrentVersion\Explorer\Bags',
 'Microsoft\Windows\CurrentVersion\Explorer\MuiCache'
 )){
 try{
 $parts=$cachePath -split '\\';$parent=$root
 for($i=0;$i -lt $parts.Count-1;$i++){
 $next=$parent.OpenSubKey($parts[$i],$true);if($null -eq $next){$parent=$null;break}
 if($parent -ne $root){$parent.Dispose()};$parent=$next
 }
 if($null -ne $parent){$leaf=$parts[-1];if(($parent.GetSubKeyNames() -contains $leaf)){$parent.DeleteSubKeyTree($leaf);$removedCache++}}
 if($null -ne $parent -and $parent -ne $root){$parent.Dispose()}
 }catch{}
 }

 }
 # MSI metadata. This is intentionally a separate, clearly logged switch.
 # It can remove a substantial amount of SOFTWARE hive data in a frozen
 # image, but MSI repair/advertised-install functionality will be lost.
 if($deleteInstallerMetadata){
 foreach($installerPath in @(
 'Microsoft\Windows\CurrentVersion\Installer\UserData',
