 'WOW6432Node\Microsoft\Windows\CurrentVersion\Installer\Products',
 'WOW6432Node\Microsoft\Windows\CurrentVersion\Installer\Features'
 )){
 try{
 $parts=$installerPath -split '\\';$parent=$root
 for($i=0;$i -lt $parts.Count-1;$i++){
 $next=$parent.OpenSubKey($parts[$i],$true);if($null -eq $next){$parent=$null;break}
 if($parent -ne $root){$parent.Dispose()};$parent=$next
 }
 if($null -ne $parent){$leaf=$parts[-1];if($parent.GetSubKeyNames() -contains $leaf){$parent.DeleteSubKeyTree($leaf);$removedInstaller++}}
