 }
 }
 if($null -ne $parent -and $parent -ne $root){$parent.Dispose()}
 }catch{}
 }
 Write-Host ' targeted Classes shell-cache deletion enabled; only explicitly disposable shell-cache branches are removed.' -ForegroundColor Cyan

 # Additional obsolete machine-wide metadata under SOFTWARE\Microsoft.
