 }
 }
 if($null -ne $parent -and $parent -ne $root){$parent.Dispose()}
 }catch{}
 }

 # SAFETY CHANGE:
 # Do NOT recursively remove empty keys across the entire SOFTWARE hive.
 # The previous global sweep could collapse shell/AppModel registry
 # structures that are intentionally sparse but still authoritative.
 # # Empty-key compaction is now limited to explicitly disposable cache
 # branches. Core Microsoft, Explorer, AppModel/AppX, Classes and OOBE
 # registry structures are never traversed by this compactor.
 function Remove-UltraEmptyTargeted {
 param(
 [Microsoft.Win32.RegistryKey]$Parent,
 [int]$Depth = 0,
 [int]$MaxDepth = 32
 )
 if($Depth -ge $MaxDepth){return 0}
 $n=0
 foreach($sn in @($Parent.GetSubKeyNames())){
 $c=$null
 try{
 $c=$Parent.OpenSubKey($sn,$true)
 if($null -ne $c){
 $n += Remove-UltraEmptyTargeted -Parent $c -Depth ($Depth+1) -MaxDepth $MaxDepth
 }
 }catch{}finally{if($null -ne $c){try{$c.Dispose()}catch{}}}
 $check=$null;$empty=$false
 try{
 $check=$Parent.OpenSubKey($sn,$false)
 if($null -ne $check){
 $empty=(@($check.GetSubKeyNames()).Count -eq 0 -and @($check.GetValueNames()).Count -eq 0)
 }
 }catch{}finally{if($null -ne $check){try{$check.Dispose()}catch{}}}
 if($empty){
 try{$Parent.DeleteSubKeyTree($sn);$n++}catch{}
 }
 }
 return $n
 }

 $targetedEmptyRoots = @(
 'Microsoft\Windows\CurrentVersion\Explorer\RecentDocs',
 'Microsoft\Windows\CurrentVersion\Explorer\RunMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\UserAssist',
 'Microsoft\Windows\CurrentVersion\Explorer\ComDlg32',
 'Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery',
 'Microsoft\Windows\CurrentVersion\Explorer\TypedPaths',
 'Microsoft\Windows\CurrentVersion\Explorer\StreamMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\Streams',
 'Microsoft\Windows\CurrentVersion\Explorer\BagMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\Bags',
 'Microsoft\Windows\CurrentVersion\Explorer\MuiCache'
 )

 foreach($targetPath in $targetedEmptyRoots){
 $target=$null
 try{
 $target=$root.OpenSubKey($targetPath,$true)
 if($null -ne $target){
 for($p=1;$p -le 8;$p++){
 $r=0 # V30: disabled; empty-key compaction isolated out
 $removedKeys += $r
 if($r -eq 0){break}
 }
 }
 }catch{}finally{if($null -ne $target){try{$target.Dispose()}catch{}}}
 }

 Write-Host ''
 Write-Host ' global SOFTWARE/NTUSER empty-key recursion DISABLED.' -ForegroundColor Cyan
 Write-Host ' Shell/Explorer cache deletion disabled for isolation test.' -ForegroundColor Cyan
 Write-Host (' AppModel orphan records removed : {0}' -f $removedAppModel) -ForegroundColor Green
 Write-Host (' AppXAllUserStore orphan records : {0}' -f $removedAppxStore) -ForegroundColor Green
 Write-Host (' Orphan COM registrations removed : {0}' -f $removedCom) -ForegroundColor Green
 Write-Host (' Disposable cache branches removed : {0}' -f $removedCache) -ForegroundColor Green
 Write-Host (' Installer metadata roots removed : {0}' -f $removedInstaller) -ForegroundColor Yellow
 Write-Host (' Empty SOFTWARE keys removed : {0}' -f $removedKeys) -ForegroundColor Green
 Write-Host 'ULTRA-AGGRESSIVE SOFTWARE reduction complete.' -ForegroundColor Green

 $root.Dispose();$root=$null;$machine.Dispose();$machine=$null
 [GC]::Collect();[GC]::WaitForPendingFinalizers();[GC]::Collect()
 }
 finally {
 if($null -ne $root){try{$root.Dispose()}catch{}}
 if($null -ne $machine){try{$machine.Dispose()}catch{}}
 [GC]::Collect();[GC]::WaitForPendingFinalizers()
 if($loaded){
 if(-not (Invoke-RegUnloadWithRetry -HiveName $hiveName -Attempts 40 -DelayMilliseconds 250)){throw "Could not unload ultra-clean SOFTWARE hive HKLM\\$hiveName."}
 }
 }
}

