# ============================================================================
# TARGETED SOFTWARE HIVE BLIND DELETION
# ============================================================================
# Explicit allow-list only.  The previous pass mostly named HKCU-style Explorer
# history keys that normally do not exist in the machine SOFTWARE hive.  This
# pass targets machine-SOFTWARE branches already treated as disposable by this
# Micro 11 build, while never recursing through Microsoft or Classes wholesale.
function Invoke-TargetedSoftwareBlindDeletion {
    param([Parameter(Mandatory=$true)][string]$WindowsRoot)

    $softwareHiveFile = Join-Path $WindowsRoot 'System32\config\SOFTWARE'
    $hiveName = 'zSOFTWARE_BLIND'
    $loaded = $false
    $machine = $null
    $root = $null
    $found = 0
    $removed = 0

    # High-value machine SOFTWARE metadata this build already intentionally
    # sacrifices (MSI advertised-install/self-repair metadata).  These paths are
    # bounded leaves; Microsoft, Classes, AppX/AppModel, COM, Windows NT,
    # networking, profiles and servicing roots are never deleted wholesale.
    $blindDeleteBranches = @(
        'Microsoft\Windows\CurrentVersion\Installer\UserData',
        'Microsoft\Windows\CurrentVersion\Installer\Products',
        'Microsoft\Windows\CurrentVersion\Installer\Features',
        'WOW6432Node\Microsoft\Windows\CurrentVersion\Installer\UserData',
        'WOW6432Node\Microsoft\Windows\CurrentVersion\Installer\Products',
        'WOW6432Node\Microsoft\Windows\CurrentVersion\Installer\Features',

        # Explicit shell/cache leaves only; harmlessly skipped when absent.
        'Microsoft\Windows\CurrentVersion\Explorer\MountPoints2',
        'Microsoft\Windows\CurrentVersion\Explorer\RecentDocs',
        'Microsoft\Windows\CurrentVersion\Explorer\RunMRU',
        'Microsoft\Windows\CurrentVersion\Explorer\UserAssist',
        'Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery',
        'Microsoft\Windows\CurrentVersion\Explorer\TypedPaths',
        'Microsoft\Windows\CurrentVersion\Explorer\ComDlg32',
        'Microsoft\Windows\CurrentVersion\Explorer\StreamMRU',
        'Microsoft\Windows\CurrentVersion\Explorer\Streams',
        'Microsoft\Windows\CurrentVersion\Explorer\BagMRU',
        'Microsoft\Windows\CurrentVersion\Explorer\Bags',
        'Microsoft\Windows\CurrentVersion\Explorer\MuiCache',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\BagMRU',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\MuiCache',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\RecentDocs',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\ComDlg32',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\TypedPaths',
        'Classes\Local Settings\Software\Microsoft\Windows\Shell\UserAssist'
    )

    try {
        & reg.exe load "HKLM\$hiveName" $softwareHiveFile *> $null
        if ($LASTEXITCODE -ne 0) { throw 'Could not load SOFTWARE hive for targeted blind deletion.' }
        $loaded = $true

        $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
            [Microsoft.Win32.RegistryHive]::LocalMachine,
            [Microsoft.Win32.RegistryView]::Registry64
        )
        $root = $machine.OpenSubKey($hiveName,$true)
        if ($null -eq $root) { throw "Could not open HKLM\$hiveName." }

        foreach ($branchPath in $blindDeleteBranches) {
            $parts = @($branchPath -split '\\')
            $parent = $root
            $opened = New-Object System.Collections.Generic.List[Microsoft.Win32.RegistryKey]
            try {
                for ($i=0; $i -lt ($parts.Count-1); $i++) {
                    $next = $parent.OpenSubKey($parts[$i],$true)
                    if ($null -eq $next) { $parent = $null; break }
                    [void]$opened.Add($next)
                    $parent = $next
                }
                if ($null -ne $parent) {
                    $leaf = $parts[-1]
                    if ($parent.GetSubKeyNames() -contains $leaf) {
                        $found++
                        try {
                            $parent.DeleteSubKeyTree($leaf,$false)
                            $removed++
                            Write-Host (' BLIND SOFTWARE REMOVED: {0}' -f $branchPath) -ForegroundColor Yellow
                        } catch {
                            Write-Warning ('Could not remove blind SOFTWARE branch: {0}' -f $branchPath)
                        }
                    }
                }
            }
            finally {
                for ($i=$opened.Count-1; $i -ge 0; $i--) {
                    try { $opened[$i].Dispose() } catch {}
                }
            }
        }

        Write-Host (' BLIND SOFTWARE branches found: {0}; removed: {1}' -f $found,$removed) -ForegroundColor Green
        try { $root.Flush() } catch {}
    }
    finally {
        if ($null -ne $root) { try { $root.Dispose() } catch {} }
        if ($null -ne $machine) { try { $machine.Dispose() } catch {} }
        [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()
        if ($loaded) {
            if (-not (Invoke-RegUnloadWithRetry -HiveName $hiveName -Attempts 40 -DelayMilliseconds 250)) {
                throw "Could not unload targeted blind-deletion SOFTWARE hive HKLM\$hiveName."
            }
        }
    }
}

Invoke-TargetedSoftwareBlindDeletion -WindowsRoot (Join-Path $scratchDir 'Windows')


