    $hiveName = 'zSOFTWARE_WRBLIND'
    $loaded = $false
    $machine = $null
    $root = $null

    function Invoke-BlindRegProcess {
        param([Parameter(Mandatory=$true)][string[]]$Arguments)
        $p = Start-Process -FilePath "$env:SystemRoot\System32\reg.exe" `
            -ArgumentList $Arguments -WindowStyle Hidden -Wait -PassThru -ErrorAction Stop
        return [int]$p.ExitCode
    }

    function Mount-BlindSoftwareHive {
        param([string]$Name,[string]$HiveFile)
        try { [void](Invoke-BlindRegProcess -Arguments @('unload',("HKLM\" + $Name))) } catch {}
        [GC]::Collect(); [GC]::WaitForPendingFinalizers()
        for ($attempt=1; $attempt -le 20; $attempt++) {
            try {
                if ((Invoke-BlindRegProcess -Arguments @('load',("HKLM\" + $Name),$HiveFile)) -eq 0) { return $true }
            } catch {}
            Start-Sleep -Milliseconds 250
        }
        return $false
    }

    function Dismount-BlindSoftwareHive {
        param([string]$Name)
        for ($attempt=1; $attempt -le 40; $attempt++) {
            [GC]::Collect(); [GC]::WaitForPendingFinalizers()
            try {
                if ((Invoke-BlindRegProcess -Arguments @('unload',("HKLM\" + $Name))) -eq 0) { return $true }
            } catch {}
            Start-Sleep -Milliseconds 250
        }
        return $false
    }

    try {
        if (-not (Mount-BlindSoftwareHive -Name $hiveName -HiveFile $softwareHiveFile)) {
            throw ('Could not load blind-test SOFTWARE hive HKLM\' + $hiveName)
        }
        $loaded = $true

        # IMPORTANT: v3 deliberately avoids reg.exe import.
        # The v2 bulk .reg file can fail as a whole on one malformed/unsupported
        # registry-file record. Direct RegistryKey operations isolate failures.
        $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
            [Microsoft.Win32.RegistryHive]::LocalMachine,
            [Microsoft.Win32.RegistryView]::Registry64
        )
        $root = $machine.OpenSubKey($hiveName,$true)
        if ($null -eq $root) { throw ('Could not open HKLM\' + $hiveName + ' writable.') }

        $keysRemoved = 0
        $keysMissing = 0
        $keyErrors = 0

        foreach ($relativePath in $blindKeys) {
            try {
                $probe = $root.OpenSubKey($relativePath,$false)
                if ($null -eq $probe) {
                    $keysMissing++
                    continue
                }
                $probe.Dispose()
                $root.DeleteSubKeyTree($relativePath,$false)
                $keysRemoved++
            }
            catch {
                $keyErrors++
            }
        }

        $valuesRemoved = 0
        $valuesMissing = 0
        $valueErrors = 0

        foreach ($entry in $blindValuesRaw) {
            $parts = $entry -split "`t",2
            if ($parts.Count -ne 2) { $valueErrors++; continue }

            $relativePath = $parts[0]
            $valueName = $parts[1]
            if ($valueName -eq '(Default)') { $valueName = '' }

            $key = $null
            try {
                $key = $root.OpenSubKey($relativePath,$true)
                if ($null -eq $key) {
                    # Usually means an ancestor was already removed by the key pass.
                    $valuesMissing++
                    continue
                }

                if ($key.GetValueNames() -contains $valueName) {
                    $key.DeleteValue($valueName,$false)
                    $valuesRemoved++
                } else {
                    $valuesMissing++
                }
            }
            catch {
                $valueErrors++
            }
            finally {
                if ($null -ne $key) { try { $key.Dispose() } catch {} }
            }
        }

        try { $root.Flush() } catch {}

        Write-Host (' AdvancedCleanup BLIND TEST keys: total={0}; removed={1}; already-missing={2}; errors={3}' -f `
            $blindKeys.Count,$keysRemoved,$keysMissing,$keyErrors) -ForegroundColor Magenta
        Write-Host (' AdvancedCleanup BLIND TEST values: total={0}; removed={1}; already-missing={2}; errors={3}' -f `
            $blindValuesRaw.Count,$valuesRemoved,$valuesMissing,$valueErrors) -ForegroundColor Magenta
        Write-Host ' WARNING: unfiltered blind deletion mode - VM TEST ONLY' -ForegroundColor Yellow
    }
    finally {
        if ($null -ne $root) { try { $root.Dispose() } catch {}; $root = $null }
        if ($null -ne $machine) { try { $machine.Dispose() } catch {}; $machine = $null }
        [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()

        if ($loaded) {
            if (-not (Dismount-BlindSoftwareHive -Name $hiveName)) {
                throw ('Could not unload blind-test SOFTWARE hive HKLM\' + $hiveName)
            }
        }
    }
}

