# ============================================================================
# ADVANCED CLEANUP SHARED-METADATA REDUCTION - EXPERIMENTAL VM TEST
# Runs after the proven blind all-delta pass.
#
# Deep comparison showed most remaining differing values are concentrated in:
#   - Microsoft\Windows\CurrentVersion\Component Based Servicing
#   - Microsoft\Fusion\GACChangeNotification
#   - Microsoft\.NETFramework\NGenQueue
#
# These are servicing/cache/queue metadata. This test deliberately sacrifices
# servicing/self-repair metadata. It DOES NOT delete Classes\CLSID, Interface,
# TypeLib, SideBySide, Explorer, shell associations, VMware/VirtualBox entries,
# or the restored Calculator/Notepad/Paint registrations.
# ============================================================================
function Invoke-AdvancedCleanupSharedMetadataTest {
    param([Parameter(Mandatory=$true)][string]$WindowsRoot)

    $softwareHiveFile = Join-Path $WindowsRoot 'System32\config\SOFTWARE'
    if (-not (Test-Path -LiteralPath $softwareHiveFile)) {
        throw 'Shared-metadata test: offline SOFTWARE hive not found.'
    }

    $hiveName = 'zSOFTWARE_WRMETA'
    $loaded = $false
    $machine = $null
    $root = $null

    $targets = @(
        'Microsoft\Windows\CurrentVersion\Component Based Servicing',
        'Microsoft\Fusion\GACChangeNotification',
        'Microsoft\.NETFramework\NGenQueue'
    )

    function Invoke-WRMetaReg {
        param([Parameter(Mandatory=$true)][string[]]$Arguments)
        $p = Start-Process -FilePath "$env:SystemRoot\System32\reg.exe" `
            -ArgumentList $Arguments -WindowStyle Hidden -Wait -PassThru -ErrorAction Stop
        [int]$p.ExitCode
    }

    try {
        try { [void](Invoke-WRMetaReg -Arguments @('unload',("HKLM\" + $hiveName))) } catch {}
        [GC]::Collect()
        [GC]::WaitForPendingFinalizers()

        for ($attempt = 1; $attempt -le 20; $attempt++) {
            try {
                if ((Invoke-WRMetaReg -Arguments @('load',("HKLM\" + $hiveName),$softwareHiveFile)) -eq 0) {
                    $loaded = $true
                    break
                }
            } catch {}
            Start-Sleep -Milliseconds 250
        }
        if (-not $loaded) {
            throw ('Could not load shared-metadata SOFTWARE hive HKLM\' + $hiveName)
        }

        $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
            [Microsoft.Win32.RegistryHive]::LocalMachine,
            [Microsoft.Win32.RegistryView]::Registry64
        )
        $root = $machine.OpenSubKey($hiveName,$true)
        if ($null -eq $root) {
            throw ('Could not open HKLM\' + $hiveName + ' writable.')
        }

        $removed = 0
        $missing = 0
        $errors = 0

        foreach ($relativePath in $targets) {
            try {
                $probe = $root.OpenSubKey($relativePath,$false)
                if ($null -eq $probe) {
                    $missing++
                    continue
                }
                $probe.Dispose()

                $root.DeleteSubKeyTree($relativePath,$false)
                $removed++
                Write-Host (' AdvancedCleanup shared metadata REMOVED: {0}' -f $relativePath) -ForegroundColor Magenta
            }
            catch {
                $errors++
                Write-Host (' AdvancedCleanup shared metadata ERROR: {0} | {1}' -f $relativePath,$_.Exception.Message) -ForegroundColor Yellow
            }
        }

        try { $root.Flush() } catch {}

        Write-Host (' AdvancedCleanup shared metadata test: targets={0}; removed={1}; missing={2}; errors={3}' -f `
            $targets.Count,$removed,$missing,$errors) -ForegroundColor Magenta
        Write-Host ' WARNING: experimental servicing/cache metadata deletion - VM TEST ONLY' -ForegroundColor Yellow
    }
    finally {
        if ($null -ne $root) { try { $root.Dispose() } catch {}; $root = $null }
        if ($null -ne $machine) { try { $machine.Dispose() } catch {}; $machine = $null }

        [GC]::Collect()
        [GC]::WaitForPendingFinalizers()
        [GC]::Collect()

        if ($loaded) {
            $unloaded = $false
            for ($attempt = 1; $attempt -le 40; $attempt++) {
                try {
                    if ((Invoke-WRMetaReg -Arguments @('unload',("HKLM\" + $hiveName))) -eq 0) {
                        $unloaded = $true
                        break
                    }
                } catch {}
                Start-Sleep -Milliseconds 250
            }
            if (-not $unloaded) {
                throw ('Could not unload shared-metadata SOFTWARE hive HKLM\' + $hiveName)
            }
        }
    }
}

