WOW6432Node\Microsoft\Windows\CurrentVersion\XWizards\Components\{7940ACF8-60BA-4213-A7C3-F3B400EE266D}
WOW6432Node\Microsoft\Windows\CurrentVersion\XWizards\Components\{984F9804-3314-4FA4-AC8C-E688D4133C51}
'@ -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }

    # Same safety boundary used by the successful recursive discovery pass.
    $softwareProtectedPrefixes = @(
        'Microsoft\Cryptography',
        'Microsoft\Ole',
        'Microsoft\Rpc',
        'Microsoft\SystemCertificates',
        'Microsoft\WBEM',
        'Microsoft\Windows NT\CurrentVersion\ProfileList',
        'Microsoft\Windows NT\CurrentVersion\Winlogon',
        'Microsoft\Windows NT\CurrentVersion\Image File Execution Options',
        'Microsoft\Windows\CurrentVersion\Authentication',
        'Microsoft\Windows\CurrentVersion\Explorer',
        'Microsoft\Windows\CurrentVersion\Policies',
        'Microsoft\Windows\CurrentVersion\Run',
        'Microsoft\Windows\CurrentVersion\RunOnce',
        'Microsoft\Windows\CurrentVersion\Shell Extensions',
        'Microsoft\Windows\CurrentVersion\SideBySide',
        'Microsoft\Windows\CurrentVersion\Setup',
        'Microsoft\Windows\CurrentVersion\Uninstall',
        'Microsoft\Windows\CurrentVersion\App Paths',
        'Microsoft\WindowsRuntime',
        'Microsoft\PolicyManager',
        'Microsoft\Provisioning',
        'Classes\*\shell\runas',
        'Classes\Directory\shell\runas',
        'Classes\Drive\shell\runas',
        'Classes\Directory\Background\shell\cmd',
        'Classes\Directory\shell\cmd',
        'Classes\Drive\shell\cmd',
        'Classes\Applications\photoviewer.dll',
        'Classes\PhotoViewer.FileAssoc'
    )

    function Test-WRStaticProtectedPath {
        param([string]$Path)
        $p = $Path.Trim('\')
        foreach ($prefix in $softwareProtectedPrefixes) {
            $q = $prefix.Trim('\')
            if ($p.Equals($q,[System.StringComparison]::OrdinalIgnoreCase) -or
                $p.StartsWith($q + '\',[System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        }
        return $false
    }

    $hiveName = 'zWR_STATIC_SOFTWARE'
    $loaded = $false
    $machine = $null
    $root = $null
    $regFile = Join-Path $env:TEMP ('Micro11-WRStatic-' + [Guid]::NewGuid().ToString('N') + '.reg')

    try {
        & reg.exe load ('HKLM\' + $hiveName) $softwareHiveFile *> $null
        if ($LASTEXITCODE -ne 0) { throw ('Could not load registry hive HKLM\' + $hiveName) }
        $loaded = $true

        $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
            [Microsoft.Win32.RegistryHive]::LocalMachine,
            [Microsoft.Win32.RegistryView]::Registry64
        )
        $root = $machine.OpenSubKey($hiveName,$false)
        if ($null -eq $root) { throw ('Could not open HKLM\' + $hiveName + ' read-only.') }

        # Only queue paths that still exist in this image. This keeps the import
        # compact when earlier cleanup stages have already removed an entry.
        $queue = New-Object System.Collections.Generic.List[string]
        $protected = 0
        foreach ($relativePath in $knownAbsentSoftware) {
            if (Test-WRStaticProtectedPath -Path $relativePath) {
                $protected++
                continue
            }
            $probe = $null
            try {
                $probe = $root.OpenSubKey($relativePath,$false)
                if ($null -ne $probe) { [void]$queue.Add($relativePath) }
            } catch {
                # A failed read probe is not treated as permission to delete.
            } finally {
                if ($null -ne $probe) { try { $probe.Dispose() } catch {} }
            }
        }

        # Close all registry handles before deletion. The previous recursive
        # implementation proved that keeping .NET handles open during mutation
        # can trigger access/share problems on offline Windows hives.
        if ($null -ne $root) { try { $root.Dispose() } catch {}; $root = $null }
        if ($null -ne $machine) { try { $machine.Dispose() } catch {}; $machine = $null }
        [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()

        if ($queue.Count -gt 0) {
            # A .reg deletion file lets ONE reg.exe process perform the whole
            # known-good deletion set instead of launching reg.exe thousands
            # of times. Encoding=Unicode is required by reg.exe import.
            $regLines = New-Object System.Collections.Generic.List[string]
            [void]$regLines.Add('Windows Registry Editor Version 5.00')
            [void]$regLines.Add('')
            foreach ($relativePath in $queue) {
                [void]$regLines.Add(('[-HKEY_LOCAL_MACHINE\{0}\{1}]' -f $hiveName,$relativePath))
                [void]$regLines.Add('')
            }
            [System.IO.File]::WriteAllLines($regFile,$regLines,[System.Text.Encoding]::Unicode)

            $regArgs = @('import',$regFile)
            $p = Start-Process -FilePath "$env:SystemRoot\System32\reg.exe" -ArgumentList $regArgs -WindowStyle Hidden -Wait -PassThru -ErrorAction Stop
            if ($p.ExitCode -ne 0) {
                throw ('Fast AdvancedCleanup static registry import failed with reg.exe exit code ' + $p.ExitCode)
            }
        }

        # Verify only the queued known-good paths. This is ~2,500 lookups rather
        # than recursively walking ~187,000 SOFTWARE keys.
        $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
            [Microsoft.Win32.RegistryHive]::LocalMachine,
            [Microsoft.Win32.RegistryView]::Registry64
        )
        $root = $machine.OpenSubKey($hiveName,$false)
        $removed = 0
        $remaining = 0
        foreach ($relativePath in $queue) {
            $probe = $null
            try {
                $probe = $root.OpenSubKey($relativePath,$false)
                if ($null -eq $probe) { $removed++ } else { $remaining++ }
            } catch {
                $remaining++
            } finally {
                if ($null -ne $probe) { try { $probe.Dispose() } catch {} }
            }
        }

        Write-Host (' AdvancedCleanup static delta SOFTWARE: known={0}; present={1}; removed={2}; remaining={3}; protected={4}' -f $knownAbsentSoftware.Count,$queue.Count,$removed,$remaining,$protected) -ForegroundColor Green
        Write-Host ' AdvancedCleanup static delta DRIVERS : skipped (discovery run removed 0 branches)' -ForegroundColor DarkGray
    }
    finally {
        if ($null -ne $root) { try { $root.Dispose() } catch {} }
        if ($null -ne $machine) { try { $machine.Dispose() } catch {} }
        Remove-Item -LiteralPath $regFile -Force -ErrorAction SilentlyContinue
        [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()
        if ($loaded) {
            if (-not (Invoke-RegUnloadWithRetry -HiveName $hiveName -Attempts 40 -DelayMilliseconds 250)) {
                throw ('Could not unload AdvancedCleanup static-delta hive HKLM\' + $hiveName)
            }
        }
    }
}

Invoke-AdvancedCleanupStaticDeltaCleanupFast -WindowsRoot (Join-Path $scratchDir 'Windows')


# ============================================================================
# SOFTWARE OBSOLETE-CONTENT GARBAGE COLLECTOR
# ============================================================================
# Replaces the former whole SOFTWARE\Microsoft deletion path.
# # Deletion policy:
# * Never delete SOFTWARE\Microsoft as a whole.
# * Prefer two independent signals for package/application registrations:
# (1) DISM actually removed the package/application, and/or
# (2) every concrete backing filesystem path recorded by the key is gone.
# * Entries with no concrete evidence are preserved.
# * CBS/COMPONENTS, servicing policy, Windows NT core configuration, network
# configuration and profile infrastructure are outside this collector.
# # The later hive rebuild/RegSaveKeyEx pass performs the physical compaction.
# ============================================================================
function Invoke-SoftwareObsoleteContentGarbageCollector {
 param(
 [Parameter(Mandatory = $true)] [string]$WindowsRoot
 )

 $softwareHiveFile = Join-Path $WindowsRoot 'System32\config\SOFTWARE'
 $imageRoot = Split-Path -Path $WindowsRoot -Parent
 $hiveName = 'zSOFTWARE_GC'
 $loaded = $false
 $machine = $null
 $root = $null

 $stats = [ordered]@{
 RemovedPackageRegistryRecords = 0
 AppPaths = 0
 Uninstall = 0
 RegisteredApplications = 0
 SharedDllValues = 0
 ComClassRegistrations = 0
 ClassesApplicationRecords = 0
 InstallerClassRoots = 0
 DisposableCacheRoots = 0
 EmptyKeys = 0
 }

 # This image is intentionally frozen/minimal and the existing ultra pass
 # already sacrifices MSI self-repair metadata. Mirror that policy for the
 # corresponding Classes\Installer registration databases as well.
 $removeFrozenMsiClassMetadata = $true

 function Convert-GcRegistryPathToOfflinePath {
 param([AllowNull()][object]$Value)
 if ($Value -isnot [string]) { return $null }
 $text = ([string]$Value).Trim()
 if (-not $text) { return $null }

 # Strip command-line quoting/arguments and DisplayIcon resource suffix.
 if ($text -match '^"([^\"]+)"') {
 $text = $Matches[1]
 }
 else {
 $text = ($text -replace '^\s*([^,]+),-?\d+\s*$', '$1').Trim()
 if ($text -match '^(.*?\.(?:exe|dll|ocx|cpl|sys|msi|msc|scr|com|bat|cmd))(?:\s+.*)?$') {
 $text = $Matches[1]
 }
 }
 $text = $text.Trim('"').Trim()
 if (-not $text) { return $null }

 # Do not let host environment expansion redirect checks to the host OS.
 $text = $text -replace '(?i)^%SystemRoot%', $WindowsRoot
 $text = $text -replace '(?i)^%windir%', $WindowsRoot
 $text = $text -replace '(?i)^\\SystemRoot', $WindowsRoot
 $text = $text -replace '(?i)^%ProgramFiles\(x86\)%', (Join-Path $imageRoot 'Program Files (x86)')
 $text = $text -replace '(?i)^%ProgramFiles%', (Join-Path $imageRoot 'Program Files')
 $text = $text -replace '(?i)^%ProgramData%', (Join-Path $imageRoot 'ProgramData')

 # Rebase ordinary C:\Windows / Program Files style paths into the mounted image.
 if ($text -match '^[A-Za-z]:\\Windows(?:\\|$)') {
 $text = $text -replace '^[A-Za-z]:\\Windows', [Regex]::Escape($WindowsRoot)
 $text = $text -replace '\\\\', '\'
 }
 elseif ($text -match '^[A-Za-z]:\\Program Files \(x86\)(?:\\|$)') {
 $pf86 = Join-Path $imageRoot 'Program Files (x86)'
 $text = $text -replace '^[A-Za-z]:\\Program Files \(x86\)', [Regex]::Escape($pf86)
 $text = $text -replace '\\\\', '\'
 }
 elseif ($text -match '^[A-Za-z]:\\Program Files(?:\\|$)') {
 $pf = Join-Path $imageRoot 'Program Files'
 $text = $text -replace '^[A-Za-z]:\\Program Files', [Regex]::Escape($pf)
 $text = $text -replace '\\\\', '\'
 }
 elseif ($text -match '^[A-Za-z]:\\ProgramData(?:\\|$)') {
 $pd = Join-Path $imageRoot 'ProgramData'
 $text = $text -replace '^[A-Za-z]:\\ProgramData', [Regex]::Escape($pd)
 $text = $text -replace '\\\\', '\'
 }
 elseif ($text -match '^[A-Za-z]:\\Users(?:\\|$)') {
 $users = Join-Path $imageRoot 'Users'
 $text = $text -replace '^[A-Za-z]:\\Users', [Regex]::Escape($users)
 $text = $text -replace '\\\\', '\'
 }

 # Expand only variables that are safe after offline rebasing.
 if ($text -match '%[^%]+%') { return $null }
 if (-not [System.IO.Path]::IsPathRooted($text)) { return $null }
 return $text
 }

 function Test-GcConcretePathMissing {
 param([AllowNull()][object]$Value)
 $p = Convert-GcRegistryPathToOfflinePath -Value $Value
 if (-not $p) { return $false }
 try { return -not (Test-Path -LiteralPath $p) } catch { return $false }
 }

 function Get-GcEvidencePaths {
 param(
 [Parameter(Mandatory=$true)][Microsoft.Win32.RegistryKey]$Key,
 [string[]]$ValueNames = @('','Path','InstallLocation','PackageRootFolder','DisplayIcon','UninstallString','QuietUninstallString','LocalPackage')
 )
 $paths = New-Object System.Collections.Generic.List[string]
 foreach ($vn in $ValueNames) {
 try {
 $v = $Key.GetValue($vn,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 $p = Convert-GcRegistryPathToOfflinePath -Value $v
 if ($p) { [void]$paths.Add($p) }
 } catch {}
 }
 return @($paths | Select-Object -Unique)
 }

 function Test-GcAllEvidencePathsMissing {
 param([string[]]$Paths)
 if (@($Paths).Count -eq 0) { return $false }
 foreach ($p in @($Paths)) {
 try { if (Test-Path -LiteralPath $p) { return $false } } catch { return $false }
 }
 return $true
 }

 function Remove-GcChildByPath {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$Path)
 $parts = @($Path -split '\\')
 if ($parts.Count -lt 1) { return $false }
 $parent = $Root
 $opened = New-Object System.Collections.Generic.List[Microsoft.Win32.RegistryKey]
 try {
 for ($i=0; $i -lt ($parts.Count-1); $i++) {
 $next = $parent.OpenSubKey($parts[$i],$true)
 if ($null -eq $next) { return $false }
 [void]$opened.Add($next)
 $parent = $next
 }
 $leaf = $parts[-1]
 if (@($parent.GetSubKeyNames()) -notcontains $leaf) { return $false }
 $parent.DeleteSubKeyTree($leaf,$false)
 return $true
 }
 catch { return $false }
 finally {
 for ($i=$opened.Count-1; $i -ge 0; $i--) { try { $opened[$i].Dispose() } catch {} }
 }
 }

 function Get-GcRemovedAppxPrefixes {
 $set = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
 foreach ($pkg in @($removedProvisionedAppxPackages)) {
 $n = [string]$pkg
 if (-not $n) { continue }
 $prefix = ($n -split '_')[0]
 if ($prefix -and $prefix.Length -ge 6) { [void]$set.Add($prefix) }
 }
 return $set
 }

 function Get-GcRemovedCbsBases {
 $set = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
 foreach ($pkg in @($removedPackageIdentities)) {
 $n = [string]$pkg
 if (-not $n) { continue }
 $base = ($n -split '~')[0] -replace '(?i)\.cab$',''
 if ($base -and $base.Length -ge 8) { [void]$set.Add($base) }
 }
 return $set
 }

 function Test-GcNameMatchesRemovedPackage {
 param([string]$Name,[System.Collections.Generic.HashSet[string]]$AppxPrefixes,[System.Collections.Generic.HashSet[string]]$CbsBases)
 if (-not $Name) { return $false }
 foreach ($p in $AppxPrefixes) { if ($Name.IndexOf($p,[StringComparison]::OrdinalIgnoreCase) -ge 0) { return $true } }
 foreach ($p in $CbsBases) { if ($Name.IndexOf($p,[StringComparison]::OrdinalIgnoreCase) -ge 0) { return $true } }
 return $false
 }

 function Remove-GcPackageRepositoryOrphans {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath,[System.Collections.Generic.HashSet[string]]$AppxPrefixes,[System.Collections.Generic.HashSet[string]]$CbsBases)
 $removed = 0
 $branch = $null
 try {
 $branch = $Root.OpenSubKey($BranchPath,$true)
 if ($null -eq $branch) { return 0 }
 foreach ($name in @($branch.GetSubKeyNames())) {
 $k=$null
 try {
 $k=$branch.OpenSubKey($name,$false)
 if ($null -eq $k) { continue }
 $paths = Get-GcEvidencePaths -Key $k -ValueNames @('PackageRootFolder','InstallLocation','Path','PackagePath','RootFolder')
 $removedEvidence = Test-GcNameMatchesRemovedPackage -Name $name -AppxPrefixes $AppxPrefixes -CbsBases $CbsBases
 $allMissing = Test-GcAllEvidencePathsMissing -Paths $paths
 # A removed-package name alone is not enough. Require missing backing
 # path evidence, or an exact AppX removed-package prefix plus no path.
 $exactRemovedAppx = $false
 foreach ($p in $AppxPrefixes) {
 if ($name.StartsWith($p,[StringComparison]::OrdinalIgnoreCase)) { $exactRemovedAppx=$true; break }
 }
 }
 finally { if ($null -ne $k) { try{$k.Dispose()}catch{} } }
 if ($allMissing -or ($removedEvidence -and $exactRemovedAppx -and @($paths).Count -eq 0)) {
 try { $branch.DeleteSubKeyTree($name,$false); $removed++ } catch {}
 }
 }
 } catch {} finally { if ($null -ne $branch) { try{$branch.Dispose()}catch{} } }
 return $removed
 }

 function Remove-GcAppPaths {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath)
 $removed=0;$branch=$null
 try {
 $branch=$Root.OpenSubKey($BranchPath,$true); if($null -eq $branch){return 0}
 foreach($name in @($branch.GetSubKeyNames())){
 $k=$null
 try {
 $k=$branch.OpenSubKey($name,$false);if($null -eq $k){continue}
 $paths=Get-GcEvidencePaths -Key $k -ValueNames @('','Path')
 } finally {if($null -ne $k){try{$k.Dispose()}catch{}}}
 if(Test-GcAllEvidencePathsMissing -Paths $paths){try{$branch.DeleteSubKeyTree($name,$false);$removed++}catch{}}
 }
 }catch{}finally{if($null -ne $branch){try{$branch.Dispose()}catch{}}}
 return $removed
 }

 function Remove-GcUninstallOrphans {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath)
 $removed=0;$branch=$null
 try {
 $branch=$Root.OpenSubKey($BranchPath,$true);if($null -eq $branch){return 0}
 foreach($name in @($branch.GetSubKeyNames())){
 $k=$null
 try{
 $k=$branch.OpenSubKey($name,$false);if($null -eq $k){continue}
 $windowsInstaller=[int]($k.GetValue('WindowsInstaller',0)) -eq 1
 $systemComponent=[int]($k.GetValue('SystemComponent',0)) -eq 1
 $releaseType=[string]$k.GetValue('ReleaseType','')
 # Keep servicing/hotfix/update registrations even if their display
 # paths are not conventional filesystem paths.
 if($systemComponent -or $releaseType -match '(?i)update|hotfix|security'){continue}
 $paths=Get-GcEvidencePaths -Key $k -ValueNames @('InstallLocation','DisplayIcon','UninstallString','QuietUninstallString')
 if($windowsInstaller -and @($paths).Count -eq 0){continue}
 }finally{if($null -ne $k){try{$k.Dispose()}catch{}}}
 if(Test-GcAllEvidencePathsMissing -Paths $paths){try{$branch.DeleteSubKeyTree($name,$false);$removed++}catch{}}
 }
 }catch{}finally{if($null -ne $branch){try{$branch.Dispose()}catch{}}}
 return $removed
 }

 function Remove-GcRegisteredApplicationsOrphans {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath)
 $removed=0;$branch=$null
 try {
 $branch=$Root.OpenSubKey($BranchPath,$true);if($null -eq $branch){return 0}
 foreach($vn in @($branch.GetValueNames())){
 try{
 $target=[string]$branch.GetValue($vn,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 if(-not $target){continue}
 $target=$target -replace '^HKEY_LOCAL_MACHINE\\','' -replace '^HKLM\\','' -replace '^SOFTWARE\\',''
 $k=$Root.OpenSubKey($target,$false)
 if($null -eq $k){$branch.DeleteValue($vn,$false);$removed++}else{$k.Dispose()}
 }catch{}
 }
 }catch{}finally{if($null -ne $branch){try{$branch.Dispose()}catch{}}}
 return $removed
 }

 function Remove-GcSharedDllValues {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath)
 $removed=0;$branch=$null
 try {
 $branch=$Root.OpenSubKey($BranchPath,$true);if($null -eq $branch){return 0}
 foreach($vn in @($branch.GetValueNames())){
 $p=Convert-GcRegistryPathToOfflinePath -Value $vn
 if($p){try{if(-not(Test-Path -LiteralPath $p)){$branch.DeleteValue($vn,$false);$removed++}}catch{}}
 }
 }catch{}finally{if($null -ne $branch){try{$branch.Dispose()}catch{}}}
 return $removed
 }

 function Remove-GcComClsids {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath)
 $removed=0;$branch=$null
 $serverSubs=@('InprocServer32','InprocServerX86','InprocHandler32','LocalServer32','LocalServer')
 try {
 $branch=$Root.OpenSubKey($BranchPath,$true);if($null -eq $branch){return 0}
 foreach($name in @($branch.GetSubKeyNames())){
 $cls=$null;$paths=New-Object System.Collections.Generic.List[string]
 try{
 $cls=$branch.OpenSubKey($name,$false);if($null -eq $cls){continue}
 foreach($sub in $serverSubs){
 $srv=$null
 try{
 $srv=$cls.OpenSubKey($sub,$false);if($null -eq $srv){continue}
 foreach($vn in @('','ServerExecutable')){
 $v=$srv.GetValue($vn,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 $p=Convert-GcRegistryPathToOfflinePath -Value $v
 if($p){[void]$paths.Add($p)}
 }
 }catch{}finally{if($null -ne $srv){try{$srv.Dispose()}catch{}}}
 }
 }catch{}finally{if($null -ne $cls){try{$cls.Dispose()}catch{}}}
 if(Test-GcAllEvidencePathsMissing -Paths @($paths | Select-Object -Unique)){
 try{$branch.DeleteSubKeyTree($name,$false);$removed++}catch{}
 }
 }
 }catch{}finally{if($null -ne $branch){try{$branch.Dispose()}catch{}}}
 return $removed
 }

 function Remove-GcClassesApplications {
 param([Microsoft.Win32.RegistryKey]$Root,[string]$BranchPath)
 $removed=0;$branch=$null
 try{
 $branch=$Root.OpenSubKey($BranchPath,$true);if($null -eq $branch){return 0}
 foreach($name in @($branch.GetSubKeyNames())){
 $app=$null;$cmd=$null
 try{
 $app=$branch.OpenSubKey($name,$false);if($null -eq $app){continue}
 $cmd=$app.OpenSubKey('shell\open\command',$false)
 if($null -eq $cmd){continue}
 $v=$cmd.GetValue('',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
 $p=Convert-GcRegistryPathToOfflinePath -Value $v
 }catch{$p=$null}finally{if($null -ne $cmd){try{$cmd.Dispose()}catch{}};if($null -ne $app){try{$app.Dispose()}catch{}}}
 if($p){try{if(-not(Test-Path -LiteralPath $p)){$branch.DeleteSubKeyTree($name,$false);$removed++}}catch{}}
 }
 }catch{}finally{if($null -ne $branch){try{$branch.Dispose()}catch{}}}
 return $removed
 }

 function Remove-GcEmptyKeys {
 param([Microsoft.Win32.RegistryKey]$Parent,[int]$Depth=0,[int]$MaxDepth=32)
 if($Depth -ge $MaxDepth){return 0}
 $removed=0
 foreach($name in @($Parent.GetSubKeyNames())){
 $child=$null
 try{$child=$Parent.OpenSubKey($name,$true);if($null -ne $child){$removed += Remove-GcEmptyKeys -Parent $child -Depth ($Depth+1) -MaxDepth $MaxDepth}}
 catch{}finally{if($null -ne $child){try{$child.Dispose()}catch{}}}
 $check=$null;$empty=$false
 try{$check=$Parent.OpenSubKey($name,$false);if($null -ne $check){$empty=(@($check.GetSubKeyNames()).Count -eq 0 -and @($check.GetValueNames()).Count -eq 0)}}
 catch{}finally{if($null -ne $check){try{$check.Dispose()}catch{}}}
 if($empty){try{$Parent.DeleteSubKeyTree($name,$false);$removed++}catch{}}
 }
 return $removed
 }

 try {
 if(-not(Test-Path -LiteralPath $softwareHiveFile -PathType Leaf)){throw "SOFTWARE hive not found: $softwareHiveFile"}
 & reg.exe unload "HKLM\$hiveName" >$null 2>&1
 & reg.exe load "HKLM\$hiveName" "$softwareHiveFile" >$null 2>&1
 if($LASTEXITCODE -ne 0){throw "Could not load SOFTWARE hive for obsolete-content garbage collection."}
 $loaded=$true

 $machine=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,[Microsoft.Win32.RegistryView]::Registry64)
 $root=$machine.OpenSubKey($hiveName,$true)
 if($null -eq $root){throw "Could not open HKLM\$hiveName."}

 Write-Host ''
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host 'SOFTWARE OBSOLETE-CONTENT GARBAGE COLLECTOR' -ForegroundColor Cyan
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host (' Successfully removed provisioned AppX packages available as evidence: {0}' -f @($removedProvisionedAppxPackages).Count) -ForegroundColor Gray
 Write-Host (' Successfully removed CBS/FOD package identities available as evidence : {0}' -f $removedPackageIdentities.Count) -ForegroundColor Gray

 $appxPrefixes=Get-GcRemovedAppxPrefixes
 $cbsBases=Get-GcRemovedCbsBases

 # only SharedDLL stale-value cleanup is enabled in this
 # evidence-based garbage-collector pass. All other optional registry
 # deletion categories remain disabled for a controlled boot test.

 foreach($p in @(
 'Microsoft\Windows\CurrentVersion\SharedDLLs',
 'WOW6432Node\Microsoft\Windows\CurrentVersion\SharedDLLs'
 )){
 $stats.SharedDllValues += Remove-GcSharedDllValues -Root $root -BranchPath $p
 }

 Write-Host ' App Paths/Uninstall + native/WOW MSI metadata enabled; global empty-key compaction disabled.' -ForegroundColor Cyan
 Write-Host ' COM and Classes\Applications remain disabled; targeted Classes shell caches are handled by ultra pass.' -ForegroundColor Cyan

 # SAFETY CHANGE:
 # Never recurse through the entire SOFTWARE hive looking for empty keys.
 # Only compact branches that were explicitly classified as disposable
 # Explorer/cache metadata above. Shell/AppModel/AppX/Classes authority
 # is therefore preserved even when a branch becomes sparse.
 $targetedEmptyRoots = @(
 'Microsoft\Windows\CurrentVersion\Explorer\RecentDocs',
 'Microsoft\Windows\CurrentVersion\Explorer\RunMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\UserAssist',
 'Microsoft\Windows\CurrentVersion\Explorer\ComDlg32',
 'Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery',
 'Microsoft\Windows\CurrentVersion\Explorer\TypedPaths',
 'Microsoft\Windows\CurrentVersion\Explorer\StreamMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\Streams',
 'Microsoft\Windows\CurrentVersion\Explorer\BagMRU',
 'Microsoft\Windows\CurrentVersion\Explorer\Bags',
 'Microsoft\Windows\CurrentVersion\Explorer\MuiCache',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\BagMRU',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\MuiCache',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\RecentDocs',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\ComDlg32',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\TypedPaths',
 'Classes\Local Settings\Software\Microsoft\Windows\Shell\UserAssist'
 )

 # enable ONLY targeted empty-key compaction under explicitly
 # disposable Explorer/cache branches. Do not recurse through all of
 # SOFTWARE or NTUSER.
 foreach($targetPath in $targetedEmptyRoots){
 $target=$null
 try{
 $target=$root.OpenSubKey($targetPath,$true)
 if($null -ne $target){
 for($pass=1;$pass -le 8;$pass++){
 $n=Remove-EmptyRegistrySubKeys -ParentKey $target
 $stats.EmptyKeys += $n
 if($n -eq 0){break}
 }
 }
 }catch{}finally{if($null -ne $target){try{$target.Dispose()}catch{}}}
 }

 Write-Host ''
 Write-Host ' global SOFTWARE/NTUSER empty-key recursion DISABLED.' -ForegroundColor Cyan
 Write-Host ' targeted empty-key compaction ENABLED.' -ForegroundColor Cyan
 Write-Host (' Removed-package/AppX registry records : {0}' -f $stats.RemovedPackageRegistryRecords) -ForegroundColor Green
 Write-Host (' Orphan App Paths : {0}' -f $stats.AppPaths) -ForegroundColor Green
 Write-Host (' Orphan Uninstall records : {0}' -f $stats.Uninstall) -ForegroundColor Green
 Write-Host (' Stale RegisteredApplications values : {0}' -f $stats.RegisteredApplications) -ForegroundColor Green
 Write-Host (' Missing SharedDLL values : {0}' -f $stats.SharedDllValues) -ForegroundColor Green
 Write-Host (' Orphan COM CLSID registrations : {0}' -f $stats.ComClassRegistrations) -ForegroundColor Green
 Write-Host (' Orphan Classes\\Applications records : {0}' -f $stats.ClassesApplicationRecords) -ForegroundColor Green
 Write-Host (' Frozen MSI Classes roots removed : {0}' -f $stats.InstallerClassRoots) -ForegroundColor Yellow
 Write-Host (' Disposable cache roots removed : {0}' -f $stats.DisposableCacheRoots) -ForegroundColor Green
 Write-Host (' Empty SOFTWARE keys removed : {0}' -f $stats.EmptyKeys) -ForegroundColor Green
 Write-Host 'SOFTWARE obsolete-content garbage collection complete.' -ForegroundColor Cyan

 $root.Dispose();$root=$null
 $machine.Dispose();$machine=$null
 [GC]::Collect();[GC]::WaitForPendingFinalizers();[GC]::Collect()
 }
 finally {
 if($null -ne $root){try{$root.Dispose()}catch{}}
 if($null -ne $machine){try{$machine.Dispose()}catch{}}
 [GC]::Collect();[GC]::WaitForPendingFinalizers()
 if($loaded){
 if(-not(Invoke-RegUnloadWithRetry -HiveName $hiveName -Attempts 40 -DelayMilliseconds 250)){
 throw "Could not unload obsolete-content SOFTWARE hive HKLM\$hiveName."
 }
 }
 }
}

} *> $null

Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "SOFTWARE OBSOLETE-CONTENT GARBAGE COLLECTOR" -ForegroundColor Cyan
Write-Host "  [Stage 1] 10.1 Scan SOFTWARE hive for obsolete content" -ForegroundColor Cyan
Write-Host "  [Stage 2] 10.2 Remove targeted obsolete registry content" -ForegroundColor Cyan
Write-Host "  [Stage 3] 10.3 Flush and verify SOFTWARE hive" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Registry cleanup isolation:
# Package/file servicing remains unchanged. Registry mutation is restricted so
# AppModel/AppX, COM, Shell/Explorer caches, and empty-key compaction cannot
# remove structures required during the first ShellHost/OOBE launch.
Write-Host 'REGISTRY POLICY: targeted cleanup enabled; global SOFTWARE empty-key recursion remains disabled.' -ForegroundColor Cyan

# Evidence-based obsolete-content removal comes before the existing ultra pass.
Invoke-SoftwareObsoleteContentGarbageCollector -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'SOFTWARE obsolete-content garbage collection completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "ULTRA-AGGRESSIVE SOFTWARE HIVE REDUCTION" -ForegroundColor Green
Write-Host "  [Stage 1] 11.1 Identify high-volume removable SOFTWARE content" -ForegroundColor Green
Write-Host "  [Stage 2] 11.2 Remove targeted registry data" -ForegroundColor Yellow
Write-Host "  [Stage 3] 11.3 Rebuild/compact SOFTWARE hive" -ForegroundColor Gray
Write-Host "============================================================================" -ForegroundColor Gray
. {
# shell/Oobe safety boundary:
# The entire SOFTWARE hive is no longer subjected to a recursive empty-key
# sweep. Shell, Explorer, AppModel/AppX and Classes structures remain intact
# unless a specific targeted orphan/cache rule above removes an individual
# record with positive evidence.
Write-Host 'REGISTRY SAFETY: only targeted disposable branches/records are removed; global SOFTWARE empty-key recursion remains disabled.' -ForegroundColor Cyan

# Follow with the existing SOFTWARE structural profiler/reducer. The nuclear
# SOFTWARE\Microsoft routine has been removed from this version entirely.
# This second pass can catch disposable structures that are not tied to a
# successfully removed package while still preserving core Microsoft branches.

Invoke-UltraAggressiveSoftwareRegistryReduction -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'ULTRA-AGGRESSIVE SOFTWARE hive reduction completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "OFFLINE zNTUSER / zSOFTWARE REGISTRY CLEANUP" -ForegroundColor Yellow
Write-Host "  [Stage 1] 12.1 Load Default-user and SOFTWARE hives" -ForegroundColor Cyan
Write-Host "  [Stage 2] 12.2 Remove targeted offline registry content" -ForegroundColor Cyan
Write-Host "  [Stage 3] 12.3 Apply user-profile configuration cleanup" -ForegroundColor Green
Write-Host "  [Stage 4] 12.4 Unload and verify hives" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Run registry-content cleanup BEFORE hive rebuild/compaction.
Invoke-OfflineUserAndSoftwareRegistryCleanup -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'Offline zNTUSER / zSOFTWARE registry cleanup completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "OFFLINE REGISTRY ORPHAN / COMPONENT CLEANUP" -ForegroundColor Gray
Write-Host "  [Stage 1] 13.1 Detect orphaned registry/component entries" -ForegroundColor Yellow
Write-Host "  [Stage 2] 13.2 Remove orphaned entries" -ForegroundColor Gray
Write-Host "  [Stage 3] 13.3 Verify registry/component cleanup" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Rebuild/compact System32\config hives after all registry edits.
Invoke-InstallOfflineRegistryHiveRebuild -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host ' Registry orphan cleanup completed' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "OFFLINE DEFAULT NTUSER.DAT REBUILD / COMPACTION" -ForegroundColor Green
Write-Host "  [Stage 1] 14.1 Prepare Default NTUSER.DAT" -ForegroundColor Cyan
Write-Host "  [Stage 2] 14.2 Rebuild/compact Default NTUSER.DAT" -ForegroundColor Green
Write-Host "  [Stage 3] 14.3 Verify resulting hive" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Compact Default user's NTUSER.DAT after zNTUSER cleanup.
Invoke-OfflineDefaultNtUserHiveRebuild -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'Offline Default NTUSER.DAT rebuild / compaction completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "OFFLINE SYSTEM32\CONFIG REGISTRY LOG CLEANUP" -ForegroundColor Cyan
Write-Host "  [Stage 1] 15.1 Identify offline registry transaction/log files" -ForegroundColor Yellow
Write-Host "  [Stage 2] 15.2 Remove stale registry logs" -ForegroundColor Gray
Write-Host "  [Stage 3] 15.3 Verify System32\Config cleanup" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Remove only transactional registry log files after all offline registry
# hives have been unloaded/rebuilt. Core hive files are never deleted.
Remove-OfflineRegistryHiveLogFiles -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'Offline System32\Config registry log cleanup completed...' -ForegroundColor Green


. {
[GC]::Collect()
[GC]::WaitForPendingFinalizers()
# Performance optimization: cosmetic fixed delay removed.

# ============================================================================
# END REGISTRY CLEANUP -> HIVE REBUILD / COMPACTION
# ============================================================================
} *> $null
Write-Host 'REGISTRY CLEANUP -> HIVE REBUILD / COMPACTION Completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "FINAL CBS COMPONENT CLEANUP / RESETBASE" -ForegroundColor Cyan
Write-Host "  [Stage 1] 16.1 Run CBS component cleanup" -ForegroundColor Cyan
Write-Host "  [Stage 2] 16.2 Reset component baseline" -ForegroundColor Green
Write-Host "  [Stage 3] 16.3 Verify servicing cleanup" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Cleaning up image..."
Write-Host "Final servicing cleanup: package removal is complete; running CBS component cleanup before image commit." -ForegroundColor Green
& 'dism' '/English' "/image:$scratchDir" '/Cleanup-Image' '/StartComponentCleanup' '/ResetBase' >$null
$cleanupExitCode = $LASTEXITCODE
if ($cleanupExitCode -ne 0) {
 throw "DISM StartComponentCleanup/ResetBase failed. Exit code: $cleanupExitCode"
}
Write-Host "Cleanup complete."
} *> $null
Write-Host 'Final CBS component cleanup / ResetBase Completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "FINAL COMPONENTS / WINSXS REGISTRY CLEANUP + COMPACTION" -ForegroundColor Yellow
Write-Host "  [Stage 1] 17.1 Clean COMPONENTS registry data" -ForegroundColor Yellow
Write-Host "  [Stage 2] 17.2 Clean WinSxS-related registry data" -ForegroundColor Gray
Write-Host "  [Stage 3] 17.3 Compact final registry hives" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
# ============================================================================
# FINAL COMPONENTS / WINSXS REGISTRY CLEANUP + COMPACTION
# ============================================================================
# Runs AFTER DISM /StartComponentCleanup /ResetBase so the COMPONENTS hive
# reflects the final serviced component store. This cleans only genuinely
# empty registry keys left behind by component/package removal and then uses
# native latest-format hive save to reclaim unused hive-file slack.
# # IMPORTANT:
# * The COMPONENTS hive is PRESERVED.
# * WinSxS itself is PRESERVED.
# * Optional nuclear mode can blindly remove all child identities under the
# COMPONENTS/CBS identity branches after ResetBase.
# * The rebuilt hive is validated and kept only when it is smaller and valid.
# ============================================================================
function Invoke-FinalComponentsWinSxSRegistryCleanup {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $configPath = Join-Path $WindowsRoot 'System32\config'
 $sourceHive = Join-Path $configPath 'COMPONENTS'
 $hiveName = 'zCOMPONENTS_FINAL'
 $validateName = 'zCOMPONENTS_FINAL_VALIDATE'
 $workRoot = Join-Path $env:TEMP ("Micro11-COMPONENTS-Rebuild-" + [guid]::NewGuid().ToString('N'))
 $rebuiltHive = Join-Path $workRoot 'COMPONENTS.rebuilt'
 $backupHive = Join-Path $workRoot 'COMPONENTS.original'

 if (-not (Test-Path -LiteralPath $sourceHive -PathType Leaf)) {
 Write-Warning "COMPONENTS hive not found. Skipping final COMPONENTS/WinSxS registry cleanup: $sourceHive"
 return
 }

 New-Item -ItemType Directory -Path $workRoot -Force -ErrorAction Stop | Out-Null

 $machine = $null
 $rootKey = $null

 try {
 $originalSize = (Get-Item -LiteralPath $sourceHive -Force).Length
 Copy-Item -LiteralPath $sourceHive -Destination $backupHive -Force -ErrorAction Stop

 # Make sure a stale temporary mount cannot interfere.
 & reg.exe unload "HKLM\$hiveName" > $null 2>&1
 & reg.exe unload "HKLM\$validateName" > $null 2>&1

 $loadOutput = & reg.exe load "HKLM\$hiveName" $sourceHive 2>&1
 $loadExitCode = $LASTEXITCODE
 if ($loadExitCode -ne 0) {
 $detail = (($loadOutput | ForEach-Object { $_.ToString().Trim() } | Where-Object { $_ }) -join ' ')
 if ([string]::IsNullOrWhiteSpace($detail)) {
 $detail = 'reg.exe returned no diagnostic text.'
 }
 Write-Warning "Could not load COMPONENTS hive for final cleanup. Exit code: $loadExitCode. $detail"
 Write-Warning 'The existing COMPONENTS hive is being retained; final COMPONENTS compaction is skipped.'
 return
 }

 $removedEmpty = 0

 try {
 $machine = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
 [Microsoft.Win32.RegistryHive]::LocalMachine,
 [Microsoft.Win32.RegistryView]::Default
 )
 $rootKey = $machine.OpenSubKey($hiveName, $true)

 if ($null -eq $rootKey) {
 throw 'Could not open the loaded COMPONENTS hive.'
 }

 # ====================================================================
 # EXPERIMENTAL / NUCLEAR COMPONENTS-CBS IDENTITY REDUCTION
 # ====================================================================
 # Explicitly requested blind deletion mode. This does NOT test whether
 # an identity is orphaned, installed, staged, referenced by CBS, or still
 # present in WinSxS. It removes every child identity under the selected
 # CBS branches after DISM /ResetBase has completed.
 # # WARNING: this can permanently break CBS/DISM/SFC/Windows servicing.
 # It is intended only for a deliberately frozen/debloated image.
 # The branch roots remain so the resulting hive can still be validated
 # and loaded; the identity records beneath them are discarded.
 # ====================================================================
 $script:Micro11BlindComponentsDeletion = $true
 $script:Micro11BlindComponentsRemoved = 0

 function Remove-BlindComponentsChildren {
 param(
 [Parameter(Mandatory = $true)]
 [Microsoft.Win32.RegistryKey]$ParentKey,
 [Parameter(Mandatory = $true)]
 [string]$RelativePath
 )

 foreach ($identityName in @($ParentKey.GetSubKeyNames())) {
 try {
 $ParentKey.DeleteSubKeyTree($identityName, $false)
 $script:Micro11BlindComponentsRemoved++
 Write-Host " BLIND CBS IDENTITY REMOVED: $RelativePath\$identityName" -ForegroundColor Gray
 }
 catch {
 Write-Warning "Unable to blindly remove CBS identity $RelativePath\$identityName : $($_.Exception.Message)"
 }
 }
 }

 if ($script:Micro11BlindComponentsDeletion) {
 Write-Host ''
 Write-Host '!!! BLIND COMPONENTS/CBS IDENTITY DELETION ENABLED !!!' -ForegroundColor Red
 Write-Host 'All child identities in Components, Packages, DerivedData and CanonicalData will be deleted.' -ForegroundColor Red

 foreach ($blindBranch in @('Components','Packages','DerivedData','CanonicalData')) {
 $blindKey = $null
 try {
 $blindKey = $rootKey.OpenSubKey($blindBranch, $true)
 if ($null -eq $blindKey) {
 Write-Host " CBS branch not present: $blindBranch" -ForegroundColor Green
 continue
 }
 Remove-BlindComponentsChildren -ParentKey $blindKey -RelativePath $blindBranch
 }
 catch {
 Write-Warning "Blind COMPONENTS cleanup failed for branch '$blindBranch': $($_.Exception.Message)"
 }
 finally {
 if ($null -ne $blindKey) {
 try { $blindKey.Dispose() } catch {}
 }
 }
 }

 Write-Host (' BLIND CBS identities removed: {0}' -f $script:Micro11BlindComponentsRemoved) -ForegroundColor Red
 }

 function Remove-FinalComponentsEmptyKeys {
 param(
 [Parameter(Mandatory = $true)]
 [Microsoft.Win32.RegistryKey]$Parent
 )

 foreach ($childName in @($Parent.GetSubKeyNames())) {
 $child = $null
 try {
 $child = $Parent.OpenSubKey($childName, $true)
 if ($null -eq $child) { continue }

 Remove-FinalComponentsEmptyKeys -Parent $child
 $child.Dispose()
 $child = $null

 $check = $null
 try {
 $check = $Parent.OpenSubKey($childName, $false)
 if ($null -ne $check -and $check.SubKeyCount -eq 0 -and $check.ValueCount -eq 0) {
 [void]$Parent.DeleteSubKey($childName, $false)
 $script:FinalComponentsRemovedEmpty++
 }
 }
 finally {
 if ($null -ne $check) { $check.Dispose() }
 }
 }
 catch {
 # Leave uncertain servicing data untouched.
 }
 finally {
 if ($null -ne $child) { $child.Dispose() }
 }
 }
 }

 $script:FinalComponentsRemovedEmpty = 0

 # These are the areas most likely to retain empty branches after
 # DISM component/package removal. The hive root itself is never
 # deleted and non-empty servicing data is never recursively purged.
 foreach ($relativeRoot in @('DerivedData','CanonicalData')) {
 $target = $rootKey.OpenSubKey($relativeRoot, $true)
 if ($null -ne $target) {
 try {
 Remove-FinalComponentsEmptyKeys -Parent $target
 }
 finally {
 $target.Dispose()
 }
 }
 }

 $removedEmpty = [int]$script:FinalComponentsRemovedEmpty
 $script:FinalComponentsRemovedEmpty = $null
 }
 finally {
 if ($null -ne $rootKey) { $rootKey.Dispose(); $rootKey = $null }
 if ($null -ne $machine) { $machine.Dispose(); $machine = $null }
 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 [GC]::Collect()
 }

 # Save a fresh hive file to reclaim unused hive-file slack.
 Remove-Item -LiteralPath $rebuiltHive -Force -ErrorAction SilentlyContinue
 $saveExitCode = Invoke-NativeRegistryHiveSaveLatest -HiveName $hiveName -DestinationPath $rebuiltHive

 if (-not (Invoke-RegUnloadWithRetry -HiveName $hiveName -Attempts 40 -DelayMilliseconds 250)) {
 throw 'Could not unload final COMPONENTS cleanup hive.'
 }

 if ($saveExitCode -ne 0 -or -not (Test-Path -LiteralPath $rebuiltHive -PathType Leaf)) {
 throw 'Native/latest-format save failed for the final COMPONENTS hive. Original retained.'
 }

 $rebuiltSize = (Get-Item -LiteralPath $rebuiltHive -Force).Length
 if ($rebuiltSize -le 0) {
 throw 'The rebuilt COMPONENTS hive is empty. Original retained.'
 }

 # Validate the rebuilt hive before replacement.
 & reg.exe load "HKLM\$validateName" $rebuiltHive > $null 2>&1
 $validationOK = ($LASTEXITCODE -eq 0)

 if ($validationOK) {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $validateName -Attempts 40 -DelayMilliseconds 250)) {
 throw 'Could not unload validation COMPONENTS hive. Original retained.'
 }
 }

 if (-not $validationOK) {
 throw 'Validation failed for rebuilt COMPONENTS hive. Original retained.'
 }

 if ($rebuiltSize -lt $originalSize) {
 Copy-Item -LiteralPath $rebuiltHive -Destination $sourceHive -Force -ErrorAction Stop

 # Only remove COMPONENTS transaction logs after a validated smaller
 # hive has been installed.
 foreach ($logPath in @(
 (Join-Path $configPath 'COMPONENTS.LOG'),
 (Join-Path $configPath 'COMPONENTS.LOG1'),
 (Join-Path $configPath 'COMPONENTS.LOG2'),
 (Join-Path $configPath 'COMPONENTS.SAV')
 )) {
 if (Test-Path -LiteralPath $logPath -PathType Leaf) {
 Remove-Item -LiteralPath $logPath -Force -ErrorAction SilentlyContinue
 }
 }

 $finalSize = (Get-Item -LiteralPath $sourceHive -Force).Length
 Write-Host (
 'FINAL COMPONENTS/WINSXS REGISTRY CLEANUP: {0:N2} MB -> {1:N2} MB | saved {2:N2} MB ({3:N1}%) | empty keys removed: {4}' -f
 ($originalSize / 1MB),
 ($finalSize / 1MB),
 (($originalSize - $finalSize) / 1MB),
 ((($originalSize - $finalSize) / $originalSize) * 100),
 $removedEmpty
 ) -ForegroundColor Green
 }
 else {
 Write-Host (
 'FINAL COMPONENTS/WINSXS REGISTRY CLEANUP: no smaller validated hive produced ({0:N2} MB -> {1:N2} MB); original retained. Empty keys removed: {2}' -f
 ($originalSize / 1MB),
 ($rebuiltSize / 1MB),
 $removedEmpty
 ) -ForegroundColor Yellow
 }
 }
 finally {
 # Best-effort cleanup of any temporary mount left by an exception.
 if ($null -ne $rootKey) { try { $rootKey.Dispose() } catch {} }
 if ($null -ne $machine) { try { $machine.Dispose() } catch {} }
 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()

 [void](Invoke-RegUnloadWithRetry -HiveName $hiveName -Attempts 10 -DelayMilliseconds 250)
 [void](Invoke-RegUnloadWithRetry -HiveName $validateName -Attempts 10 -DelayMilliseconds 250)

 if (Test-Path -LiteralPath $workRoot) {
 Remove-Item -LiteralPath $workRoot -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
}

Write-Host 'Final registry compaction includes BLIND COMPONENTS/CBS identity deletion.' -ForegroundColor Red
Invoke-FinalComponentsWinSxSRegistryCleanup -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'Final COMPONENTS / WinSxS registry cleanup + compaction Completed...' -ForegroundColor Green



. {
# ============================================================================
# FINAL POST-DISM PHYSICAL HIVE COMPACTION
# ============================================================================
# DISM servicing can write registry state after the earlier compaction pass.
# Re-save SOFTWARE, SYSTEM and DRIVERS one last time after ResetBase. COMPONENTS
# is handled immediately above by Invoke-FinalComponentsWinSxSRegistryCleanup.
# This pass performs NO key/value deletion; it only rebuilds the physical files.
# ============================================================================
function Invoke-FinalOfflineHivePhysicalCompaction {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot,

 [string[]]$HiveNames = @('SOFTWARE','SYSTEM','DRIVERS')
 )

 $configPath = Join-Path $WindowsRoot 'System32\config'
 $workRoot = Join-Path $env:TEMP ("Micro11-FinalHiveCompact-" + [guid]::NewGuid().ToString('N'))
 New-Item -ItemType Directory -Path $workRoot -Force -ErrorAction Stop | Out-Null

 try {
 foreach ($hive in $HiveNames) {
 $sourceHive = Join-Path $configPath $hive
 if (-not (Test-Path -LiteralPath $sourceHive -PathType Leaf)) {
 Write-Warning "Final compaction skipped; hive not found: $sourceHive"
 continue
 }

 $mountName = "zFINAL_$hive"
 $validateName = "zFINAL_VALIDATE_$hive"
 $rebuiltHive = Join-Path $workRoot "$hive.rebuilt"
 $backupHive = Join-Path $workRoot "$hive.original"
 $originalSize = (Get-Item -LiteralPath $sourceHive -Force).Length

 Copy-Item -LiteralPath $sourceHive -Destination $backupHive -Force -ErrorAction Stop
 Remove-Item -LiteralPath $rebuiltHive -Force -ErrorAction SilentlyContinue

 [void](Invoke-RegUnloadWithRetry -HiveName $mountName -Attempts 5 -DelayMilliseconds 100)
 [void](Invoke-RegUnloadWithRetry -HiveName $validateName -Attempts 5 -DelayMilliseconds 100)

 & reg.exe load "HKLM\$mountName" $sourceHive > $null 2>&1
 if ($LASTEXITCODE -ne 0) {
 Write-Warning "Final compaction could not load $hive. Original retained."
 continue
 }

 $saveExitCode = 1
 try {
 $saveExitCode = Invoke-NativeRegistryHiveSaveLatest -HiveName $mountName -DestinationPath $rebuiltHive
 }
 finally {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $mountName -Attempts 40 -DelayMilliseconds 250)) {
 throw "Could not unload final-compaction hive HKLM\$mountName. Original $hive retained."
 }
 }

 if ($saveExitCode -ne 0 -or -not (Test-Path -LiteralPath $rebuiltHive -PathType Leaf)) {
 Write-Warning "Final native hive save failed for $hive. Original retained."
 continue
 }

 $rebuiltSize = (Get-Item -LiteralPath $rebuiltHive -Force).Length
 if ($rebuiltSize -le 0) {
 Write-Warning "Final rebuilt $hive is empty. Original retained."
 continue
 }

 & reg.exe load "HKLM\$validateName" $rebuiltHive > $null 2>&1
 $validationOK = ($LASTEXITCODE -eq 0)
 if ($validationOK) {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $validateName -Attempts 40 -DelayMilliseconds 250)) {
 throw "Could not unload final validation hive HKLM\$validateName. Original $hive retained."
 }
 }

 if (-not $validationOK) {
 Write-Warning "Final rebuilt $hive failed validation. Original retained."
 continue
 }

 if ($rebuiltSize -lt $originalSize) {
 Copy-Item -LiteralPath $rebuiltHive -Destination $sourceHive -Force -ErrorAction Stop
 $finalSize = (Get-Item -LiteralPath $sourceHive -Force).Length
 Write-Host (
 'FINAL HIVE COMPACTION {0}: {1:N2} MB -> {2:N2} MB | saved {3:N2} MB ({4:N1}%)' -f
 $hive,
 ($originalSize / 1MB),
 ($finalSize / 1MB),
 (($originalSize - $finalSize) / 1MB),
 ((($originalSize - $finalSize) / $originalSize) * 100)
 ) -ForegroundColor Green
 }
 else {
 Write-Host (
 'FINAL HIVE COMPACTION {0}: no smaller validated hive produced ({1:N2} MB -> {2:N2} MB); original retained.' -f
 $hive,
 ($originalSize / 1MB),
 ($rebuiltSize / 1MB)
 ) -ForegroundColor Yellow
 }
 }
 }
 finally {
 foreach ($hive in $HiveNames) {
 [void](Invoke-RegUnloadWithRetry -HiveName "zFINAL_$hive" -Attempts 5 -DelayMilliseconds 100)
 [void](Invoke-RegUnloadWithRetry -HiveName "zFINAL_VALIDATE_$hive" -Attempts 5 -DelayMilliseconds 100)
 }
 if (Test-Path -LiteralPath $workRoot) {
 Remove-Item -LiteralPath $workRoot -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
}
} *> $null


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "DEFAULT PROFILE NTUSER TRANSACTION FILE CLEANUP" -ForegroundColor Cyan
Write-Host "  [Stage 1] 18.1 Identify Default-profile transaction files" -ForegroundColor Cyan
Write-Host "  [Stage 2] 18.2 Remove stale transaction files" -ForegroundColor Green
Write-Host "  [Stage 3] 18.3 Verify Default-profile cleanup" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
# TARGETED DEFAULT PROFILE NTUSER TRANSACTION FILE CLEANUP
# Delete only the explicitly identified stale Default-profile registry transaction files.
# Do not delete NTUSER.DAT itself.
$defaultProfilePath = Join-Path $scratchDir 'Users\Default'
$defaultNtUserTransactionFiles = @(
 'ntuser.dat.LOG1',
 'ntuser.dat.LOG2',
 'NTUSER.DAT{2ad838bc-efea-11ee-a54d-000d3a94eaa1}.TM.blf',
 'NTUSER.DAT{2ad838bc-efea-11ee-a54d-000d3a94eaa1}.TMContainer00000000000000000001.regtrans-ms',
 'NTUSER.DAT{2ad838bc-efea-11ee-a54d-000d3a94eaa1}.TMContainer00000000000000000002.regtrans-ms',
 'NTUSER.DAT{ec8c8c88-ade9-11f1-8a63-bfe92d423b6e}.TM.blf',
 'NTUSER.DAT{ec8c8c88-ade9-11f1-8a63-bfe92d423b6e}.TMContainer00000000000000000001.regtrans-ms',
 'NTUSER.DAT{ec8c8c88-ade9-11f1-8a63-bfe92d423b6e}.TMContainer00000000000000000002.regtrans-ms'
)

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host 'DEFAULT PROFILE NTUSER TRANSACTION FILE CLEANUP' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan

foreach ($transactionFile in $defaultNtUserTransactionFiles) {
 $transactionPath = Join-Path $defaultProfilePath $transactionFile
 if (Test-Path -LiteralPath $transactionPath -PathType Leaf) {
 try {
 Remove-Item -LiteralPath $transactionPath -Force -ErrorAction Stop
 Write-Host "Deleted Default NTUSER transaction file: $transactionFile" -ForegroundColor Cyan
 }
 catch {
 Write-Host "Could not delete Default NTUSER transaction file: $transactionFile | $($_.Exception.Message)" -ForegroundColor Green
 }
 }
}

Write-Host 'Default-profile NTUSER transaction-file cleanup complete.' -ForegroundColor Green
} *> $null
Write-Host 'Default-profile NTUSER transaction-file cleanup completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "FINAL POST-DISM PHYSICAL HIVE COMPACTION" -ForegroundColor Yellow
Write-Host "  [Stage 1] 19.1 Prepare final physical hive compaction" -ForegroundColor Yellow
Write-Host "  [Stage 2] 19.2 Compact remaining offline registry hives" -ForegroundColor Gray
Write-Host "  [Stage 3] 19.3 Verify physical hive sizes" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
Invoke-FinalOfflineHivePhysicalCompaction -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'Final post-DISM physical hive compaction Completed...' -ForegroundColor Green


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "FINAL OFFLINE REGISTRY LOG CLEANUP" -ForegroundColor Gray
Write-Host "  [Stage 1] 20.1 Scan final offline registry logs" -ForegroundColor Cyan
Write-Host "  [Stage 2] 20.2 Remove remaining stale logs" -ForegroundColor Green
Write-Host "  [Stage 3] 20.3 Verify final registry-log cleanup" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
Remove-OfflineRegistryHiveLogFiles -WindowsRoot (Join-Path $scratchDir 'Windows')
} *> $null
Write-Host 'Final offline registry log cleanup Completed...' -ForegroundColor Green



Write-Host "INSTALL.WIM - COMMIT, EXPORT AND FINAL REBUILD" -ForegroundColor Green
Write-Host "  [Stage 1] 21.1 Commit changes to mounted INSTALL.WIM" -ForegroundColor Yellow
Write-Host "  [Stage 2] 21.2 Unmount INSTALL.WIM" -ForegroundColor Gray
Write-Host "  [Stage 3] 21.3 Export/rebuild final INSTALL.WIM" -ForegroundColor Cyan
Write-Host "  [Stage 4] 21.4 Verify final INSTALL.WIM" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host ' ' 
Write-Host "Unmounting image..."

& 'dism' '/English' '/unmount-image' "/mountdir:$scratchDir" '/commit'
$unmountExitCode = $LASTEXITCODE
if ($unmountExitCode -ne 0) {
 throw "DISM failed to commit/unmount the install.wim image. Exit code: $unmountExitCode"
}

# The WIM must be fully released before it is replaced. Export first and
# replace the original only after a successful, non-empty export exists.
$installWim = Join-Path $mainOSDrive 'Micro 11 Barebones\sources\install.wim'
$installWimRebuilt = Join-Path $mainOSDrive 'Micro 11 Barebones\sources\install2.wim'

Write-Host "Exporting image..."
if (Test-Path -LiteralPath $installWimRebuilt) {
 Remove-Item -LiteralPath $installWimRebuilt -Force -ErrorAction Stop
}

& 'dism' '/English' '/Export-Image' "/SourceImageFile:$installWim" "/SourceIndex:$index" "/DestinationImageFile:$installWimRebuilt" '/compress:max' '/CheckIntegrity'
$exportExitCode = $LASTEXITCODE

if ($exportExitCode -ne 0 -or -not (Test-Path -LiteralPath $installWimRebuilt -PathType Leaf)) {
 throw "DISM failed to export the rebuilt install.wim. Exit code: $exportExitCode. The original install.wim has been retained."
}

$rebuiltInstallSize = (Get-Item -LiteralPath $installWimRebuilt -Force).Length
if ($rebuiltInstallSize -le 0) {
 throw "The rebuilt install.wim is empty. The original install.wim has been retained."
}

if (-not (Wait-ForFileUnlock -Path $installWim -Attempts 40 -DelayMilliseconds 500)) {
 throw "The original install.wim is still locked after the committed unmount. The rebuilt install2.wim has been retained and the original was not deleted."
}

Remove-Item -LiteralPath $installWim -Force -ErrorAction Stop
Rename-Item -LiteralPath $installWimRebuilt -NewName 'install.wim' -ErrorAction Stop

if (-not (Test-Path -LiteralPath $installWim -PathType Leaf)) {
 throw "install.wim replacement failed. The expected final install.wim was not found."
}

Write-Host "Final install.wim replacement complete; continuing with boot.wim."
} *> $null
Write-Host 'INSTALL.WIM commit, export and final rebuild Completed...' -ForegroundColor Green

# Performance optimization: cosmetic fixed delay removed.
# Clear-Host suppressed so section headers remain visible.

Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "BOOT.WIM - MOUNT AND PREPARATION" -ForegroundColor Cyan
Write-Host "  [Stage 1] 22.1 Mount BOOT.WIM" -ForegroundColor Green
Write-Host "  [Stage 2] 22.2 Prepare BOOT.WIM servicing environment" -ForegroundColor Green
Write-Host "  [Stage 3] 22.3 Verify BOOT.WIM mount" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Mounting boot image:"
$wimFilePath = "$($env:SystemDrive)\Micro 11 Barebones\sources\boot.wim"
& takeown "/F" $wimFilePath >$null 2>&1
if ($LASTEXITCODE -ne 0) {
    throw "Could not take ownership of boot.wim. takeown.exe exit code: $LASTEXITCODE"
}
& icacls $wimFilePath "/grant" "$($adminGroup.Value):(F)" >$null 2>&1
if ($LASTEXITCODE -ne 0) {
    throw "Could not grant Administrators full control on boot.wim. icacls.exe exit code: $LASTEXITCODE"
}
Set-ItemProperty -Path $wimFilePath -Name IsReadOnly -Value $false
& 'dism.exe' '/English' '/Delete-Image' "/ImageFile:$($env:SystemDrive)\Micro 11 Barebones\sources\boot.wim" '/Index:1' >$null 2>&1
if ($LASTEXITCODE -ne 0) {
    throw "DISM failed to delete Boot.wim index 1. Exit code: $LASTEXITCODE"
}
Write-Host "Getting image information:"
& 'dism' '/English' "/Get-WimInfo" "/wimfile:$mainOSDrive\Micro 11 Barebones\sources\boot.wim"
if ($LASTEXITCODE -ne 0) {
    throw "DISM failed to read boot.wim information. Exit code: $LASTEXITCODE"
}
& 'dism.exe' '/English' '/mount-image' "/imagefile:$mainOSDrive\Micro 11 Barebones\sources\boot.wim" '/index:1' "/mountdir:$mainOSDrive\scratchdir"
if ($LASTEXITCODE -ne 0) {
    throw "DISM failed to mount boot.wim. Exit code: $LASTEXITCODE"
}


Write-Host "Taking ownership of the Program Files folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchDir\Program Files" '/A' '/R' '/D' 'Y' >$null 2>&1
& 'icacls' "$mainOSDrive\scratchDir\Program Files" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q' >$null 2>&1

$bootProgramFilesX86Path = "$mainOSDrive\scratchdir\Program Files (x86)"
if (Test-Path -LiteralPath $bootProgramFilesX86Path -PathType Container) {
    Write-Host "Taking ownership of the Program Files (x86) folder. This might take a while..."
    & 'takeown' '/f' $bootProgramFilesX86Path '/A' '/R' '/D' 'Y' >$null 2>&1
    & 'icacls' $bootProgramFilesX86Path '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q' >$null 2>&1
}

Write-Host "Taking ownership of the ProgramData folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchDir\ProgramData" '/A' '/R' '/D' 'Y' >$null 2>&1
& 'icacls' "$mainOSDrive\scratchDir\ProgramData" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q' >$null 2>&1

Write-Host "Taking ownership of the Sources folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchDir\sources" '/A' '/R' '/D' 'Y' >$null 2>&1
& 'icacls' "$mainOSDrive\scratchDir\sources" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q' >$null 2>&1

