& 'takeown' '/f' "$mainOSDrive\scratchdir\Windows" '/A' '/R' '/D' 'Y' >$null 2>&1
& 'icacls' "$mainOSDrive\scratchdir\Windows" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q' >$null 2>&1

Write-Host "Mounting complete! Performing Boot Wim Agressive Manual Deletions..."
} *> $null
Write-Host 'BOOT.WIM mount and preparation Completed...' -ForegroundColor Green


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "BOOT.WIM - AGGRESSIVE MANUAL FILE CLEANUP" -ForegroundColor Cyan
Write-Host "  [Stage 1] 23.1 Identify removable BOOT.WIM files" -ForegroundColor Gray
Write-Host "  [Stage 2] 23.2 Remove targeted files" -ForegroundColor Cyan
Write-Host "  [Stage 3] 23.3 Verify BOOT.WIM file cleanup" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
Remove-Item -Path @(
    "$scratchDir\Program Files",
    "$scratchDir\Program Files (x86)",
    "$scratchDir\ProgramData"
) -Recurse -Force -ErrorAction SilentlyContinue
# preserve the Boot.wim Default profile so NTUSER.DAT remains available
# for the later zNTUSER registry load/tweaks. The previous line removed
# the entire Users tree here, which deleted Users\Default\NTUSER.DAT before the
# registry-loading section was reached.
$bootUsersRoot = Join-Path $scratchDir 'Users'
$bootDefaultProfile = Join-Path $bootUsersRoot 'Default'
$bootDefaultNtUser = Join-Path $bootDefaultProfile 'NTUSER.DAT'
if (Test-Path -LiteralPath $bootUsersRoot -PathType Container) {
 foreach ($bootUserChild in @(Get-ChildItem -LiteralPath $bootUsersRoot -Force -ErrorAction SilentlyContinue)) {
 if ($bootUserChild.Name -ieq 'Default') { continue }
 Remove-Item -LiteralPath $bootUserChild.FullName -Recurse -Force -ErrorAction SilentlyContinue
 }
}
if (Test-Path -LiteralPath $bootDefaultNtUser -PathType Leaf) {
 $NtUserItem = Get-Item -LiteralPath $bootDefaultNtUser -Force -ErrorAction SilentlyContinue
 if ($null -ne $NtUserItem) {
 }
}
else {
 Write-Warning "Boot.wim Default NTUSER.DAT is already absent immediately after Users cleanup: $bootDefaultNtUser"
}
