Write-Host "BOOT.WIM - WINSXS CLEANUP" -ForegroundColor Green
Write-Host "  [Stage 1] 24.1 Analyze BOOT.WIM WinSxS" -ForegroundColor Green
Write-Host "  [Stage 2] 24.2 Remove targeted component payloads" -ForegroundColor Green
Write-Host "  [Stage 3] 24.3 Verify WinSxS cleanup" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Taking ownership of the WinSxS folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchdir\Windows\WinSxS" '/A' '/R' '/D' 'Y' >$null 2>&1
& 'icacls' "$mainOSDrive\scratchdir\Windows\WinSxS" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q' >$null 2>&1
Write-Host "Complete!"
Write-Host "Preparing Boot WinSxS...." >$null
$folderPath = Join-Path -Path $mainOSDrive -ChildPath "\scratchdir\Windows\WinSxS_edit"
$sourceDirectory = "$mainOSDrive\scratchdir\Windows\WinSxS"
$destinationDirectory = "$mainOSDrive\scratchdir\Windows\WinSxS_edit"

New-Item -Path $folderPath -ItemType Directory -Force | Out-Null

if ($architecture -eq "amd64") {
 $dirsToCopy = @(
 "amd64_microsoft.windows.common-controls_6595b64144ccf1df_*",
 "amd64_microsoft.windows.gdiplus_6595b64144ccf1df_*"
 )

 # Copy each directory
 foreach ($dir in $dirsToCopy) {
 $sourceDirs = Get-ChildItem -Path $sourceDirectory -Filter $dir -Directory
 foreach ($sourceDir in $sourceDirs) {
 $destDir = Join-Path -Path $destinationDirectory -ChildPath $sourceDir.Name
  # Per-directory WinSxS copy output suppressed for a quieter/faster console.
 Copy-Item -Path $sourceDir.FullName -Destination $destDir -Recurse -Force
 }
 }

 # Copy only required manifests
 $manifestPath = Join-Path $sourceDirectory "Manifests"
 $destPath = Join-Path $destinationDirectory "Manifests"
 New-Item -ItemType Directory -Path $destPath -Force | Out-Null
 
 $keep = @(
 "amd64_microsoft.windows.i..utomation.proxystub_*","amd64_microsoft.windows.isolationautomation_*","amd64_microsoft-windows-international-core_*","amd64_microsoft.windows.common-controls_*","amd64_microsoft.windows.c..-controls.resources_*_en-us_*","amd64_microsoft.windows.gdiplus_*","amd64_microsoft.windows.systemcompatible_*","amd64_microsoft-windows-servicingstack_*","x86_microsoft-windows-servicingstack_*"
 )
 
 foreach ($pattern in $keep) {
 Get-ChildItem $manifestPath -Filter $pattern -File -ErrorAction SilentlyContinue | Copy-Item -Destination $destPath -Force
 }
}
elseif ($architecture -eq "arm64") {
 $dirsToCopy = @(
 "arm64_microsoft.windows.common-controls_6595b64144ccf1df_*",
 "arm64_microsoft.windows.gdiplus_6595b64144ccf1df_*"
 )

 foreach ($dir in $dirsToCopy) {
 $sourceDirs = Get-ChildItem -Path $sourceDirectory -Filter $dir -Directory -ErrorAction SilentlyContinue
 foreach ($sourceDir in $sourceDirs) {
 $destDir = Join-Path -Path $destinationDirectory -ChildPath $sourceDir.Name
  # Per-directory WinSxS copy output suppressed for a quieter/faster console.
 Copy-Item -Path $sourceDir.FullName -Destination $destDir -Recurse -Force
 }
 }

 $manifestPath = Join-Path $sourceDirectory "Manifests"
 $destPath = Join-Path $destinationDirectory "Manifests"
 New-Item -ItemType Directory -Path $destPath -Force | Out-Null

 $keep = @(
 "arm64_microsoft.windows.i..utomation.proxystub_*",
 "arm64_microsoft.windows.isolationautomation_*",
 "arm64_microsoft-windows-international-core_*",
 "arm64_microsoft.windows.common-controls_*",
 "arm64_microsoft.windows.c..-controls.resources_*_en-us_*",
 "arm64_microsoft.windows.gdiplus_*",
 "arm64_microsoft.windows.systemcompatible_*",
 "arm64_microsoft-windows-servicingstack_*",
 "x86_microsoft-windows-servicingstack_*"
 )

 foreach ($pattern in $keep) {
 Get-ChildItem $manifestPath -Filter $pattern -File -ErrorAction SilentlyContinue |
 Copy-Item -Destination $destPath -Force
 }
}

Write-Host "Deleting WinSxS. This may take a while..."
 Remove-Item -Path $mainOSDrive\scratchdir\Windows\WinSxS -Recurse -Force

Rename-Item -Path "$mainOSDrive\scratchdir\Windows\WinSxS_edit" -NewName "WinSxS" -ErrorAction Stop
Write-Host "Complete!"
} *> $null
Write-Host 'BOOT.WIM WinSxS cleanup Completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "BOOT.WIM - REGISTRY HIVE TWEAKS" -ForegroundColor Yellow
Write-Host "  [Stage 1] 25.1 Load BOOT.WIM registry hives" -ForegroundColor Gray
Write-Host "  [Stage 2] 25.2 Apply offline registry tweaks" -ForegroundColor Cyan
Write-Host "  [Stage 3] 25.3 Apply setup/boot configuration changes" -ForegroundColor Cyan
Write-Host "  [Stage 4] 25.4 Unload BOOT.WIM registry hives" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Boot.wim registry loading is intentionally silent, but every load is validated.
$bootHiveLoads = @(
    @{ Name = 'zCOMPONENTS'; Path = "$mainOSDrive\scratchdir\Windows\System32\config\COMPONENTS" },
    @{ Name = 'zDEFAULT';    Path = "$mainOSDrive\scratchdir\Windows\System32\config\default" },
    @{ Name = 'zSOFTWARE';   Path = "$mainOSDrive\scratchdir\Windows\System32\config\SOFTWARE" },
    @{ Name = 'zSYSTEM';     Path = "$mainOSDrive\scratchdir\Windows\System32\config\SYSTEM" }
)

$bootHivesLoaded = @()
try {
    foreach ($bootHive in $bootHiveLoads) {
        & reg.exe load "HKLM\$($bootHive.Name)" $bootHive.Path >$null 2>&1
        if ($LASTEXITCODE -ne 0) {
            throw "Could not load BOOT.WIM registry hive HKLM\$($bootHive.Name). reg.exe exit code: $LASTEXITCODE"
        }
        $bootHivesLoaded += $bootHive.Name
    }
Write-Host "Bypassing system requirements on the Boot wim image"
& reg.exe add 'HKLM\zDEFAULT\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV1' '/t' 'REG_DWORD' '/d' '0' '/f' >$null
& reg.exe add 'HKLM\zDEFAULT\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV2' '/t' 'REG_DWORD' '/d' '0' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassCPUCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassRAMCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassSecureBootCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassStorageCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassTPMCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup\MoSetup' '/v' 'AllowUpgradesWithUnsupportedTPMOrCPU' '/t' 'REG_DWORD' '/d' '1' '/f' >$null
& reg.exe add 'HKLM\zSYSTEM\Setup' '/v' 'CmdLine' '/t' 'REG_SZ' '/d' 'X:\sources\setup.exe' '/f' >$null
# Boot.wim registry tweaks completed silently.
}
finally {
    # Always release every hive that was successfully loaded, using the same
    # retry helper used elsewhere in the offline-image servicing framework.
    [array]::Reverse($bootHivesLoaded)
    foreach ($bootHiveName in $bootHivesLoaded) {
        if (-not (Invoke-RegUnloadWithRetry -HiveName $bootHiveName -Attempts 30 -DelayMilliseconds 500)) {
            throw "Could not unload BOOT.WIM registry hive HKLM\$bootHiveName after all retry attempts."
        }
    }
}

# Once every BOOT.WIM registry hive has been fully unloaded, discard only the
# Default-profile registry transaction sidecars. Keep NTUSER.DAT itself.
$bootDefaultProfileForLogCleanup = Join-Path $mainOSDrive 'scratchdir\Users\Default'
if (Test-Path -LiteralPath $bootDefaultProfileForLogCleanup -PathType Container) {
    $bootNtUserSidecarPatterns = @(
        'ntuser.dat.LOG1',
        'ntuser.dat.LOG2',
        'NTUSER.DAT{*}.TM.blf',
        'NTUSER.DAT{*}.TMContainer*.regtrans-ms'
    )

    $bootDefaultFiles = @(Get-ChildItem -LiteralPath $bootDefaultProfileForLogCleanup -Force -File -ErrorAction SilentlyContinue)
    foreach ($bootNtUserSidecarPattern in $bootNtUserSidecarPatterns) {
        foreach ($bootNtUserSidecarFile in @($bootDefaultFiles | Where-Object { $_.Name -like $bootNtUserSidecarPattern })) {
            try {
                Remove-Item -LiteralPath $bootNtUserSidecarFile.FullName -Force -ErrorAction Stop
            }
            catch {
                # Keep this cleanup non-fatal. The core NTUSER.DAT hive is never removed.
            }
        }
    }
}
} *> $null
Write-Host 'BOOT.WIM registry hive tweaks Completed...' -ForegroundColor Green

. {
# ============================================================================
# BOOT.WIM REGISTRY CLEANUP + NATIVE HIVE COMPACTION
# ============================================================================
# Conservative Boot.wim-specific strategy:
# 1. Finish the existing Boot.wim registry tweaks.
# 2. Ensure all Boot.wim registry hives are cleanly unloaded.
# 3. Remove registry transaction sidecars only after clean unloads.
# 4. Rebuild selected Boot.wim hives with native RegSaveKeyEx(REG_LATEST_FORMAT).
# 5. Validate every rebuilt hive by loading it again.
# 6. Replace an original hive only when the rebuilt hive is valid and smaller.
# # IMPORTANT:
# * No SOFTWARE\Microsoft wholesale deletion.
# * No global SOFTWARE empty-key sweep.
# * No blind COMPONENTS/CBS identity deletion in Boot.wim.
# * Existing Boot.wim setup/compatibility tweaks remain unchanged.
# ============================================================================
function Invoke-BootWimRegistryCleanupAndCompaction {
 param(
 [Parameter(Mandatory = $true)]
 [string]$WindowsRoot
 )

 $configPath = Join-Path $WindowsRoot 'System32\config'
 if (-not (Test-Path -LiteralPath $configPath -PathType Container)) {
 throw "Boot.wim registry config directory was not found: $configPath"
 }

 # Boot.wim is deliberately handled more conservatively than install.wim.
 # These are rebuilt only to reclaim unused hive-file slack; no broad content
 # deletion is performed here.
 $hives = @('COMPONENTS','DEFAULT','SOFTWARE','SYSTEM')
 $workRoot = Join-Path $env:TEMP ("Micro11-BootHive-" + [guid]::NewGuid().ToString('N'))
 New-Item -ItemType Directory -Path $workRoot -Force -ErrorAction Stop | Out-Null

 try {
 Write-Host ''
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host 'BOOT.WIM REGISTRY CLEANUP + HIVE COMPACTION' -ForegroundColor Cyan
 Write-Host '============================================================' -ForegroundColor Cyan
 Write-Host 'Boot.wim policy: targeted transaction cleanup + validated native hive rebuild.' -ForegroundColor Cyan
 Write-Host 'Boot.wim policy: no wholesale SOFTWARE deletion, no global empty-key sweep, no blind CBS deletion.' -ForegroundColor Cyan

 foreach ($hive in $hives) {
 $sourceHive = Join-Path $configPath $hive
 if (-not (Test-Path -LiteralPath $sourceHive -PathType Leaf)) {
 Write-Warning "Boot.wim hive not found; skipping: $sourceHive"
 continue
 }

 $mountName = "zBOOT_$hive"
 $validateName = "zBOOT_VALIDATE_$hive"
 $rebuiltHive = Join-Path $workRoot "$hive.rebuilt"
 $originalSize = (Get-Item -LiteralPath $sourceHive -Force).Length

 [void](Invoke-RegUnloadWithRetry -HiveName $mountName -Attempts 5 -DelayMilliseconds 100)
 [void](Invoke-RegUnloadWithRetry -HiveName $validateName -Attempts 5 -DelayMilliseconds 100)
 Remove-Item -LiteralPath $rebuiltHive -Force -ErrorAction SilentlyContinue

 Write-Host "Rebuilding Boot.wim hive: $hive" -ForegroundColor Gray
 & reg.exe load "HKLM\$mountName" $sourceHive >$null 2>&1
 $loadExitCode = $LASTEXITCODE
 if ($loadExitCode -ne 0) {
 Write-Warning "Could not load Boot.wim hive $hive (reg.exe exit code $loadExitCode). Original retained."
 continue
 }

 try {
 # Conservative registry cleanup: remove only genuinely empty keys
 # directly beneath known disposable transaction/cache roots. The
 # Boot.wim hive is otherwise left structurally intact.
 $cleanupRoots = @()
 if ($hive -eq 'SOFTWARE') {
 $cleanupRoots = @(
 "Registry::HKEY_LOCAL_MACHINE\$mountName\Microsoft\Windows\CurrentVersion\Explorer\MountPoints2"
 )
 }
 elseif ($hive -eq 'DEFAULT') {
 $cleanupRoots = @(
 "Registry::HKEY_LOCAL_MACHINE\$mountName\Software\Microsoft\Windows\CurrentVersion\Explorer\MountPoints2"
 )
 }

 $emptyRemoved = 0
 foreach ($root in $cleanupRoots) {
 if (-not (Test-Path -LiteralPath $root)) { continue }
 foreach ($child in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
 try {
 $subChildren = @(Get-ChildItem -LiteralPath $child.PSPath -ErrorAction SilentlyContinue)
 $item = Get-Item -LiteralPath $child.PSPath -ErrorAction Stop
 if ($subChildren.Count -eq 0 -and @($item.GetValueNames()).Count -eq 0) {
 Remove-Item -LiteralPath $child.PSPath -Recurse -Force -ErrorAction SilentlyContinue
 $emptyRemoved++
 }
 } catch { }
 }
 }

 if ($emptyRemoved -gt 0) {
 Write-Host " Targeted empty registry branches removed: $emptyRemoved" -ForegroundColor Green
 }
 else {
 Write-Host ' Targeted registry cleanup: no disposable empty branches found.' -ForegroundColor Gray
 }
 }
 finally {
 $saveExitCode = 1
 try {
 $saveExitCode = Invoke-NativeRegistryHiveSaveLatest -HiveName $mountName -DestinationPath $rebuiltHive
 }
 finally {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $mountName -Attempts 40 -DelayMilliseconds 250)) {
 throw "Could not unload Boot.wim hive HKLM\$mountName. Original $hive retained."
 }
 }
 }

 if ($saveExitCode -ne 0 -or -not (Test-Path -LiteralPath $rebuiltHive -PathType Leaf)) {
 Write-Warning "Native rebuild failed for Boot.wim hive $hive. Original retained."
 continue
 }

 $rebuiltSize = (Get-Item -LiteralPath $rebuiltHive -Force).Length
 if ($rebuiltSize -le 0) {
 Write-Warning "Rebuilt Boot.wim hive $hive is empty. Original retained."
 continue
 }

 & reg.exe load "HKLM\$validateName" $rebuiltHive >$null 2>&1
 $validationExitCode = $LASTEXITCODE
 $validationOK = ($validationExitCode -eq 0)
 if ($validationOK) {
 if (-not (Invoke-RegUnloadWithRetry -HiveName $validateName -Attempts 40 -DelayMilliseconds 250)) {
 throw "Could not unload Boot.wim validation hive HKLM\$validateName. Original $hive retained."
 }
 }

 if (-not $validationOK) {
 Write-Warning "Rebuilt Boot.wim hive $hive failed validation (reg.exe exit code $validationExitCode). Original retained."
 continue
 }

 if ($rebuiltSize -lt $originalSize) {
 Copy-Item -LiteralPath $rebuiltHive -Destination $sourceHive -Force -ErrorAction Stop
 $finalSize = (Get-Item -LiteralPath $sourceHive -Force).Length
 Write-Host (
 'BOOT HIVE COMPACTION {0}: {1:N2} MB -> {2:N2} MB | saved {3:N2} MB ({4:N1}%)' -f
 $hive,
 ($originalSize / 1MB),
 ($finalSize / 1MB),
 (($originalSize - $finalSize) / 1MB),
 ((($originalSize - $finalSize) / $originalSize) * 100)
 ) -ForegroundColor Green
 }
 else {
 Write-Host (
 'BOOT HIVE COMPACTION {0}: no smaller validated hive produced ({1:N2} MB -> {2:N2} MB); original retained.' -f
 $hive,
 ($originalSize / 1MB),
 ($rebuiltSize / 1MB)
 ) -ForegroundColor Yellow
 }
 }
 }
 finally {
 foreach ($hive in $hives) {
 [void](Invoke-RegUnloadWithRetry -HiveName "zBOOT_$hive" -Attempts 5 -DelayMilliseconds 100)
 [void](Invoke-RegUnloadWithRetry -HiveName "zBOOT_VALIDATE_$hive" -Attempts 5 -DelayMilliseconds 100)
 }
 if (Test-Path -LiteralPath $workRoot) {
 Remove-Item -LiteralPath $workRoot -Recurse -Force -ErrorAction SilentlyContinue
 }
 }
}
} *> $null


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "BOOT.WIM - REGISTRY HIVE CLEANUP + NATIVE HIVE COMPACTION" -ForegroundColor Cyan
Write-Host "  [Stage 1] 26.1 Clean BOOT.WIM registry content" -ForegroundColor Green
Write-Host "  [Stage 2] 26.2 Remove orphaned/obsolete entries" -ForegroundColor Yellow
Write-Host "  [Stage 3] 26.3 Compact BOOT.WIM registry hives" -ForegroundColor Gray
Write-Host "  [Stage 4] 26.4 Verify compacted hives" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
# ============================================================================
# SERVICING ORDER: ResetBase -> registry cleanup/compaction -> commit
# ============================================================================
# do not invoke Boot.wim /ResetBase here. The log showed this
# newly-added DISM operation returning exit code 50 after the earlier aggressive
# WinSxS/package manipulation. Keep the validated registry compaction and final
# WIM export, which do not depend on this failing cleanup call.

# Run Boot.wim registry cleanup/compaction while the image is still mounted.
Invoke-BootWimRegistryCleanupAndCompaction -WindowsRoot (Join-Path $mainOSDrive 'scratchdir\Windows')

# Remove only registry transaction logs after every hive has been cleanly
# unloaded and validated/replaced. Core hive files are never deleted.
Remove-OfflineRegistryHiveLogFiles -WindowsRoot (Join-Path $mainOSDrive 'scratchdir\Windows')
} *> $null
Write-Host 'BOOT.WIM registry hive cleanup + native hive compaction Completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "BOOT.WIM - COMMIT AND PHYSICAL WIM REBUILD" -ForegroundColor Cyan
Write-Host "  [Stage 1] 27.1 Commit BOOT.WIM changes" -ForegroundColor Cyan
Write-Host "  [Stage 2] 27.2 Unmount BOOT.WIM" -ForegroundColor Green
Write-Host "  [Stage 3] 27.3 Rebuild/export physical BOOT.WIM" -ForegroundColor Green
Write-Host "  [Stage 4] 27.4 Verify rebuilt BOOT.WIM" -ForegroundColor Yellow
Write-Host "  [Stage 5] 27.5 Install ESD final recovery compression" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Unmounting image..."
& 'dism' '/English' '/unmount-image' "/mountdir:$mainOSDrive\scratchdir" '/commit'
if ($LASTEXITCODE -ne 0) {
    throw "DISM failed to commit/unmount boot.wim. Exit code: $LASTEXITCODE"
}
# Rebuild boot.wim after cleanup. Exporting to a new WIM physically compacts the image and removes unused/deleted data.
Write-Host "Rebuilding boot.wim to physically reduce its size..."
$bootWim = "$mainOSDrive\Micro 11 Barebones\sources\boot.wim"
$bootWimRebuilt = "$mainOSDrive\Micro 11 Barebones\sources\boot_rebuilt.wim"
if (Test-Path $bootWimRebuilt) { Remove-Item -Path $bootWimRebuilt -Force -ErrorAction SilentlyContinue }
Write-Host "Exporting boot.wim with maximum compression. This may take a while..."
& 'dism.exe' '/English' '/Export-Image' `
 "/SourceImageFile:$bootWim" '/SourceIndex:1' `
 "/DestinationImageFile:$bootWimRebuilt" '/Compress:max' '/CheckIntegrity'
if ($LASTEXITCODE -ne 0 -or -not (Test-Path $bootWimRebuilt)) {
 Write-Host "ERROR: boot.wim rebuild failed. The original boot.wim has been retained."
 exit 1
}
Write-Host "Replacing original boot.wim with rebuilt boot.wim..."
Remove-Item -Path $bootWim -Force -ErrorAction Stop
Rename-Item -Path $bootWimRebuilt -NewName "boot.wim" -ErrorAction Stop
Write-Host "Boot.wim rebuild complete."
Write-Host "Final boot.wim information:"
& 'dism.exe' '/English' '/Get-WimInfo' "/WimFile:$bootWim"
} *> $null
Write-Host 'BOOT.WIM commit and physical WIM rebuild Completed...' -ForegroundColor Green

# Convert the final, compacted installation WIM to recovery-compressed ESD.
# Keep install.wim until the exported ESD passes DISM validation.
$finalSourcesDir = Join-Path $mainOSDrive 'Micro 11 Barebones\sources'
$finalInstallWim = Join-Path $finalSourcesDir 'install.wim'
$finalInstallEsd = Join-Path $finalSourcesDir 'install.esd'
$temporaryInstallEsd = Join-Path $finalSourcesDir 'install_build.esd'
if (-not (Test-Path -LiteralPath $finalInstallWim -PathType Leaf)) {
    throw "Cannot create install.esd: final install.wim not found at $finalInstallWim"
}
if (Test-Path -LiteralPath $temporaryInstallEsd) {
    Remove-Item -LiteralPath $temporaryInstallEsd -Force -ErrorAction Stop
}
# The preceding final WIM rebuild exports only $index, making its index 1.
& dism.exe /English /Export-Image "/SourceImageFile:$finalInstallWim" /SourceIndex:1 "/DestinationImageFile:$temporaryInstallEsd" /Compress:recovery /CheckIntegrity /Quiet 2>&1 | Out-Null
$esdExportExitCode = $LASTEXITCODE
if ($esdExportExitCode -ne 0 -or -not (Test-Path -LiteralPath $temporaryInstallEsd -PathType Leaf)) {
    throw "install.esd export failed (DISM exit code $esdExportExitCode). Original install.wim retained."
}
if ((Get-Item -LiteralPath $temporaryInstallEsd).Length -le 0) {
    throw 'install.esd export is empty. Original install.wim retained.'
}
& dism.exe /English /Get-WimInfo "/WimFile:$temporaryInstallEsd" /Index:1 /Quiet 2>&1 | Out-Null
$esdVerifyExitCode = $LASTEXITCODE
if ($esdVerifyExitCode -ne 0) {
    throw "install.esd verification failed (DISM exit code $esdVerifyExitCode). Original install.wim retained."
}
if (Test-Path -LiteralPath $finalInstallEsd) {
    Remove-Item -LiteralPath $finalInstallEsd -Force -ErrorAction Stop
}
Rename-Item -LiteralPath $temporaryInstallEsd -NewName 'install.esd' -ErrorAction Stop
if (-not (Wait-ForFileUnlock -Path $finalInstallWim -Attempts 40 -DelayMilliseconds 500)) {
    throw 'install.wim is locked. Verified install.esd retained; original install.wim was not deleted.'
}
Remove-Item -LiteralPath $finalInstallWim -Force -ErrorAction Stop
Write-Host 'Final install.esd created and verified; install.wim removed.' -ForegroundColor Green




