    "$mainOSDrive\Micro 11 Barebones\sources\upgrade_frmwrk.xml",
    "$mainOSDrive\Micro 11 Barebones\sources\upgradeagent.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\upgradeagent.xml",
    "$mainOSDrive\Micro 11 Barebones\sources\upgwow_bulk.xml",
    "$mainOSDrive\Micro 11 Barebones\sources\upgwowa32_bulk.xml",
    "$mainOSDrive\Micro 11 Barebones\sources\utcapi.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\uup",
    "$mainOSDrive\Micro 11 Barebones\sources\uxlib.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\uxlibres.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\vhdprovider.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\w32uiimg.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\w32uires.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\warning.gif",
    "$mainOSDrive\Micro 11 Barebones\sources\wdsclient.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdsclientapi.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdscommonlib.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdscore.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdscsl.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdsimage.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdstptc.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdsupgcompl.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wdsutil.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wimgapi.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\wimprovider.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\win32ui.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\windlp.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\winsetup.dll",
    "$mainOSDrive\Micro 11 Barebones\sources\winsetupboot.hiv",
    "$mainOSDrive\Micro 11 Barebones\sources\winsetupboot.sys",
    "$mainOSDrive\Micro 11 Barebones\sources\winsetupmon.hiv",
    "$mainOSDrive\Micro 11 Barebones\sources\winsetupmon.sys",
    "$mainOSDrive\Micro 11 Barebones\sources\wpx.dll"
) -Recurse -Force -ErrorAction SilentlyContinue
# Clear-Host suppressed so section headers remain visible.
} *> $null
Write-Host 'BOOT.WIM / setup media manual file cleanup Completed...' -ForegroundColor Green


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "ISO CREATION" -ForegroundColor Yellow
Write-Host "  [Stage 1] 29.1 Prepare ISO source tree" -ForegroundColor Green
Write-Host "  [Stage 2] 29.2 Build bootable ISO" -ForegroundColor Green
Write-Host "  [Stage 3] 29.3 Verify ISO output" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray

# Generate SetupComplete.cmd directly in the ISO OEM distribution folder.
# Windows Setup copies $OEM$\$$ to %WINDIR% during installation.
$setupCompleteDirectory = Join-Path $mainOSDrive 'Micro 11 Barebones\sources\$OEM$\$$\Setup\Scripts'
$setupCompleteDestination = Join-Path $setupCompleteDirectory 'SetupComplete.cmd'
$setupCompleteContent = @'
@echo off
compact /c /s /a /i /exe:lzx "C:\*"
del /q /f "%0"
'@
New-Item -ItemType Directory -Path $setupCompleteDirectory -Force -ErrorAction Stop | Out-Null
[System.IO.File]::WriteAllText($setupCompleteDestination, ($setupCompleteContent.TrimEnd("`r", "`n") + "`r`n"), [System.Text.Encoding]::ASCII)
Write-Host 'SetupComplete.cmd generated in ISO OEM Setup Scripts for installed OS Compact LZX compression.' -ForegroundColor Green

Write-Host "The Micro 11 Barebones image is now completed. Proceeding with the making of the ISO..."
Write-Host "Creating ISO image..."

$ADKDepTools = "C:\Program Files (x86)\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\$hostarchitecture\Oscdimg"
$localOSCDIMGPath = Join-Path $PSScriptRoot 'oscdimg.exe'
$OSCDIMG = $localOSCDIMGPath

if (-not (Test-Path -LiteralPath $localOSCDIMGPath -PathType Leaf)) {
    $adkOSCDIMGPath = Join-Path $ADKDepTools 'oscdimg.exe'
    try {
        if (Test-Path -LiteralPath $adkOSCDIMGPath -PathType Leaf) {
            Copy-Item -LiteralPath $adkOSCDIMGPath -Destination $localOSCDIMGPath -Force -ErrorAction Stop
            Write-Host 'Copied oscdimg.exe from the installed Windows ADK to the script folder.'
        }
        else {
            $url = 'https://msdl.microsoft.com/download/symbols/oscdimg.exe/3D44737265000/oscdimg.exe'
            $downloadPath = Join-Path $PSScriptRoot ('oscdimg.{0}.download' -f $PID)
            try {
                Write-Host 'Downloading oscdimg.exe to the script folder...'
                Invoke-WebRequest -Uri $url -OutFile $downloadPath -ErrorAction Stop
                $stream = [System.IO.File]::OpenRead($downloadPath)
                try {
                    if ($stream.Length -lt 1024 -or $stream.ReadByte() -ne 77 -or $stream.ReadByte() -ne 90) {
                        throw 'The downloaded file is not a valid Windows executable.'
                    }
                }
                finally { $stream.Dispose() }
                Move-Item -LiteralPath $downloadPath -Destination $localOSCDIMGPath -Force -ErrorAction Stop
            }
            finally {
                Remove-Item -LiteralPath $downloadPath -Force -ErrorAction SilentlyContinue
            }
        }
    }
    catch {
        throw ("ISO creation FAILED: Unable to obtain oscdimg.exe in the script folder. {0}" -f $_.Exception.Message)
    }
}

$isoSourcePath = Join-Path $mainOSDrive 'Micro 11 Barebones'
$isoOutputPath = Join-Path $PSScriptRoot 'Micro 11 Barebones.iso'
$oscdimgStdOut = Join-Path $env:TEMP ('Micro11_OSCDIMG_stdout_{0}.log' -f $PID)
$oscdimgStdErr = Join-Path $env:TEMP ('Micro11_OSCDIMG_stderr_{0}.log' -f $PID)
$oscdimgFailed = $false

try {
    if (-not (Test-Path -LiteralPath $OSCDIMG -PathType Leaf)) {
        throw "oscdimg.exe was not found at: $OSCDIMG"
    }
    if (-not (Test-Path -LiteralPath $isoSourcePath -PathType Container)) {
        throw "ISO source directory was not found: $isoSourcePath"
    }

    $biosBootFile = Join-Path $isoSourcePath 'boot\etfsboot.com'
    $uefiBootFile = Join-Path $isoSourcePath 'efi\microsoft\boot\efisys.bin'
    if (-not (Test-Path -LiteralPath $biosBootFile -PathType Leaf)) {
        throw "BIOS boot image was not found: $biosBootFile"
    }
    if (-not (Test-Path -LiteralPath $uefiBootFile -PathType Leaf)) {
        throw "UEFI boot image was not found: $uefiBootFile"
    }

    Remove-Item -LiteralPath $oscdimgStdOut, $oscdimgStdErr -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $isoOutputPath -Force -ErrorAction SilentlyContinue

    # A single argument string avoids Start-Process/ArgumentList quoting problems
    # with source/output paths containing spaces.
    $bootData = '-bootdata:2#p0,e,b"{0}"#pEF,e,b"{1}"' -f $biosBootFile, $uefiBootFile
    $oscdimgArgumentString = '-m -o -u2 -udfver102 -l"Micro 11 Barebones" {0} "{1}" "{2}"' -f `
        $bootData, $isoSourcePath, $isoOutputPath

    $oscdimgProcess = Start-Process `
        -FilePath $OSCDIMG `
        -ArgumentList $oscdimgArgumentString `
        -RedirectStandardOutput $oscdimgStdOut `
        -RedirectStandardError $oscdimgStdErr `
        -Wait `
        -PassThru `
        -WindowStyle Hidden `
        -ErrorAction Stop

    $oscdimgExitCode = [int]$oscdimgProcess.ExitCode
    if ($oscdimgExitCode -ne 0) {
        $details = @()
        foreach ($logPath in @($oscdimgStdErr, $oscdimgStdOut)) {
            if (Test-Path -LiteralPath $logPath -PathType Leaf) {
                $content = Get-Content -LiteralPath $logPath -Raw -ErrorAction SilentlyContinue
                if (-not [string]::IsNullOrWhiteSpace($content)) {
                    $details += $content.Trim()
                }
            }
        }
        if ($details.Count -gt 0) {
            throw ("OSCDIMG failed with exit code {0}.`n{1}" -f $oscdimgExitCode, ($details -join "`n"))
        }
        throw "OSCDIMG failed with exit code $oscdimgExitCode."
    }

    if (-not (Test-Path -LiteralPath $isoOutputPath -PathType Leaf)) {
        throw 'OSCDIMG returned exit code 0, but the output ISO was not created.'
    }

    $isoFile = Get-Item -LiteralPath $isoOutputPath -ErrorAction Stop
    if ($isoFile.Length -le 0) {
        throw 'OSCDIMG returned exit code 0, but the output ISO is empty.'
    }

    Remove-Item -LiteralPath $oscdimgStdOut, $oscdimgStdErr -Force -ErrorAction SilentlyContinue
    Write-Host ("ISO creation Completed... {0:N2} GB" -f ($isoFile.Length / 1GB)) -ForegroundColor Green
    Write-Host ("ISO: {0}" -f $isoFile.FullName) -ForegroundColor Green
}
catch {
    $oscdimgFailed = $true
    Write-Host ""
    Write-Host ("ISO creation FAILED: {0}" -f $_.Exception.Message) -ForegroundColor Red
    Write-Host 'The build has stopped before final working-file cleanup.' -ForegroundColor Red
    Write-Host ("ISO source tree preserved at: {0}" -f $isoSourcePath) -ForegroundColor Yellow
    if (Test-Path -LiteralPath $oscdimgStdErr -PathType Leaf) {
        Write-Host ("OSCDIMG stderr log preserved at: {0}" -f $oscdimgStdErr) -ForegroundColor Yellow
    }
    if (Test-Path -LiteralPath $oscdimgStdOut -PathType Leaf) {
        Write-Host ("OSCDIMG stdout log preserved at: {0}" -f $oscdimgStdOut) -ForegroundColor Yellow
    }
}

if ($oscdimgFailed) {
    try { Stop-Transcript | Out-Null } catch {}
    exit 1
}

# Continue automatically to final working-file cleanup

Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "FINAL WORKING-FILE CLEANUP" -ForegroundColor Green
Write-Host "  [Stage 1] 30.1 Remove temporary working files" -ForegroundColor Gray
Write-Host "  [Stage 2] 30.2 Remove temporary mount/servicing artifacts" -ForegroundColor Cyan
Write-Host "  [Stage 3] 30.3 Verify final workspace" -ForegroundColor Cyan
Write-Host "  [Stage 4] 30.4 Final completion" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones" -Recurse -Force >$null
Remove-Item -Path "$mainOSDrive\scratchdir" -Recurse -Force >$null
} *> $null
Write-Host "Final working-file cleanup Completed..." -ForegroundColor Cyan

# Stop the transcript
Stop-Transcript

exit
